-- ----------------------------------------------------------------------------
-- Shared trigger: keep updated_at honest
-- ----------------------------------------------------------------------------

create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

comment on function public.touch_updated_at() is
  'BEFORE UPDATE trigger that stamps updated_at. Attached to every mutable table.';

-- ==========================================================================
-- FILE 02/25  20261005000002_002_identity_roles.sql
-- ==========================================================================

-- Campus+ migration 002 — identity roles
-- Supabase CLI filename: 20261005000002_002_identity_roles.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 002 — identity, colleges, roles, permissions
-- =============================================================================
-- No passwords, no PRN. Identity comes from Supabase Auth (institutional email
-- OTP). This migration creates:
--
--   * colleges                    — the institution boundary + email allow-list
--   * profiles                    — PUBLIC identity (readable by members)
--   * profile_private             — private identity + account state (self/staff)
--   * roles/permissions/user_roles — the configurable authority model
--   * authorization helpers       — reused by every RLS policy in this schema
--
-- Splitting public and private identity at the table level (rather than relying
-- on column discipline in application code) is what makes "institutional email
-- must remain private" a database guarantee instead of a convention.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- colleges
-- ----------------------------------------------------------------------------

create table public.colleges (
  id            uuid primary key default gen_random_uuid(),
  name          text not null check (length(btrim(name)) between 2 and 120),
  short_name    text not null check (length(btrim(short_name)) between 2 and 40),
  slug          text not null unique check (slug ~ '^[a-z0-9-]{2,60}$'),
  email_domains text[] not null default '{}',
  city          text,
  is_active     boolean not null default true,
  settings      jsonb not null default '{}'::jsonb,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

create trigger colleges_touch before update on public.colleges
  for each row execute function public.touch_updated_at();

comment on table public.colleges is
  'Institutions served by this deployment. The initial deployment has exactly one (PCCOE); adding another college is a data change, not a code change.';

-- ----------------------------------------------------------------------------
-- Trusted-writer detection
-- ----------------------------------------------------------------------------
-- Maintenance scripts and definer functions legitimately bypass interactive
-- guards (bootstrapping the first Super Admin, system counters). PostgREST
-- exposes the JWT role as a request setting, and definer functions owned by
-- `postgres` see current_user = postgres.

-- The request's JWT context, as exposed by PostgREST. `current_user` is NOT
-- usable for this purpose: inside a SECURITY DEFINER function it is the function
-- owner, so it would make every guard think it was running as postgres.
create or replace function public.request_claims()
returns jsonb
language plpgsql
stable
as $$
begin
  return coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb;
exception when others then
  return '{}'::jsonb;
end;
$$;

create or replace function public.jwt_role()
returns text
language sql
stable
as $$
  select coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    nullif(public.request_claims()->>'role', '')
  );
$$;

create or replace function public.jwt_sub()
returns text
language sql
stable
as $$
  select coalesce(
    nullif(current_setting('request.jwt.claim.sub', true), ''),
    nullif(public.request_claims()->>'sub', '')
  );
$$;

-- Trusted writers are: requests made with the secret (service_role) key, and
-- direct privileged connections (maintenance scripts, migrations) that carry no
-- request claims at all. An interactive student request always carries claims.
create or replace function public.is_trusted_writer()
returns boolean
language sql
stable
as $$
  select public.jwt_role() = 'service_role'
      or (
        public.jwt_role() is null
        and public.jwt_sub() is null
        and session_user in ('postgres', 'service_role', 'supabase_admin', 'supabase_auth_admin')
      );
$$;

comment on function public.is_trusted_writer() is
  'True for secret-key requests and direct privileged connections. Used only to skip interactive guards, never to grant data access.';

-- ----------------------------------------------------------------------------
-- System-context marker
-- ----------------------------------------------------------------------------
-- SECURITY DEFINER functions that perform provisioning (creating the baseline
-- profile, for example) run with *user* claims present, so `is_trusted_writer()`
-- cannot recognise them. They set this transaction-local marker instead. It is
-- set only inside functions this repository owns — a client cannot set a GUC
-- through PostgREST — and `set_config(..., true)` means it never leaks past the
-- current transaction.

create or replace function public.in_system_context()
returns boolean
language sql
stable
as $$
  select coalesce(current_setting('campus.system_context', true), '') = 'on';
$$;

comment on function public.in_system_context() is
  'True while a Campus+ definer function is performing provisioning work.';

-- ----------------------------------------------------------------------------
-- profiles — public identity
-- ----------------------------------------------------------------------------

create table public.profiles (
  id                          uuid primary key default gen_random_uuid(),
  username                    text unique check (username ~ '^[a-z0-9_]{3,24}$'),
  display_name                text not null default '' check (length(display_name) <= 60),
  bio                         text check (bio is null or length(bio) <= 280),
  branch                      text check (branch is null or length(branch) <= 80),
  year                        text check (year is null or length(year) <= 40),
  division                    text check (division is null or length(division) <= 20),
  show_branch_year            boolean not null default true,
  allow_dms_from_everyone     boolean not null default true,
  reputation_score            numeric(4,2) not null default 0 check (reputation_score between 0 and 5),
  reputation_count            integer not null default 0 check (reputation_count >= 0),
  marketplace_completed_count integer not null default 0 check (marketplace_completed_count >= 0),
  created_at                  timestamptz not null default now(),
  updated_at                  timestamptz not null default now()
);

create unique index profiles_username_lower_idx on public.profiles (lower(username));
create index profiles_username_trgm_idx on public.profiles using gin (username gin_trgm_ops);
create index profiles_display_name_trgm_idx on public.profiles using gin (display_name gin_trgm_ops);

create trigger profiles_touch before update on public.profiles
  for each row execute function public.touch_updated_at();

comment on table public.profiles is
  'Public identity. Only these columns are ever returned to other students; username is the primary public identifier.';

-- ----------------------------------------------------------------------------
-- profile_private — private identity and account lifecycle
-- ----------------------------------------------------------------------------

create table public.profile_private (
  profile_id            uuid primary key references public.profiles (id) on delete cascade,
  auth_user_id          uuid not null unique references auth.users (id) on delete cascade,
  college_id            uuid not null references public.colleges (id) on delete restrict,
  -- The institutional email is deliberately NOT duplicated here. Supabase Auth
  -- (auth.users) is the only place it is stored: one copy, one blast radius.
  -- Duplicate-account prevention comes from auth.users.email being unique plus
  -- the one-profile-per-auth-user trigger on that table.
  account_status        public.account_status not null default 'active',
  status_reason         text,
  suspended_until       timestamptz,
  profile_completed     boolean not null default false,
  username_changed_at   timestamptz,
  last_seen             timestamptz,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  constraint profile_private_suspension_valid check (
    suspended_until is null or account_status in ('suspended', 'banned')
  )
);

create index profile_private_college_idx on public.profile_private (college_id);
create index profile_private_status_idx on public.profile_private (account_status);

create trigger profile_private_touch before update on public.profile_private
  for each row execute function public.touch_updated_at();

comment on table public.profile_private is
  'Private account state: college, status, suspension window, onboarding flags. Readable by the owner and by staff only. No email is stored here (spec §81, §86).';

-- ----------------------------------------------------------------------------
-- Username history — powers the configurable change cooldown
-- ----------------------------------------------------------------------------

create table public.username_history (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.profiles (id) on delete cascade,
  old_username text,
  new_username text not null,
  changed_by   uuid references public.profiles (id) on delete set null,
  changed_at   timestamptz not null default now()
);

create index username_history_user_idx on public.username_history (user_id, changed_at desc);
create unique index username_history_new_username_idx on public.username_history (lower(new_username));

-- ----------------------------------------------------------------------------
-- roles / permissions / role_permissions / user_roles
-- ----------------------------------------------------------------------------

create table public.roles (
  key         text primary key check (key ~ '^[a-z0-9_]{2,40}$'),
  label       text not null check (length(btrim(label)) between 2 and 60),
  description text,
  rank        integer not null default 0 check (rank between 0 and 1000),
  is_system   boolean not null default false,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create trigger roles_touch before update on public.roles
  for each row execute function public.touch_updated_at();

create table public.permissions (
  key         text primary key check (key ~ '^[a-z0-9_]{2,60}$'),
  label       text not null check (length(btrim(label)) between 2 and 80),
  description text,
  group_name  text not null default 'General',
  created_at  timestamptz not null default now()
);

create table public.role_permissions (
  role_key       text not null references public.roles (key) on delete cascade,
  permission_key text not null references public.permissions (key) on delete cascade,
  granted_at     timestamptz not null default now(),
  granted_by     uuid references public.profiles (id) on delete set null,
  primary key (role_key, permission_key)
);

create table public.user_roles (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles (id) on delete cascade,
  role_key   text not null references public.roles (key) on delete cascade,
  granted_by uuid references public.profiles (id) on delete set null,
  granted_at timestamptz not null default now(),
  expires_at timestamptz,
  unique (user_id, role_key)
);

create index user_roles_user_idx on public.user_roles (user_id);
-- Reverse lookups: "which students hold this role" (admin UI, audits) and
-- "which roles grant this permission" (permission editor).
create index user_roles_role_idx on public.user_roles (role_key);
create index role_permissions_role_idx on public.role_permissions (role_key);
create index role_permissions_permission_idx on public.role_permissions (permission_key);

-- ----------------------------------------------------------------------------
-- Authorization helpers
-- ----------------------------------------------------------------------------

create or replace function public.current_profile_id()
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select pp.profile_id from public.profile_private pp where pp.auth_user_id = auth.uid();
$$;

comment on function public.current_profile_id() is
  'profiles.id of the signed-in user, or null. Used by nearly every RLS policy.';

create or replace function public.account_status_of(p_profile uuid)
returns public.account_status
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select pp.account_status from public.profile_private pp where pp.profile_id = p_profile;
$$;

create or replace function public.current_account_status()
returns public.account_status
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.account_status_of(public.current_profile_id());
$$;

create or replace function public.is_active_profile(p_profile uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(public.account_status_of(p_profile) in ('active', 'pending'), false);
$$;

comment on function public.is_active_profile(uuid) is
  'Content visibility gate: suspended/banned/deactivated content stops being readable through RLS policies.';

create or replace function public.is_active_user()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.is_active_profile(public.current_profile_id());
$$;

comment on function public.is_active_user() is
  'FALSE for suspended/banned/deactivated/deleted accounts — enforced by RLS, not by hiding UI.';

create or replace function public.has_role(p_role text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.user_roles ur
    where ur.user_id = public.current_profile_id()
      and ur.role_key = p_role
      and (ur.expires_at is null or ur.expires_at > now())
  );
$$;

create or replace function public.has_permission(p_permission text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.is_active_user()
     and exists (
       select 1
       from public.user_roles ur
       join public.role_permissions rp on rp.role_key = ur.role_key
       where ur.user_id = public.current_profile_id()
         and rp.permission_key = p_permission
         and (ur.expires_at is null or ur.expires_at > now())
     );
$$;

comment on function public.has_permission(text) is
  'Central permission check. Mirrored in JavaScript by lib/permissions/authorization.js#can().';

create or replace function public.role_rank(p_profile uuid)
returns integer
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(max(r.rank), 0)
  from public.user_roles ur
  join public.roles r on r.key = ur.role_key
  where ur.user_id = p_profile
    and (ur.expires_at is null or ur.expires_at > now());
$$;

create or replace function public.current_role_rank()
returns integer
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.role_rank(public.current_profile_id());
$$;

create or replace function public.is_staff()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(public.current_role_rank() >= 10, false);
$$;

comment on function public.is_staff() is
  'True for Moderator (rank 10) and above. Students hold rank 0 and never display a role badge.';

create or replace function public.college_for_domain(p_domain text)
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select c.id
  from public.colleges c
  where c.is_active
    and exists (select 1 from unnest(c.email_domains) d where lower(d) = lower(p_domain))
  order by c.created_at
  limit 1;
$$;

-- ----------------------------------------------------------------------------
-- RLS — identity tables
-- ----------------------------------------------------------------------------

alter table public.colleges enable row level security;
alter table public.profiles enable row level security;
alter table public.profile_private enable row level security;
alter table public.username_history enable row level security;
alter table public.roles enable row level security;
alter table public.permissions enable row level security;
alter table public.role_permissions enable row level security;
alter table public.user_roles enable row level security;

-- colleges ------------------------------------------------------------------
create policy colleges_select_member on public.colleges
  for select to authenticated
  using (public.current_profile_id() is not null or public.has_permission('manage_colleges'));
create policy colleges_insert_owner on public.colleges
  for insert to authenticated with check (public.has_permission('manage_colleges'));
create policy colleges_update_owner on public.colleges
  for update to authenticated
  using (public.has_permission('manage_colleges'))
  with check (public.has_permission('manage_colleges'));
create policy colleges_delete_owner on public.colleges
  for delete to authenticated using (public.has_role('super_admin'));

-- profiles (public identity) -----------------------------------------------
-- Readable by every signed-in member: this is the public face of a student and
-- contains no private data.
create policy profiles_select_authenticated on public.profiles
  for select to authenticated using (true);
create policy profiles_insert_self on public.profiles
  for insert to authenticated with check (id = public.current_profile_id());
create policy profiles_update_self on public.profiles
  for update to authenticated
  using (id = public.current_profile_id())
  with check (id = public.current_profile_id());
create policy profiles_delete_admin on public.profiles
  for delete to authenticated using (public.has_permission('manage_users'));

-- profile_private -----------------------------------------------------------
create policy profile_private_select_self on public.profile_private
  for select to authenticated using (auth_user_id = auth.uid());
create policy profile_private_select_staff on public.profile_private
  for select to authenticated
  using (public.has_permission('manage_users') or public.has_permission('review_reports'));
create policy profile_private_insert_self on public.profile_private
  for insert to authenticated with check (auth_user_id = auth.uid());
create policy profile_private_update_self on public.profile_private
  for update to authenticated
  using (auth_user_id = auth.uid())
  with check (auth_user_id = auth.uid());
create policy profile_private_delete_admin on public.profile_private
  for delete to authenticated using (public.has_permission('manage_users'));

-- Field-level write control
-- ----------------------------------------------------------------------------
-- Which columns a client may write is decided by COLUMN PRIVILEGES, not by
-- triggers that undo values (see migration 015 for the full matrix):
--
--   profiles         → display_name, bio, branch, year, division, show_branch_year
--   profile_private  → allow_dms_from_everyone
--
-- Everything else — account status, moderation fields, counters, official flags —
-- is written only by SECURITY DEFINER functions that check permissions, rank and
-- legality first (migration 016). A student PATCH-ing `account_status` receives a
-- permission error from PostgreSQL, before any policy or trigger is consulted.

-- username_history ----------------------------------------------------------
create policy username_history_select_self on public.username_history
  for select to authenticated
  using (user_id = public.current_profile_id() or public.has_permission('manage_users'));
create policy username_history_insert_self on public.username_history
  for insert to authenticated with check (user_id = public.current_profile_id());

-- roles / permissions -------------------------------------------------------
create policy roles_select_all on public.roles
  for select to authenticated using (true);
create policy roles_manage on public.roles
  for all to authenticated
  using (public.has_permission('manage_roles'))
  with check (public.has_permission('manage_roles'));

create policy permissions_select_all on public.permissions
  for select to authenticated using (true);
create policy permissions_manage on public.permissions
  for all to authenticated
  using (public.has_permission('manage_permissions'))
  with check (public.has_permission('manage_permissions'));

create policy role_permissions_select_all on public.role_permissions
  for select to authenticated using (true);
create policy role_permissions_manage on public.role_permissions
  for all to authenticated
  using (public.has_permission('manage_permissions'))
  with check (public.has_permission('manage_permissions'));

-- user_roles ----------------------------------------------------------------
create policy user_roles_select_self on public.user_roles
  for select to authenticated using (user_id = public.current_profile_id());
create policy user_roles_select_staff on public.user_roles
  for select to authenticated
  using (public.has_permission('manage_users') or public.has_permission('assign_roles'));
create policy user_roles_insert_admin on public.user_roles
  for insert to authenticated with check (public.has_permission('assign_roles'));
create policy user_roles_update_admin on public.user_roles
  for update to authenticated
  using (public.has_permission('assign_roles'))
  with check (public.has_permission('assign_roles'));
create policy user_roles_delete_admin on public.user_roles
  for delete to authenticated using (public.has_permission('assign_roles'));

-- Privilege-escalation guard: nobody may grant or revoke at or above their own
-- rank, and the automatic student role cannot be touched by hand.
create or replace function public.prevent_privilege_escalation()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_role_key text := coalesce(new.role_key, old.role_key);
  v_target_rank integer;
begin
  if public.is_trusted_writer() or public.in_system_context() then
    return coalesce(new, old);
  end if;

  -- A cascade from an account deletion is not an interactive role change: by the
  -- time this fires the profile is already gone, so there is no privilege left to
  -- escalate. Without this, deleting an account (or any cascade into user_roles)
  -- would fail on the automatic student row.
  if tg_op = 'DELETE' and not exists (select 1 from public.profiles p where p.id = old.user_id) then
    return old;
  end if;

  if v_role_key = 'student' then
    raise exception 'The student role is assigned automatically and cannot be changed here.'
      using errcode = '42501';
  end if;

  select r.rank into v_target_rank from public.roles r where r.key = v_role_key;

  if coalesce(v_target_rank, 1000) >= public.current_role_rank() then
    raise exception 'You cannot grant or revoke a role at or above your own level.'
      using errcode = '42501';
  end if;

  if not public.has_permission('assign_roles') then
    raise exception 'You do not have permission to assign roles.' using errcode = '42501';
  end if;

  -- Every role change is audited, whether it came through grant_role()/revoke_role()
  -- or a direct write by an administrator (spec §59).
  if public.current_profile_id() is not null then
    perform public.log_audit(
      case when tg_op = 'DELETE' then 'admin.role_revoked' else 'admin.role_granted' end,
      'user', coalesce(new.user_id, old.user_id)::text,
      jsonb_build_object('role', v_role_key, 'direct', true),
      false, null, 'admin');
  end if;

  return coalesce(new, old);
end;
$$;

create trigger user_roles_no_escalation
  before insert or update or delete on public.user_roles
  for each row execute function public.prevent_privilege_escalation();

-- ----------------------------------------------------------------------------
-- Public profile projection
-- ----------------------------------------------------------------------------
-- `public_profiles` lives in migration 003 next to the block helpers it needs
-- (`is_blocked_with_current`), so that discovery can respect blocks from the
-- very first version of the view.

-- ==========================================================================
-- FILE 03/25  20261005000003_003_blocks.sql
-- ==========================================================================

-- Campus+ migration 003 — blocks
-- Supabase CLI filename: 20261005000003_003_blocks.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 003 — blocking and muting
-- =============================================================================
-- Blocking is a platform-wide primitive, so it lives before every content table
-- and its checks are reused by all of them (spec §60). A block is directional
-- in storage but symmetric in effect: either direction prevents interaction.
-- =============================================================================

create table public.blocks (
  id         uuid primary key default gen_random_uuid(),
  blocker_id uuid not null references public.profiles (id) on delete cascade,
  blocked_id uuid not null references public.profiles (id) on delete cascade,
  reason     text check (reason is null or length(reason) <= 300),
  created_at timestamptz not null default now(),
  constraint blocks_no_self check (blocker_id <> blocked_id),
  unique (blocker_id, blocked_id)
);

create index blocks_blocker_idx on public.blocks (blocker_id);
create index blocks_blocked_idx on public.blocks (blocked_id);

comment on table public.blocks is
  'Central block list. is_blocked() is used inside RLS policies so a blocked user cannot message, mention or interact even through a direct API call.';

create table public.mutes (
  id            uuid primary key default gen_random_uuid(),
  user_id       uuid not null references public.profiles (id) on delete cascade,
  muted_user_id uuid not null references public.profiles (id) on delete cascade,
  created_at    timestamptz not null default now(),
  constraint mutes_no_self check (user_id <> muted_user_id),
  unique (user_id, muted_user_id)
);

comment on table public.mutes is
  'Feed-level mute: hides a user''s posts from your feed without blocking direct messages.';

-- Both directions are queried: "who did I mute" and "who muted me".
create index mutes_user_idx on public.mutes (user_id);
create index mutes_muted_idx on public.mutes (muted_user_id);

-- ----------------------------------------------------------------------------
-- Helpers
-- ----------------------------------------------------------------------------

create or replace function public.is_blocked(a uuid, b uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select a is not null
     and b is not null
     and a <> b
     and exists (
       select 1 from public.blocks bl
       where (bl.blocker_id = a and bl.blocked_id = b)
          or (bl.blocker_id = b and bl.blocked_id = a)
     );
$$;

comment on function public.is_blocked(uuid, uuid) is
  'TRUE when either party has blocked the other. Used inside RLS policies for discovery, messaging and mentions.';

create or replace function public.is_blocked_with_current(p_profile uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.is_blocked(public.current_profile_id(), p_profile);
$$;

create or replace function public.is_muted_by_current(p_profile uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.mutes m
    where m.user_id = public.current_profile_id() and m.muted_user_id = p_profile
  );
$$;

-- ----------------------------------------------------------------------------
-- RLS
-- ----------------------------------------------------------------------------

alter table public.blocks enable row level security;
alter table public.mutes enable row level security;

-- A user sees and manages their own block list. Staff with moderation
-- permission may read blocks (they explain report context) but never edit them.
create policy blocks_select_own on public.blocks
  for select to authenticated using (blocker_id = public.current_profile_id());
create policy blocks_select_staff on public.blocks
  for select to authenticated using (public.has_permission('review_reports'));
create policy blocks_insert_own on public.blocks
  for insert to authenticated with check (blocker_id = public.current_profile_id() and public.is_active_user());
create policy blocks_delete_own on public.blocks
  for delete to authenticated using (blocker_id = public.current_profile_id());

create policy mutes_select_own on public.mutes
  for select to authenticated using (user_id = public.current_profile_id());
create policy mutes_insert_own on public.mutes
  for insert to authenticated with check (user_id = public.current_profile_id() and public.is_active_user());
create policy mutes_delete_own on public.mutes
  for delete to authenticated using (user_id = public.current_profile_id());

-- ----------------------------------------------------------------------------
-- Public profile projection
-- ----------------------------------------------------------------------------
create view public.public_profiles
with (security_invoker = true)
as
select
  p.id,
  p.username,
  p.display_name,
  p.bio,
  case when p.show_branch_year then p.branch else null end as branch,
  case when p.show_branch_year then p.year else null end as year,
  p.reputation_score,
  p.reputation_count,
  p.marketplace_completed_count,
  public.is_active_profile(p.id) as is_active,
  p.created_at
from public.profiles p
where p.username is not null
  -- Discovery respects blocks in both directions (spec §14, §60). The raw
  -- `profiles` table stays available so blocking, unblocking and moderation can
  -- still resolve the person involved.
  and not public.is_blocked_with_current(p.id);

comment on view public.public_profiles is
  'Public projection of profiles. Institutional email, auth ids and moderation state are structurally absent.';

-- ==========================================================================
-- FILE 04/25  20261005000004_004_communities.sql
-- ==========================================================================

-- Campus+ migration 004 — communities
-- Supabase CLI filename: 20261005000004_004_communities.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 004 — communities, study groups and clubs
-- =============================================================================
-- One membership + discussion + chat infrastructure serves three product
-- surfaces (spec §133, "Study Group → existing Community/Chat system"):
--
--   kind = 'community'    → Explore → Communities
--   kind = 'study_group'  → Explore → Study groups
--   kind = 'club'         → Campus → Clubs
--
-- Members can post discussions and chat; chat rooms are ordinary conversations
-- (migration 006) linked through `conversations.community_id`, so there is
-- exactly one messaging system.
-- =============================================================================

create table public.communities (
  id               uuid primary key default gen_random_uuid(),
  kind             public.community_kind not null default 'community',
  name             text not null check (length(btrim(name)) between 3 and 80),
  slug             text not null unique check (slug ~ '^[a-z0-9-]{3,60}$'),
  description      text not null check (length(description) between 10 and 1000),
  -- study-group specifics
  subject          text check (subject is null or length(subject) <= 120),
  branch           text check (branch is null or length(branch) <= 80),
  year             text check (year is null or length(year) <= 40),
  meeting_info     text check (meeting_info is null or length(meeting_info) <= 200),
  -- club specifics
  recruitment_info text check (recruitment_info is null or length(recruitment_info) <= 1000),
  contact_info     text check (contact_info is null or length(contact_info) <= 200),
  external_url     text check (external_url is null or external_url ~ '^https?://'),
  -- shared
  visibility       public.visibility_level not null default 'public',
  join_policy      text not null default 'open' check (join_policy in ('open', 'request', 'invite')),
  status           public.content_status not null default 'published',
  is_official      boolean not null default false,
  created_by       uuid not null references public.profiles (id) on delete restrict,
  approved_by      uuid references public.profiles (id) on delete set null,
  approved_at      timestamptz,
  member_count     integer not null default 1 check (member_count >= 0),
  post_count       integer not null default 0 check (post_count >= 0),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now()
);

create index communities_kind_idx on public.communities (kind, status);
create index communities_visibility_idx on public.communities (visibility);
create index communities_name_trgm_idx on public.communities using gin (name gin_trgm_ops);
create index communities_created_by_idx on public.communities (created_by);

create trigger communities_touch before update on public.communities
  for each row execute function public.touch_updated_at();

comment on table public.communities is
  'Communities, study groups and clubs share this table (kind discriminator) so membership, discussions and chat are one system.';

create table public.community_members (
  id           uuid primary key default gen_random_uuid(),
  community_id uuid not null references public.communities (id) on delete cascade,
  user_id      uuid not null references public.profiles (id) on delete cascade,
  role         public.community_role not null default 'member',
  status       text not null default 'active' check (status in ('active', 'pending', 'banned')),
  joined_at    timestamptz not null default now(),
  invited_by   uuid references public.profiles (id) on delete set null,
  unique (community_id, user_id)
);

create index community_members_user_idx on public.community_members (user_id, status);
create index community_members_community_idx on public.community_members (community_id, role);

comment on column public.community_members.role is
  'Community-level role only. It never implies platform authority (spec §21, §33).';

create table public.community_join_requests (
  id           uuid primary key default gen_random_uuid(),
  community_id uuid not null references public.communities (id) on delete cascade,
  user_id      uuid not null references public.profiles (id) on delete cascade,
  message      text check (message is null or length(message) <= 300),
  status       public.join_request_status not null default 'pending',
  decided_by   uuid references public.profiles (id) on delete set null,
  decided_at   timestamptz,
  created_at   timestamptz not null default now(),
  unique (community_id, user_id)
);

create index community_join_requests_community_idx on public.community_join_requests (community_id, status);
create index community_join_requests_user_idx on public.community_join_requests (user_id, created_at desc);

-- ----------------------------------------------------------------------------
-- Helpers
-- ----------------------------------------------------------------------------

create or replace function public.community_kind_of(p_community uuid)
returns public.community_kind
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select c.kind from public.communities c where c.id = p_community;
$$;

create or replace function public.is_community_member(p_community uuid, p_user uuid default null)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.community_members m
    join public.communities c on c.id = m.community_id
    where m.community_id = p_community
      and m.user_id = coalesce(p_user, public.current_profile_id())
      and m.status = 'active'
      and c.status = 'published'
  );
$$;

create or replace function public.is_community_moderator(p_community uuid, p_user uuid default null)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.community_members m
    where m.community_id = p_community
      and m.user_id = coalesce(p_user, public.current_profile_id())
      and m.status = 'active'
      and m.role in ('owner', 'moderator')
  );
$$;

create or replace function public.can_view_community(p_community uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.communities c
    where c.id = p_community
      and c.status = 'published'
      and (
        c.visibility in ('public', 'campus')
        or public.is_community_member(c.id)
        or public.has_permission('moderate_communities')
        or public.has_permission('moderate_all')
      )
  );
$$;

comment on function public.can_view_community(uuid) is
  'Visibility gate reused by community, post, discussion and chat policies.';

create or replace function public.can_post_in_community(p_community uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select public.can_view_community(p_community)
     and (
       public.is_community_member(p_community)
       or public.has_permission('moderate_communities')
       or public.has_permission('moderate_all')
     );
$$;

-- ----------------------------------------------------------------------------
-- Counters (definer triggers: the caller cannot inflate them directly)
-- ----------------------------------------------------------------------------

-- The creator becomes the owner automatically. Done in a definer trigger so the
-- client cannot forget it, and so a student never needs an elevated policy to
-- create their own membership row.
create or replace function public.add_community_owner()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.community_members (community_id, user_id, role, status)
  values (new.id, new.created_by, 'owner', 'active')
  on conflict (community_id, user_id) do update set role = 'owner', status = 'active';
  return new;
end;
$$;

create trigger communities_add_owner
  after insert on public.communities
  for each row execute function public.add_community_owner();

-- Community counters are derived truth. The owner may edit the public
-- presentation of their space; ownership, official status and counters are
-- recomputed or protected instead of trusted.
create or replace function public.guard_community_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_trusted_writer() then
    new.member_count := (
      select count(*) from public.community_members m
      where m.community_id = old.id and m.status = 'active'
    );
    new.post_count := (
      select count(*) from public.posts p
      where p.community_id = old.id and p.status = 'published' and p.deleted_at is null
    );
    new.created_by := old.created_by;
    new.kind := old.kind;
    new.is_official := old.is_official;
    new.approved_by := old.approved_by;
    new.approved_at := old.approved_at;
  end if;
  return new;
end;
$$;

create trigger communities_guard_update
  before update on public.communities
  for each row execute function public.guard_community_update();

create or replace function public.sync_community_member_count()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_community uuid := coalesce(new.community_id, old.community_id);
begin
  update public.communities c
     set member_count = (
       select count(*) from public.community_members m
       where m.community_id = v_community and m.status = 'active'
     )
   where c.id = v_community;
  return coalesce(new, old);
end;
$$;

create trigger community_members_count
  after insert or update or delete on public.community_members
  for each row execute function public.sync_community_member_count();

-- ----------------------------------------------------------------------------
-- RLS
-- ----------------------------------------------------------------------------

alter table public.communities enable row level security;
alter table public.community_members enable row level security;
alter table public.community_join_requests enable row level security;

-- communities ---------------------------------------------------------------
-- `created_by = current_profile_id()` matters for two reasons:
--   1. a creator must always see the space they just made, even if it is private;
--   2. PostgreSQL applies the SELECT policy to rows returned by INSERT ... RETURNING
--      (PostgREST does this on every insert), and `can_view_community(id)` reads
--      this same table, so the newly inserted row is not yet visible to it.
create policy communities_select_visible on public.communities
  for select to authenticated
  using (public.can_view_community(id) or created_by = public.current_profile_id());

create policy communities_insert_own on public.communities
  for insert to authenticated
  with check (
    public.is_active_user()
    and created_by = public.current_profile_id()
    and (
      (kind = 'community' and public.has_permission('create_communities'))
      or (kind = 'study_group' and public.has_permission('create_communities'))
      or (kind = 'club' and public.has_permission('manage_clubs'))
    )
  );

-- Owner may edit the public presentation of their space; staff may moderate it.
create policy communities_update_owner on public.communities
  for update to authenticated
  using (public.is_community_moderator(id) and public.is_active_user())
  with check (public.is_community_moderator(id));
create policy communities_update_staff on public.communities
  for update to authenticated
  using (public.has_permission('moderate_communities') or public.has_permission('moderate_all'))
  with check (public.has_permission('moderate_communities') or public.has_permission('moderate_all'));

create policy communities_delete_owner on public.communities
  for delete to authenticated
  using (created_by = public.current_profile_id() or public.has_permission('moderate_all'));

-- community_members ---------------------------------------------------------
create policy community_members_select_member on public.community_members
  for select to authenticated
  using (
    user_id = public.current_profile_id()
    or public.is_community_member(community_id)
    or public.has_permission('moderate_communities')
  );

create policy community_members_insert_self on public.community_members
  for insert to authenticated
  with check (
    user_id = public.current_profile_id()
    and public.is_active_user()
    and exists (
      select 1 from public.communities c
      where c.id = community_id
        and c.status = 'published'
        and c.join_policy = 'open'
        and c.visibility in ('public', 'campus')
    )
  );

-- Owners/moderators of a space may add members (invite flows) within their own
-- space only.
create policy community_members_insert_managers on public.community_members
  for insert to authenticated
  with check (public.is_community_moderator(community_id));

create policy community_members_update_managers on public.community_members
  for update to authenticated
  using (public.is_community_moderator(community_id) or public.has_permission('moderate_communities'))
  with check (public.is_community_moderator(community_id) or public.has_permission('moderate_communities'));

create policy community_members_delete_self on public.community_members
  for delete to authenticated using (user_id = public.current_profile_id());
create policy community_members_delete_managers on public.community_members
  for delete to authenticated
  using (public.is_community_moderator(community_id) or public.has_permission('moderate_communities'));

-- A member may not promote themselves: role changes are restricted to managers
-- and to owners for the owner role.
create or replace function public.guard_community_role_change()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if public.is_trusted_writer() then
    return new;
  end if;
  if new.role is distinct from old.role then
    if not public.is_community_moderator(new.community_id) then
      raise exception 'Only community owners and moderators can change member roles.'
        using errcode = '42501';
    end if;
    if new.role = 'owner' and not exists (
      select 1 from public.community_members m
      where m.community_id = new.community_id
        and m.user_id = public.current_profile_id()
        and m.role = 'owner'
    ) then
      raise exception 'Only an owner can transfer ownership.' using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

create trigger community_members_guard_role
  before update on public.community_members
  for each row execute function public.guard_community_role_change();

-- community_join_requests --------------------------------------------------
create policy community_join_requests_select on public.community_join_requests
  for select to authenticated
  using (
    user_id = public.current_profile_id()
    or public.is_community_moderator(community_id)
    or public.has_permission('moderate_communities')
  );

create policy community_join_requests_insert_self on public.community_join_requests
  for insert to authenticated
  with check (
    user_id = public.current_profile_id()
    and public.is_active_user()
    and exists (
      select 1 from public.communities c
      where c.id = community_id and c.status = 'published' and c.join_policy = 'request'
    )
  );

create policy community_join_requests_decide on public.community_join_requests
  for update to authenticated
  using (public.is_community_moderator(community_id))
  with check (public.is_community_moderator(community_id));

create policy community_join_requests_cancel on public.community_join_requests
  for delete to authenticated using (user_id = public.current_profile_id());

-- ==========================================================================
-- FILE 05/25  20261005000005_005_social.sql
-- ==========================================================================

-- Campus+ migration 005 — social
-- Supabase CLI filename: 20261005000005_005_social.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 005 — posts, discussions, polls, comments, reactions, mentions
-- =============================================================================
-- Text-first by construction: `body` is text, `gif` is a validated JSONB
-- reference to an external GIPHY asset, and there is deliberately no column,
-- bucket or policy that could hold an uploaded file (spec §3, §89).
-- =============================================================================

-- ----------------------------------------------------------------------------
-- posts (also serves discussions and polls through `kind`)
-- ----------------------------------------------------------------------------

create table public.posts (
  id                 uuid primary key default gen_random_uuid(),
  author_id          uuid not null references public.profiles (id) on delete cascade,
  kind               public.post_kind not null default 'post',
  title              text check (title is null or length(title) between 5 and 140),
  body               text not null check (length(btrim(body)) between 1 and 2000),
  gif                jsonb,
  community_id       uuid references public.communities (id) on delete cascade,
  visibility         public.visibility_level not null default 'public',
  status             public.content_status not null default 'published',
  is_official        boolean not null default false,
  pinned             boolean not null default false,
  poll_closes_at     timestamptz,
  comment_count      integer not null default 0 check (comment_count >= 0),
  reaction_count     integer not null default 0 check (reaction_count >= 0),
  moderated_by       uuid references public.profiles (id) on delete set null,
  moderated_at       timestamptz,
  moderation_reason  text,
  deleted_at         timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now(),
  search_vector      tsvector generated always as (
    to_tsvector(
      'english'::regconfig,
      coalesce(title, '') || ' ' || coalesce(body, '')
    )
  ) stored,
  constraint posts_kind_title check (kind = 'post' or (title is not null and length(btrim(title)) >= 5)),
  constraint posts_community_visibility check (
    (community_id is null and visibility in ('public', 'campus'))
    or community_id is not null
  ),
  constraint posts_gif_provider check (
    gif is null or (gif->>'provider') = 'giphy'
  ),
  constraint posts_gif_url_host check (
    gif is null or (gif->>'url') ~ '^https://(media[0-9]?\.)?giphy\.com/'
  )
);

create index posts_feed_idx on public.posts (status, created_at desc) where community_id is null;
create index posts_community_idx on public.posts (community_id, created_at desc);
create index posts_author_idx on public.posts (author_id, created_at desc);
create index posts_kind_idx on public.posts (kind, created_at desc);
create index posts_search_idx on public.posts using gin (search_vector);
create index posts_recent_activity_idx on public.posts (updated_at desc);

create trigger posts_touch before update on public.posts
  for each row execute function public.touch_updated_at();

comment on table public.posts is
  'Text-first posts, discussions (kind=discussion) and polls (kind=poll). No attachments exist by design.';

-- Keep author-editable columns separate from moderation columns. A student
-- editing their own post can never change its status, official badge, counters
-- or moderation metadata.
create or replace function public.guard_post_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  -- Counters are derived truth, never client input: they are recomputed from the
  -- rows that produce them, for every writer that is not an operator script.
  if not public.is_trusted_writer() then
    new.comment_count := (
      select count(*) from public.comments c
      where c.post_id = old.id and c.status = 'published' and c.deleted_at is null
    );
    new.reaction_count := (
      select count(*) from public.reactions r
      where r.target_type = 'post' and r.target_id = old.id
    );
  end if;

  if public.is_trusted_writer()
     or public.has_permission('remove_posts')
     or public.has_permission('moderate_all') then
    return new;
  end if;

  new.status            := old.status;
  new.is_official       := old.is_official;
  new.pinned            := old.pinned;
  new.author_id         := old.author_id;
  new.community_id      := old.community_id;
  new.kind              := old.kind;
  new.moderated_by      := old.moderated_by;
  new.moderated_at      := old.moderated_at;
  new.moderation_reason := old.moderation_reason;
  return new;
end;
$$;

create trigger posts_guard_update
  before update on public.posts
  for each row execute function public.guard_post_update();

-- ----------------------------------------------------------------------------
-- poll_options / poll_votes
-- ----------------------------------------------------------------------------

create table public.poll_options (
  id         uuid primary key default gen_random_uuid(),
  post_id    uuid not null references public.posts (id) on delete cascade,
  label      text not null check (length(btrim(label)) between 1 and 120),
  position   integer not null default 0,
  vote_count integer not null default 0 check (vote_count >= 0),
  unique (post_id, position)
);

-- No separate (post_id) index: the unique (post_id, position) constraint already
-- serves lookups by post_id as a prefix.

create table public.poll_votes (
  id         uuid primary key default gen_random_uuid(),
  post_id    uuid not null references public.posts (id) on delete cascade,
  option_id  uuid not null references public.poll_options (id) on delete cascade,
  user_id    uuid not null references public.profiles (id) on delete cascade,
  created_at timestamptz not null default now(),
  unique (post_id, user_id)
);

create index poll_votes_post_idx on public.poll_votes (post_id);
create index poll_votes_option_idx on public.poll_votes (option_id);
create index poll_votes_user_idx on public.poll_votes (user_id);

comment on table public.poll_votes is
  'One row per voter per poll — duplicate voting is impossible at the schema level.';

-- ----------------------------------------------------------------------------
-- comments
-- ----------------------------------------------------------------------------

create table public.comments (
  id                uuid primary key default gen_random_uuid(),
  post_id           uuid not null references public.posts (id) on delete cascade,
  author_id         uuid not null references public.profiles (id) on delete cascade,
  parent_id         uuid references public.comments (id) on delete cascade,
  body              text not null check (length(btrim(body)) between 1 and 1000),
  gif               jsonb,
  status            public.content_status not null default 'published',
  reaction_count    integer not null default 0 check (reaction_count >= 0),
  moderated_by      uuid references public.profiles (id) on delete set null,
  moderated_at      timestamptz,
  moderation_reason text,
  deleted_at        timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  constraint comments_gif_provider check (gif is null or (gif->>'provider') = 'giphy'),
  constraint comments_gif_url_host check (
    gif is null or (gif->>'url') ~ '^https://(media[0-9]?\.)?giphy\.com/'
  )
);

create index comments_post_idx on public.comments (post_id, created_at);
create index comments_author_idx on public.comments (author_id);
create index comments_parent_idx on public.comments (parent_id);

create trigger comments_touch before update on public.comments
  for each row execute function public.touch_updated_at();

create or replace function public.guard_comment_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_trusted_writer() then
    new.reaction_count := (
      select count(*) from public.reactions r
      where r.target_type = 'comment' and r.target_id = old.id
    );
  end if;

  if public.is_trusted_writer()
     or public.has_permission('remove_comments')
     or public.has_permission('moderate_all') then
    return new;
  end if;

  new.status            := old.status;
  new.author_id         := old.author_id;
  new.post_id           := old.post_id;
  new.parent_id         := old.parent_id;
  new.moderated_by      := old.moderated_by;
  new.moderated_at      := old.moderated_at;
  new.moderation_reason := old.moderation_reason;
  return new;
end;
$$;

create trigger comments_guard_update
  before update on public.comments
  for each row execute function public.guard_comment_update();

-- ----------------------------------------------------------------------------
-- reactions (posts and comments)
-- ----------------------------------------------------------------------------

create table public.reactions (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.profiles (id) on delete cascade,
  target_type text not null check (target_type in ('post', 'comment')),
  target_id   uuid not null,
  kind        public.reaction_kind not null default 'like',
  created_at  timestamptz not null default now(),
  unique (user_id, target_type, target_id)
);

create index reactions_target_idx on public.reactions (target_type, target_id);
create index reactions_user_idx on public.reactions (user_id, created_at desc);

comment on table public.reactions is
  'One reaction per user per item. target_type validates the polymorphic reference; target_id is checked by the RLS policies of the parent table.';

-- ----------------------------------------------------------------------------
-- mentions
-- ----------------------------------------------------------------------------

create table public.mentions (
  id                uuid primary key default gen_random_uuid(),
  mentioned_user_id uuid not null references public.profiles (id) on delete cascade,
  actor_id          uuid not null references public.profiles (id) on delete cascade,
  source_type       text not null check (source_type in ('post', 'comment', 'message', 'community_post')),
  source_id         uuid not null,
  created_at        timestamptz not null default now(),
  unique (mentioned_user_id, source_type, source_id)
);

create index mentions_user_idx on public.mentions (mentioned_user_id, created_at desc);
create index mentions_source_idx on public.mentions (source_type, source_id);
create index mentions_actor_idx on public.mentions (actor_id);

-- ----------------------------------------------------------------------------
-- Counters
-- ----------------------------------------------------------------------------

create or replace function public.sync_post_counts()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_post uuid := coalesce(new.post_id, old.post_id);
begin
  update public.posts p
     set comment_count = (
       select count(*) from public.comments c
       where c.post_id = v_post and c.status = 'published' and c.deleted_at is null
     )
   where p.id = v_post;
  return coalesce(new, old);
end;
$$;

create trigger comments_sync_post_counts
  after insert or update or delete on public.comments
  for each row execute function public.sync_post_counts();

create or replace function public.sync_reaction_counts()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_target_type text := coalesce(new.target_type, old.target_type);
  v_target uuid := coalesce(new.target_id, old.target_id);
  v_total integer;
begin
  select count(*) into v_total from public.reactions r
   where r.target_type = v_target_type and r.target_id = v_target;

  if v_target_type = 'post' then
    update public.posts set reaction_count = v_total where id = v_target;
  else
    update public.comments set reaction_count = v_total where id = v_target;
  end if;
  return coalesce(new, old);
end;
$$;

create trigger reactions_sync_counts
  after insert or update or delete on public.reactions
  for each row execute function public.sync_reaction_counts();

-- Poll option vote counts are derived truth as well.
create or replace function public.guard_poll_option_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_trusted_writer() then
    new.vote_count := (select count(*) from public.poll_votes v where v.option_id = old.id);
    new.post_id := old.post_id;
    new.position := old.position;
  end if;
  return new;
end;
$$;

create trigger poll_options_guard_update
  before update on public.poll_options
  for each row execute function public.guard_poll_option_update();

create or replace function public.sync_poll_option_counts()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_option uuid := coalesce(new.option_id, old.option_id);
begin
  update public.poll_options o
     set vote_count = (select count(*) from public.poll_votes v where v.option_id = v_option)
   where o.id = v_option;
  return coalesce(new, old);
end;
$$;

create trigger poll_votes_sync_counts
  after insert or update or delete on public.poll_votes
  for each row execute function public.sync_poll_option_counts();

-- ----------------------------------------------------------------------------
-- RLS
-- ----------------------------------------------------------------------------

alter table public.posts enable row level security;
alter table public.poll_options enable row level security;
alter table public.poll_votes enable row level security;
alter table public.comments enable row level security;
alter table public.reactions enable row level security;
alter table public.mentions enable row level security;

-- posts ---------------------------------------------------------------------
create policy posts_select_visible on public.posts
  for select to authenticated
  using (
    status = 'published'
    and deleted_at is null
    and public.is_active_profile(author_id)
    and not public.is_blocked_with_current(author_id)
    and not public.is_muted_by_current(author_id)
    and (
      (community_id is null and visibility in ('public', 'campus'))
      or (community_id is not null and public.can_view_community(community_id))
    )
  );

create policy posts_select_author on public.posts
  for select to authenticated using (author_id = public.current_profile_id());

create policy posts_select_staff on public.posts
  for select to authenticated
  using (public.has_permission('remove_posts') or public.has_permission('moderate_all'));

create policy posts_insert_own on public.posts
  for insert to authenticated
  with check (
    author_id = public.current_profile_id()
    and public.is_active_user()
    and public.has_permission('create_posts')
    and public.is_active_profile(author_id)
    and status in ('published', 'pending')
    and (is_official = false or public.has_permission('manage_notices'))
    and (community_id is null or public.can_post_in_community(community_id))
    and (kind <> 'poll' or public.has_permission('create_polls'))
  );

create policy posts_update_author on public.posts
  for update to authenticated
  using (author_id = public.current_profile_id() and public.is_active_user())
  with check (author_id = public.current_profile_id());

create policy posts_update_staff on public.posts
  for update to authenticated
  using (public.has_permission('remove_posts') or public.has_permission('moderate_all'))
  with check (public.has_permission('remove_posts') or public.has_permission('moderate_all'));

create policy posts_delete_author on public.posts
  for delete to authenticated using (author_id = public.current_profile_id());
create policy posts_delete_staff on public.posts
  for delete to authenticated
  using (public.has_permission('remove_posts') or public.has_permission('moderate_all'));

-- poll_options --------------------------------------------------------------
create policy poll_options_select_visible on public.poll_options
  for select to authenticated
  using (exists (select 1 from public.posts p where p.id = post_id));

create policy poll_options_insert_author on public.poll_options
  for insert to authenticated
  with check (
    exists (
      select 1 from public.posts p
      where p.id = post_id
        and p.author_id = public.current_profile_id()
        and p.kind = 'poll'
        and p.created_at > now() - interval '5 minutes'
    )
  );

create policy poll_options_update_author on public.poll_options
  for update to authenticated
  using (exists (select 1 from public.posts p where p.id = post_id and p.author_id = public.current_profile_id()))
  with check (exists (select 1 from public.posts p where p.id = post_id and p.author_id = public.current_profile_id()));

-- poll_votes ----------------------------------------------------------------
create policy poll_votes_select_visible on public.poll_votes
  for select to authenticated
  using (exists (select 1 from public.posts p where p.id = post_id));

create policy poll_votes_insert_self on public.poll_votes
  for insert to authenticated
  with check (
    user_id = public.current_profile_id()
    and public.is_active_user()
    and exists (
      select 1 from public.posts p
      where p.id = post_id
        and p.kind = 'poll'
        and p.status = 'published'
        and (p.poll_closes_at is null or p.poll_closes_at > now())
        and p.author_id <> public.current_profile_id()
    )
    and not exists (
      select 1 from public.posts p2
      where p2.id = post_id and public.is_blocked_with_current(p2.author_id)
    )
  );

create policy poll_votes_delete_self on public.poll_votes
  for delete to authenticated using (user_id = public.current_profile_id());

-- comments ------------------------------------------------------------------
create policy comments_select_visible on public.comments
  for select to authenticated
  using (
    status = 'published'
    and deleted_at is null
    and public.is_active_profile(author_id)
    and not public.is_blocked_with_current(author_id)
    and exists (
      select 1 from public.posts p
      where p.id = post_id
        and p.status = 'published'
        and public.is_active_profile(p.author_id)
        and not public.is_blocked_with_current(p.author_id)
        and (
          (p.community_id is null and p.visibility in ('public', 'campus'))
          or (p.community_id is not null and public.can_view_community(p.community_id))
        )
    )
  );

create policy comments_select_author on public.comments
  for select to authenticated using (author_id = public.current_profile_id());

create policy comments_select_staff on public.comments
  for select to authenticated
  using (public.has_permission('remove_comments') or public.has_permission('moderate_all'));

create policy comments_insert_own on public.comments
  for insert to authenticated
  with check (
    author_id = public.current_profile_id()
    and public.is_active_user()
    and public.has_permission('create_comments')
    and status in ('published', 'pending')
    and exists (
      select 1 from public.posts p
      where p.id = post_id
        and p.status = 'published'
        and p.deleted_at is null
        and public.is_active_profile(p.author_id)
        and not public.is_blocked_with_current(p.author_id)
        and (
          (p.community_id is null and p.visibility in ('public', 'campus'))
          or (p.community_id is not null and public.can_view_community(p.community_id))
        )
    )
  );

create policy comments_update_author on public.comments
  for update to authenticated
  using (author_id = public.current_profile_id() and public.is_active_user())
  with check (author_id = public.current_profile_id());

create policy comments_update_staff on public.comments
  for update to authenticated
  using (public.has_permission('remove_comments') or public.has_permission('moderate_all'))
  with check (public.has_permission('remove_comments') or public.has_permission('moderate_all'));

create policy comments_delete_author on public.comments
  for delete to authenticated using (author_id = public.current_profile_id());
create policy comments_delete_staff on public.comments
  for delete to authenticated
  using (public.has_permission('remove_comments') or public.has_permission('moderate_all'));

-- reactions -----------------------------------------------------------------
create policy reactions_select_visible on public.reactions
  for select to authenticated
  using (
    case target_type
      when 'post' then exists (select 1 from public.posts p where p.id = target_id)
      else exists (select 1 from public.comments c where c.id = target_id)
    end
  );

create policy reactions_insert_self on public.reactions
  for insert to authenticated
  with check (
    user_id = public.current_profile_id()
    and public.is_active_user()
    and public.has_permission('react_content')
    and case target_type
      when 'post' then exists (
        select 1 from public.posts p
        where p.id = target_id and p.status = 'published' and not public.is_blocked_with_current(p.author_id)
      )
      else exists (
        select 1 from public.comments c
        where c.id = target_id and c.status = 'published' and not public.is_blocked_with_current(c.author_id)
      )
    end
  );

create policy reactions_update_self on public.reactions
  for update to authenticated
  using (user_id = public.current_profile_id())
  with check (user_id = public.current_profile_id());

create policy reactions_delete_self on public.reactions
  for delete to authenticated using (user_id = public.current_profile_id());

-- mentions ------------------------------------------------------------------
create policy mentions_select_own on public.mentions
  for select to authenticated
  using (mentioned_user_id = public.current_profile_id() or actor_id = public.current_profile_id());

create policy mentions_insert_actor on public.mentions
  for insert to authenticated
  with check (
    actor_id = public.current_profile_id()
    and public.is_active_user()
    and not public.is_blocked(actor_id, mentioned_user_id)
    and public.is_active_profile(mentioned_user_id)
  );

-- ----------------------------------------------------------------------------
-- Convenience: one call that records a post's mentions.
-- Runs as definer so a mention can only be recorded for a real, unblocked,
-- active user — the same checks the policy above performs.
-- ----------------------------------------------------------------------------

create or replace function public.record_mentions(
  p_source_type text,
  p_source_id uuid,
  p_usernames text[]
)
returns table (user_id uuid, username text, display_name text)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_name text;
begin
  if v_actor is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  foreach v_name in array coalesce(p_usernames, '{}'::text[])
  loop
    insert into public.mentions (mentioned_user_id, actor_id, source_type, source_id)
    select p.id, v_actor, p_source_type, p_source_id
    from public.profiles p
    where p.username = lower(ltrim(v_name, '@'))
      and p.id <> v_actor
      and public.is_active_profile(p.id)
      and not public.is_blocked(v_actor, p.id)
    on conflict (mentioned_user_id, source_type, source_id) do nothing;
  end loop;

  return query
    select m.mentioned_user_id, p.username, p.display_name
    from public.mentions m
    join public.profiles p on p.id = m.mentioned_user_id
    where m.source_type = p_source_type and m.source_id = p_source_id;
end;
$$;

comment on function public.record_mentions(text, uuid, text[]) is
  'Records @mentions for a post/comment/message. Blocks and inactive accounts are filtered server-side.';

-- ==========================================================================
-- FILE 06/25  20261005000006_006_moderation_core.sql
-- ==========================================================================

-- Campus+ migration 006 — moderation core
-- Supabase CLI filename: 20261005000006_006_moderation_core.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 006 — reporting, moderation trail, audit logs, notifications
-- =============================================================================
-- Built before the product modules on purpose: every feature reports through
-- this one system, moderates through this one trail and notifies through this
-- one table (spec §53, §57, §59, §133).
--
-- Write paths for notifications and audit logs are SECURITY DEFINER functions,
-- so a client cannot forge an audit record, spoof the actor, or push a
-- notification to an arbitrary user.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- reports
-- ----------------------------------------------------------------------------

create table public.reports (
  id                 uuid primary key default gen_random_uuid(),
  reporter_id        uuid not null references public.profiles (id) on delete cascade,
  target_type        public.report_target_type not null,
  target_id          uuid not null,
  reason             text not null check (reason in (
                       'spam', 'harassment', 'hate', 'nudity', 'violence', 'scam',
                       'misinformation', 'impersonation', 'academic_dishonesty',
                       'privacy', 'other')),
  details            text check (details is null or length(details) <= 1000),
  status             public.report_status not null default 'pending',
  assigned_to        uuid references public.profiles (id) on delete set null,
  reviewed_by        uuid references public.profiles (id) on delete set null,
  reviewed_at        timestamptz,
  resolution         text check (resolution is null or length(resolution) <= 1000),
  random_session_id  uuid,  -- FK added in 010 once random_sessions exists
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);

create index reports_status_idx on public.reports (status, created_at desc);
create index reports_target_idx on public.reports (target_type, target_id);
create index reports_reporter_idx on public.reports (reporter_id, created_at desc);
create index reports_random_session_idx on public.reports (random_session_id) where random_session_id is not null;
create index reports_open_idx on public.reports (status) where status in ('pending', 'reviewing');

-- One open report per reporter per item: stops report spam without preventing a
-- fresh report after a previous one was resolved or dismissed.
create unique index reports_one_open_per_reporter
  on public.reports (reporter_id, target_type, target_id)
  where status in ('pending', 'reviewing');

create trigger reports_touch before update on public.reports
  for each row execute function public.touch_updated_at();

comment on table public.reports is
  'Central report queue for every reportable entity. Moderators work from this table only.';

-- Does the referenced entity exist, and may the reporter see it? Kept in one
-- plpgsql function so the policy stays readable as modules are added.
create or replace function public.report_target_exists(p_type public.report_target_type, p_id uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_exists boolean := false;
begin
  if p_id is null then
    return false;
  end if;

  case p_type
    when 'user' then
      v_exists := exists (select 1 from public.profiles p where p.id = p_id and p.username is not null);
    when 'post', 'poll' then
      v_exists := exists (select 1 from public.posts p where p.id = p_id);
    when 'comment' then
      v_exists := exists (select 1 from public.comments c where c.id = p_id);
    when 'community', 'club' then
      v_exists := exists (select 1 from public.communities c where c.id = p_id);
    when 'conversation' then
      v_exists := exists (select 1 from public.conversations c where c.id = p_id);
    when 'message' then
      v_exists := exists (select 1 from public.messages m where m.id = p_id);
    when 'marketplace_listing' then
      v_exists := exists (select 1 from public.marketplace_listings l where l.id = p_id);
    when 'gig' then
      v_exists := exists (select 1 from public.gigs g where g.id = p_id);
    when 'deal' then
      v_exists := exists (select 1 from public.campus_deals d where d.id = p_id);
    when 'event' then
      v_exists := exists (select 1 from public.events e where e.id = p_id);
    when 'resource' then
      v_exists := exists (select 1 from public.official_resources r where r.id = p_id);
    when 'opportunity' then
      v_exists := exists (select 1 from public.opportunities o where o.id = p_id);
    when 'project' then
      v_exists := exists (select 1 from public.projects pr where pr.id = p_id);
    when 'lost_found' then
      v_exists := exists (select 1 from public.lost_found lf where lf.id = p_id);
    when 'housing_post' then
      v_exists := exists (select 1 from public.housing_posts h where h.id = p_id);
    when 'ride_post' then
      v_exists := exists (select 1 from public.ride_posts rp where rp.id = p_id);
    when 'random_session' then
      v_exists := exists (select 1 from public.random_sessions rs where rs.id = p_id);
    else
      v_exists := false;
  end case;

  return v_exists;
end;
$$;

-- ----------------------------------------------------------------------------
-- moderation_actions — one row per explicit staff action (spec §105)
-- ----------------------------------------------------------------------------

create table public.moderation_actions (
  id              uuid primary key default gen_random_uuid(),
  -- Nullable + ON DELETE SET NULL: removing a staff account must not destroy
  -- the moderation history it produced (spec §120).
  moderator_id    uuid references public.profiles (id) on delete set null,
  report_id       uuid references public.reports (id) on delete set null,
  action          text not null check (length(btrim(action)) between 3 and 60),
  target_type     text,
  target_id       uuid,
  previous_status text,
  new_status      text,
  duration_days   integer check (duration_days is null or duration_days between 0 and 3650),
  note            text check (note is null or length(note) <= 1000),
  created_at      timestamptz not null default now()
);

create index moderation_actions_moderator_idx on public.moderation_actions (moderator_id, created_at desc);
create index moderation_actions_target_idx on public.moderation_actions (target_type, target_id);
create index moderation_actions_report_idx on public.moderation_actions (report_id);

-- ----------------------------------------------------------------------------
-- audit_logs — the administrative trail (spec §59)
-- ----------------------------------------------------------------------------

create table public.audit_logs (
  id            uuid primary key default gen_random_uuid(),
  actor_user_id uuid references public.profiles (id) on delete set null,
  action        text not null check (length(btrim(action)) between 3 and 80),
  target_type   text,
  target_id     uuid,
  metadata      jsonb,
  visibility    public.moderation_visibility not null default 'staff',
  created_at    timestamptz not null default now()
);

create index audit_logs_created_idx on public.audit_logs (created_at desc);
create index audit_logs_actor_idx on public.audit_logs (actor_user_id, created_at desc);
create index audit_logs_action_idx on public.audit_logs (action, created_at desc);
create index audit_logs_target_idx on public.audit_logs (target_type, target_id);

comment on table public.audit_logs is
  'Append-only administrative trail. Rows are written by log_audit() (definer) so the actor and timestamp cannot be forged.';

-- ----------------------------------------------------------------------------
-- notifications
-- ----------------------------------------------------------------------------

create table public.notifications (
  id             uuid primary key default gen_random_uuid(),
  recipient_id   uuid not null references public.profiles (id) on delete cascade,
  actor_id       uuid references public.profiles (id) on delete set null,
  type           public.notification_type not null,
  title          text not null check (length(btrim(title)) between 1 and 140),
  body           text check (body is null or length(body) <= 500),
  reference_type text check (reference_type is null or length(reference_type) <= 60),
  reference_id   text check (reference_id is null or length(reference_id) <= 80),
  url            text check (url is null or length(url) <= 300),
  read_at        timestamptz,
  created_at     timestamptz not null default now()
);

create index notifications_recipient_idx on public.notifications (recipient_id, created_at desc);
create index notifications_unread_idx on public.notifications (recipient_id) where read_at is null;
create index notifications_actor_idx on public.notifications (actor_id, created_at desc);

comment on table public.notifications is
  'One notification system for the whole product. Rows are created by notify_user(); clients never insert directly.';

-- ----------------------------------------------------------------------------
-- notify_user — the only way a notification row is created
-- ----------------------------------------------------------------------------

create or replace function public.notify_user(
  p_recipient uuid,
  p_type public.notification_type,
  p_title text,
  p_body text default null,
  p_reference_type text default null,
  p_reference_id text default null,
  p_url text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_id uuid;
  v_recent integer;
  v_trusted boolean := public.is_trusted_writer();
begin
  -- Trusted writers (maintenance scripts, scheduled jobs) may send system
  -- notifications without a signed-in actor.
  if v_actor is null and not v_trusted then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if p_recipient is null or p_recipient = v_actor then
    return null;  -- never notify yourself
  end if;
  if not public.is_active_profile(p_recipient) then
    return null;
  end if;
  if v_actor is not null and public.is_blocked(v_actor, p_recipient) then
    return null;  -- blocked relationships produce no notifications
  end if;
  if not v_trusted then
    -- Staff-only notification types cannot be forged by students.
    if p_type in ('moderation_notice', 'report_result', 'system')
       and not (public.is_staff() or public.has_permission('review_reports')) then
      raise exception 'This notification type is restricted to staff.' using errcode = '42501';
    end if;
    -- Basic flood control: 60 notifications per actor per hour.
    select count(*) into v_recent
    from public.notifications n
    where n.actor_id = v_actor and n.created_at > now() - interval '1 hour';
    if v_recent >= 60 then
      return null;
    end if;
  end if;

  insert into public.notifications (
    recipient_id, actor_id, type, title, body, reference_type, reference_id, url
  ) values (
    p_recipient, v_actor, p_type, left(p_title, 140), left(p_body, 500),
    left(p_reference_type, 60), left(p_reference_id, 80), left(p_url, 300)
  )
  returning id into v_id;

  return v_id;
end;
$$;

comment on function public.notify_user is
  'Single entry point for notifications. Filters block relationships, self-notification, inactive recipients and staff-only types.';

-- Mark a notification read (own rows only; enforced by RLS too).
create or replace function public.mark_notification_read(p_id uuid)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  update public.notifications
     set read_at = now()
   where id = p_id
     and recipient_id = public.current_profile_id()
     and read_at is null;
  return found;
end;
$$;

create or replace function public.mark_all_notifications_read()
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_count integer;
begin
  update public.notifications
     set read_at = now()
   where recipient_id = public.current_profile_id()
     and read_at is null;
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- ----------------------------------------------------------------------------
-- log_audit — the single audit entry point
-- ----------------------------------------------------------------------------

create or replace function public.log_audit(
  p_action text,
  p_target_type text default null,
  p_target_id text default null,
  p_metadata jsonb default null,
  p_also_moderation boolean default false,
  p_reason text default null,
  p_visibility public.moderation_visibility default 'staff'
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_id uuid;
  v_is_staff boolean;
begin
  if v_actor is null and not public.is_trusted_writer() then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  v_is_staff := public.is_staff() or public.is_trusted_writer();

  -- Non-staff may only record their own account-lifecycle events, never
  -- moderation or administration entries.
  if not v_is_staff
     and p_action not like 'account.%'
     and p_action not like 'user.%'
     and p_action not like 'content.self_%' then
    raise exception 'You do not have permission to write audit entries.' using errcode = '42501';
  end if;

  insert into public.audit_logs (actor_user_id, action, target_type, target_id, metadata, visibility)
  values (
    v_actor,
    left(p_action, 80),
    left(p_target_type, 60),
    case when p_target_id ~ '^[0-9a-f-]{36}$' then p_target_id::uuid else null end,
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'reason', p_reason,
      'actor_username', (select username from public.profiles where id = v_actor)
    ),
    case when v_is_staff then p_visibility else 'private'::public.moderation_visibility end
  )
  returning id into v_id;

  if p_also_moderation and v_is_staff then
    insert into public.moderation_actions (
      moderator_id, report_id, action, target_type, target_id, note
    ) values (
      v_actor,
      nullif(p_metadata->>'report_id', '')::uuid,
      left(p_action, 60),
      left(p_target_type, 60),
      case when p_target_id ~ '^[0-9a-f-]{36}$' then p_target_id::uuid else null end,
      left(p_reason, 1000)
    );
  end if;

  return v_id;
end;
$$;

comment on function public.log_audit is
  'Append-only audit writer. Students are limited to their own account.* / user.* events; moderation entries require staff.';

-- ----------------------------------------------------------------------------
-- RLS
-- ----------------------------------------------------------------------------

alter table public.reports enable row level security;
alter table public.moderation_actions enable row level security;
alter table public.audit_logs enable row level security;
alter table public.notifications enable row level security;

-- reports -------------------------------------------------------------------
create policy reports_select_reporter on public.reports
  for select to authenticated using (reporter_id = public.current_profile_id());
create policy reports_select_staff on public.reports
  for select to authenticated
  using (public.has_permission('review_reports') or public.has_permission('moderate_all'));

create policy reports_insert_own on public.reports
  for insert to authenticated
  with check (
    reporter_id = public.current_profile_id()
    and public.is_active_user()
    and public.has_permission('report_content')
    and public.report_target_exists(target_type, target_id)
    -- Nobody may report an entity they cannot see (prevents probing private ids)
    and (
      target_type not in ('post', 'comment', 'user', 'community', 'club')
      or (
        case target_type
          when 'post' then exists (
            select 1 from public.posts p where p.id = target_id
              and p.status = 'published' and not public.is_blocked_with_current(p.author_id))
          when 'comment' then exists (
            select 1 from public.comments c where c.id = target_id
              and c.status = 'published' and not public.is_blocked_with_current(c.author_id))
          when 'user' then exists (
            select 1 from public.profiles p where p.id = target_id and p.username is not null)
          when 'community' then public.can_view_community(target_id)
          when 'club' then public.can_view_community(target_id)
          else true
        end
      )
    )
  );

create policy reports_update_staff on public.reports
  for update to authenticated
  using (public.has_permission('review_reports') or public.has_permission('moderate_all'))
  with check (public.has_permission('review_reports') or public.has_permission('moderate_all'));

create policy reports_delete_admin on public.reports
  for delete to authenticated using (public.has_permission('manage_platform_settings'));

-- moderation_actions --------------------------------------------------------
create policy moderation_actions_select_staff on public.moderation_actions
  for select to authenticated
  using (public.has_permission('view_moderation_logs') or public.has_permission('moderate_all'));
create policy moderation_actions_insert_staff on public.moderation_actions
  for insert to authenticated
  with check (public.has_permission('review_reports') or public.is_staff());

-- audit_logs -----------------------------------------------------------------
create policy audit_logs_select_admin on public.audit_logs
  for select to authenticated
  using (public.has_permission('view_audit_logs') or public.has_permission('moderate_all'));
-- No INSERT/UPDATE/DELETE policies: audit rows are written by log_audit() only,
-- and they are immutable.

-- notifications -------------------------------------------------------------
create policy notifications_select_own on public.notifications
  for select to authenticated using (recipient_id = public.current_profile_id());

-- A user may only toggle `read_at`; the content columns are protected below.
create policy notifications_update_own on public.notifications
  for update to authenticated
  using (recipient_id = public.current_profile_id())
  with check (recipient_id = public.current_profile_id());

create policy notifications_delete_own on public.notifications
  for delete to authenticated using (recipient_id = public.current_profile_id());
-- No INSERT policy: use notify_user().

create or replace function public.guard_notification_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if public.is_trusted_writer() then
    return new;
  end if;
  new.recipient_id   := old.recipient_id;
  new.actor_id       := old.actor_id;
  new.type           := old.type;
  new.title          := old.title;
  new.body           := old.body;
  new.reference_type := old.reference_type;
  new.reference_id   := old.reference_id;
  new.url            := old.url;
  new.created_at     := old.created_at;
  return new;
end;
$$;

create trigger notifications_guard_update
  before update on public.notifications
  for each row execute function public.guard_notification_update();

-- ==========================================================================
-- FILE 07/25  20261005000007_007_messaging.sql
-- ==========================================================================

-- Campus+ migration 007 — messaging
-- Supabase CLI filename: 20261005000007_007_messaging.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 007 — direct messages, group chat, read receipts
-- =============================================================================
-- One conversation model serves DMs, marketplace "Message seller", event
-- organizer contact, club/community/study-group chat (spec §133).
--
-- Direct conversations can only be created through
-- `get_or_create_direct_conversation()`, which enforces blocks, the recipient's
-- "allow DMs from everyone" preference and account status. That single rule is
-- what makes "blocked users cannot DM each other" a database guarantee.
--
-- Read receipts only. No presence, no typing indicators, no last-seen (spec §23,
-- §80, §102).
-- =============================================================================

create table public.conversations (
  id              uuid primary key default gen_random_uuid(),
  kind            public.conversation_kind not null default 'direct',
  title           text check (title is null or length(title) <= 120),
  -- canonical "uuid:uuid" key for direct conversations (least:greatest) so a
  -- pair can never accumulate duplicate threads.
  direct_key      text unique,
  community_id    uuid references public.communities (id) on delete cascade,
  created_by      uuid references public.profiles (id) on delete set null,
  status          public.content_status not null default 'published',
  last_message_at timestamptz not null default now(),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint conversations_direct_key check (
    (kind = 'direct' and direct_key is not null) or (kind = 'group')
  ),
  constraint conversations_group_title check (kind = 'group' or title is null)
);

create index conversations_last_message_idx on public.conversations (last_message_at desc);
create index conversations_community_idx on public.conversations (community_id);

create trigger conversations_touch before update on public.conversations
  for each row execute function public.touch_updated_at();

create table public.conversation_members (
  id              uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references public.conversations (id) on delete cascade,
  user_id         uuid not null references public.profiles (id) on delete cascade,
  role            text not null default 'member' check (role in ('member', 'owner')),
  status          text not null default 'active' check (status in ('active', 'left', 'removed')),
  joined_at       timestamptz not null default now(),
  last_read_at    timestamptz,
  -- FK is added right after `messages` is created below: SET NULL keeps the read
  -- marker meaningful even when a sender hard-deletes a message.
  last_read_message_id uuid,
  is_muted        boolean not null default false,
  unique (conversation_id, user_id)
);

create index conversation_members_user_idx on public.conversation_members (user_id, status);
create index conversation_members_conversation_idx on public.conversation_members (conversation_id, status);

create table public.messages (
  id              uuid primary key default gen_random_uuid(),
  conversation_id uuid not null references public.conversations (id) on delete cascade,
  sender_id       uuid not null references public.profiles (id) on delete cascade,
  body            text not null default '' check (length(body) <= 2000),
  gif             jsonb,
  status          public.content_status not null default 'published',
  edited_at       timestamptz,
  deleted_at      timestamptz,
  deleted_by      uuid references public.profiles (id) on delete set null,
  moderated_by    uuid references public.profiles (id) on delete set null,
  moderated_at    timestamptz,
  moderation_reason text,
  created_at      timestamptz not null default now(),
  -- A live message must carry content; a soft-deleted one deliberately carries
  -- none (the content is retained in message_edits for moderation).
  constraint messages_content_present check (
    length(btrim(body)) > 0 or gif is not null or status = 'deleted'
  ),
  constraint messages_gif_provider check (gif is null or (gif->>'provider') = 'giphy'),
  constraint messages_gif_url_host check (gif is null or (gif->>'url') ~ '^https://(media[0-9]?\.)?giphy\.com/')
);

create index messages_conversation_idx on public.messages (conversation_id, created_at desc);
create index messages_sender_idx on public.messages (sender_id, created_at desc);

alter table public.conversation_members
  add constraint conversation_members_last_read_fk
  foreign key (last_read_message_id) references public.messages (id) on delete set null;

comment on table public.messages is
  'DM and group-chat messages. Text plus an optional external GIF reference — never an upload.';

-- Evidence trail: keeps the previous body whenever a message is edited or
-- deleted, so moderation evidence survives (spec §121).
create table public.message_edits (
  id            uuid primary key default gen_random_uuid(),
  message_id    uuid not null references public.messages (id) on delete cascade,
  previous_body text,
  previous_gif  jsonb,
  edited_by     uuid references public.profiles (id) on delete set null,
  reason        text not null default 'edit' check (reason in ('edit', 'delete', 'moderation')),
  edited_at     timestamptz not null default now()
);

create index message_edits_message_idx on public.message_edits (message_id, edited_at desc);

create table public.message_reads (
  id               uuid primary key default gen_random_uuid(),
  conversation_id  uuid not null references public.conversations (id) on delete cascade,
  user_id          uuid not null references public.profiles (id) on delete cascade,
  last_read_at     timestamptz not null default now(),
  last_message_id  uuid references public.messages (id) on delete set null,
  created_at       timestamptz not null default now(),
  unique (conversation_id, user_id)
);

create index message_reads_conversation_idx on public.message_reads (conversation_id);
create index message_reads_user_idx on public.message_reads (user_id);

-- ----------------------------------------------------------------------------
-- Helpers
-- ----------------------------------------------------------------------------

create or replace function public.can_access_conversation(p_conversation uuid, p_user uuid default null)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.conversation_members m
    join public.conversations c on c.id = m.conversation_id
    where m.conversation_id = p_conversation
      and m.user_id = coalesce(p_user, public.current_profile_id())
      and m.status = 'active'
      and c.status = 'published'
  );
$$;

comment on function public.can_access_conversation(uuid, uuid) is
  'The only membership test used by conversation, message and read-receipt policies.';

create or replace function public.conversation_member_ids(p_conversation uuid)
returns uuid[]
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not (public.can_access_conversation(p_conversation) or public.is_staff()) then
    raise exception 'You are not a member of this conversation.' using errcode = '42501';
  end if;
  return (
    select coalesce(array_agg(m.user_id), '{}'::uuid[])
    from public.conversation_members m
    where m.conversation_id = p_conversation and m.status = 'active'
  );
end;
$$;

-- ----------------------------------------------------------------------------
-- get_or_create_direct_conversation — the only path that creates a DM thread
-- ----------------------------------------------------------------------------

create or replace function public.get_or_create_direct_conversation(p_other uuid)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_key text;
  v_id uuid;
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if not public.is_active_user() then
    raise exception 'Your account cannot start conversations.' using errcode = '42501';
  end if;
  if not public.has_permission('send_messages') then
    raise exception 'You do not have permission to send messages.' using errcode = '42501';
  end if;
  if p_other is null or p_other = v_me then
    raise exception 'Choose another student to message.' using errcode = '22023';
  end if;
  if not public.is_active_profile(p_other) then
    raise exception 'That student is not available.' using errcode = '42501';
  end if;
  if public.is_blocked(v_me, p_other) then
    raise exception 'You cannot start a conversation with this student.' using errcode = '42501';
  end if;
  if exists (
    select 1 from public.profiles pr
    where pr.id = p_other and pr.allow_dms_from_everyone = false
  ) then
    raise exception 'That student does not accept messages from everyone.' using errcode = '42501';
  end if;

  v_key := least(v_me::text, p_other::text) || ':' || greatest(v_me::text, p_other::text);

  select c.id into v_id from public.conversations c where c.direct_key = v_key;
  if v_id is not null then
    return v_id;
  end if;

  insert into public.conversations (kind, direct_key, created_by)
  values ('direct', v_key, v_me)
  returning id into v_id;

  insert into public.conversation_members (conversation_id, user_id, role)
  values (v_id, v_me, 'member'), (v_id, p_other, 'member');

  return v_id;
end;
$$;

comment on function public.get_or_create_direct_conversation(uuid) is
  'Creates or returns the single DM thread between two students, enforcing blocks, DM preferences and account status.';

-- ----------------------------------------------------------------------------
-- open_community_chat — the group room for a community / study group / club
-- ----------------------------------------------------------------------------
-- Rooms are created and populated by the database, not by the client: one room
-- per space, members kept in sync with space membership. This keeps chat
-- authorization identical to community authorization (spec §23, §114).

create or replace function public.open_community_chat(p_community uuid)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_id uuid;
  v_title text;
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if not public.is_active_user() then
    raise exception 'Your account cannot open chats.' using errcode = '42501';
  end if;
  if not public.feature_enabled('group_chat') then
    raise exception 'Group chat is disabled.' using errcode = '42501';
  end if;
  if p_community is null then
    raise exception 'Choose a space.' using errcode = '22023';
  end if;
  if not public.can_view_community(p_community) then
    raise exception 'You cannot open this chat.' using errcode = '42501';
  end if;
  if not (public.is_community_member(p_community) or public.is_staff()) then
    raise exception 'Join the space before using its chat.' using errcode = '42501';
  end if;

  select c.id into v_id
  from public.conversations c
  where c.community_id = p_community and c.kind = 'group'
  limit 1;

  select co.name into v_title from public.communities co where co.id = p_community;

  if v_id is null then
    insert into public.conversations (kind, title, community_id, created_by)
    values ('group', left(v_title, 120), p_community, v_me)
    returning id into v_id;
  end if;

  -- Keep membership aligned with the space. Only active members are added.
  insert into public.conversation_members (conversation_id, user_id, role)
  select v_id, m.user_id, case when m.role = 'owner' then 'owner' else 'member' end
  from public.community_members m
  where m.community_id = p_community and m.status = 'active'
  on conflict (conversation_id, user_id) do nothing;

  insert into public.conversation_members (conversation_id, user_id, role)
  values (v_id, v_me, 'member')
  on conflict (conversation_id, user_id) do nothing;

  return v_id;
end;
$$;

comment on function public.open_community_chat(uuid) is
  'Returns (creating if needed) the single group chat room for a community, study group or club.';

-- ----------------------------------------------------------------------------
-- mark_conversation_read — powers the Seen receipt
-- ----------------------------------------------------------------------------

create or replace function public.mark_conversation_read(p_conversation uuid)
returns timestamptz
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_now timestamptz := now();
  v_last uuid;
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if not public.can_access_conversation(p_conversation, v_me) then
    raise exception 'You are not a member of this conversation.' using errcode = '42501';
  end if;

  select m.id into v_last
  from public.messages m
  where m.conversation_id = p_conversation
  order by m.created_at desc
  limit 1;

  update public.conversation_members
     set last_read_at = v_now,
         last_read_message_id = coalesce(v_last, last_read_message_id)
   where conversation_id = p_conversation and user_id = v_me;

  insert into public.message_reads (conversation_id, user_id, last_read_at, last_message_id)
  values (p_conversation, v_me, v_now, v_last)
  on conflict (conversation_id, user_id)
  do update set last_read_at = v_now, last_message_id = coalesce(v_last, public.message_reads.last_message_id);

  return v_now;
end;
$$;

comment on function public.mark_conversation_read(uuid) is
  'Records the Seen receipt for the calling member. There is no other read-state mechanism.';

-- ----------------------------------------------------------------------------
-- Guarded writes
-- ----------------------------------------------------------------------------

-- Conversation last_message_at + the sender's own read position.
create or replace function public.on_message_inserted()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  update public.conversations
     set last_message_at = new.created_at
   where id = new.conversation_id;
  return new;
end;
$$;

create trigger messages_touch_conversation
  after insert on public.messages
  for each row execute function public.on_message_inserted();

-- Preserve previous content when a message is edited or deleted.
create or replace function public.track_message_edit()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  -- Deletions are captured by soften_deleted_message (which owns that
  -- transition); this trigger records content edits and staff moderation edits.
  if (new.body is distinct from old.body or new.gif is distinct from old.gif)
     and new.deleted_at is not distinct from old.deleted_at then
    insert into public.message_edits (message_id, previous_body, previous_gif, edited_by, reason)
    values (
      old.id, old.body, old.gif, coalesce(public.current_profile_id(), new.sender_id),
      case when public.is_staff() and old.sender_id is distinct from public.current_profile_id()
           then 'moderation' else 'edit' end
    );
  end if;
  if new.body is distinct from old.body and new.deleted_at is null then
    new.edited_at := now();
  end if;
  return new;
end;
$$;

create trigger messages_track_edit
  before update on public.messages
  for each row execute function public.track_message_edit();

-- Soft-neutralise a deleted message: keep the row (and the evidence trail),
-- drop the visible content.
create or replace function public.soften_deleted_message()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if new.deleted_at is not null and old.deleted_at is null then
    -- Retention first: the content being removed is kept as evidence so that a
    -- moderator can still read what was said (spec: deletion must never break
    -- moderation or audit).
    if length(btrim(coalesce(old.body, ''))) > 0 or old.gif is not null then
      insert into public.message_edits (message_id, previous_body, previous_gif, edited_by, reason)
      values (old.id, old.body, old.gif, coalesce(new.deleted_by, public.current_profile_id()), 'delete');
    end if;

    new.body := '';
    new.gif := null;
    new.status := 'deleted';
  end if;
  return new;
end;
$$;

create trigger messages_soften_deleted
  before update on public.messages
  for each row execute function public.soften_deleted_message();

-- ----------------------------------------------------------------------------
-- RLS
-- ----------------------------------------------------------------------------

alter table public.conversations enable row level security;
alter table public.conversation_members enable row level security;
alter table public.messages enable row level security;
alter table public.message_edits enable row level security;
alter table public.message_reads enable row level security;

-- conversations -------------------------------------------------------------
-- The creator fallback keeps `INSERT ... RETURNING` working (PostgreSQL applies SELECT
-- policies to returned rows) and lets a room owner always see the room they opened.
create policy conversations_select_member on public.conversations
  for select to authenticated
  using (public.can_access_conversation(id) or created_by = public.current_profile_id());

-- Staff may read a conversation ONLY while a report is open against it. This is
-- the narrow, auditable moderation window (access is written to audit_logs by
-- the application every time it is used).
create policy conversations_select_staff_on_report on public.conversations
  for select to authenticated
  using (
    (public.has_permission('review_reports') or public.has_permission('moderate_all'))
    and exists (
      select 1 from public.reports r
      where r.target_type in ('conversation', 'message')
        and r.status in ('pending', 'reviewing')
        and (r.target_id = conversations.id
             or exists (select 1 from public.messages m
                        where m.id = r.target_id and m.conversation_id = conversations.id))
    )
  );

-- Direct conversations are created exclusively by the definer function; group
-- rooms may be created by a community moderator or by a student opening a chat
-- for a space they belong to.
create policy conversations_insert_group on public.conversations
  for insert to authenticated
  with check (
    kind = 'group'
    and created_by = public.current_profile_id()
    and public.is_active_user()
    and (
      (community_id is null and public.has_permission('create_communities'))
      or (community_id is not null and public.is_community_moderator(community_id))
    )
  );

create policy conversations_update_member on public.conversations
  for update to authenticated
  using (public.can_access_conversation(id))
  with check (public.can_access_conversation(id));

-- conversation_members ------------------------------------------------------
create policy conversation_members_select_member on public.conversation_members
  for select to authenticated
  using (public.can_access_conversation(conversation_id));

create policy conversation_members_update_self on public.conversation_members
  for update to authenticated
  using (user_id = public.current_profile_id())
  with check (user_id = public.current_profile_id());

create policy conversation_members_insert_group_member on public.conversation_members
  for insert to authenticated
  with check (
    exists (
      select 1 from public.conversations c
      where c.id = conversation_id
        and c.kind = 'group'
        and public.can_access_conversation(c.id)
    )
  );

-- messages ------------------------------------------------------------------
create policy messages_select_member on public.messages
  for select to authenticated
  using (public.can_access_conversation(conversation_id));

create policy messages_select_staff_on_report on public.messages
  for select to authenticated
  using (
    (public.has_permission('review_reports') or public.has_permission('moderate_all'))
    and exists (
      select 1 from public.reports r
      where r.status in ('pending', 'reviewing')
        and (
          (r.target_type = 'message' and r.target_id = messages.id)
          or (r.target_type = 'conversation' and r.target_id = messages.conversation_id)
        )
    )
  );

create policy messages_insert_member on public.messages
  for insert to authenticated
  with check (
    sender_id = public.current_profile_id()
    and public.is_active_user()
    and public.has_permission('send_messages')
    and status = 'published'
    and public.can_access_conversation(conversation_id)
    -- A block in either direction stops message delivery, in direct threads and
    -- group rooms alike.
    -- `other.conversation_id` MUST be qualified against the outer table:
    -- an unqualified name inside the subquery binds to `other`, turning the
    -- join into a tautology and blocking the sender's unrelated conversations.
    and not exists (
      select 1
      from public.conversation_members other
      where other.conversation_id = messages.conversation_id
        and other.user_id <> messages.sender_id
        and other.status = 'active'
        and public.is_blocked(messages.sender_id, other.user_id)
    )
  );

create policy messages_update_sender on public.messages
  for update to authenticated
  using (
    sender_id = public.current_profile_id()
    and public.is_active_user()
    and deleted_at is null
    and created_at > now() - interval '15 minutes'
  )
  with check (sender_id = public.current_profile_id());

create policy messages_update_staff on public.messages
  for update to authenticated
  using ((public.has_permission('review_reports') or public.has_permission('moderate_all'))
         and exists (select 1 from public.reports r
                     where r.status in ('pending', 'reviewing')
                       and ((r.target_type = 'message' and r.target_id = messages.id)
                            or (r.target_type = 'conversation' and r.target_id = messages.conversation_id))))
  with check (true);

create policy messages_delete_sender on public.messages
  for delete to authenticated using (sender_id = public.current_profile_id());
create policy messages_delete_staff on public.messages
  for delete to authenticated
  using (public.has_permission('moderate_all'));

-- message_edits (evidence) ---------------------------------------------------
create policy message_edits_select_staff on public.message_edits
  for select to authenticated
  using (public.has_permission('view_moderation_logs') or public.has_permission('review_reports'));

-- message_reads --------------------------------------------------------------
-- Every member of a conversation may see the read state of that conversation's
-- members (that is the Seen receipt). Nobody can see read states elsewhere.
create policy message_reads_select_member on public.message_reads
  for select to authenticated
  using (public.can_access_conversation(conversation_id));

create policy message_reads_insert_self on public.message_reads
  for insert to authenticated
  with check (user_id = public.current_profile_id() and public.can_access_conversation(conversation_id));

create policy message_reads_update_self on public.message_reads
  for update to authenticated
  using (user_id = public.current_profile_id())
  with check (user_id = public.current_profile_id());

-- ==========================================================================
-- FILE 08/25  20261005000008_008_marketplace.sql
-- ==========================================================================

-- Campus+ migration 008 — marketplace
-- Supabase CLI filename: 20261005000008_008_marketplace.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 008 — marketplace, gigs, free stuff, deals, ratings
-- =============================================================================
-- Listings are text-only. "Free stuff" is the same table with is_free = true
-- (spec §30: do not build duplicate infrastructure). Deals are the official,
-- staff-managed counterpart (spec §31).
--
-- Seller contact always reuses the DM system: there is no marketplace messaging
-- table anywhere in this schema (spec §26, §134).
-- =============================================================================

-- ----------------------------------------------------------------------------
-- categories — editable by Admin/Super Admin (spec §28)
-- ----------------------------------------------------------------------------

create table public.marketplace_categories (
  id          uuid primary key default gen_random_uuid(),
  name        text not null check (length(btrim(name)) between 2 and 60),
  slug        text not null unique check (slug ~ '^[a-z0-9-]{2,60}$'),
  description text check (description is null or length(description) <= 200),
  -- which board the category belongs to
  scope       text not null default 'marketplace' check (scope in ('marketplace', 'gig', 'deal')),
  sort_order  integer not null default 0,
  is_active   boolean not null default true,
  created_by  uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

create index marketplace_categories_scope_idx on public.marketplace_categories (scope, sort_order);

create trigger marketplace_categories_touch before update on public.marketplace_categories
  for each row execute function public.touch_updated_at();

-- ----------------------------------------------------------------------------
-- listings
-- ----------------------------------------------------------------------------

create table public.marketplace_listings (
  id                uuid primary key default gen_random_uuid(),
  seller_id         uuid not null references public.profiles (id) on delete cascade,
  category_id       uuid not null references public.marketplace_categories (id) on delete restrict,
  title             text not null check (length(btrim(title)) between 3 and 120),
  description       text not null check (length(btrim(description)) between 5 and 1500),
  price             numeric(12, 2) check (price is null or price >= 0),
  is_free           boolean not null default false,
  is_negotiable     boolean not null default true,
  condition         public.item_condition not null default 'not_applicable',
  location          text check (location is null or length(location) <= 120),
  contact_note      text check (contact_note is null or length(contact_note) <= 200),
  status            public.listing_status not null default 'active',
  reserved_for      uuid references public.profiles (id) on delete set null,
  sold_at           timestamptz,
  sold_to           uuid references public.profiles (id) on delete set null,
  view_count        integer not null default 0 check (view_count >= 0),
  contact_count     integer not null default 0 check (contact_count >= 0),
  is_official       boolean not null default false,
  moderated_by      uuid references public.profiles (id) on delete set null,
  moderated_at      timestamptz,
  moderation_reason text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  search_vector     tsvector generated always as (
    to_tsvector('english'::regconfig, coalesce(title, '') || ' ' || coalesce(description, ''))
  ) stored,
  constraint listings_free_price check (not is_free or price is null or price = 0)
);

create index marketplace_listings_status_idx on public.marketplace_listings (status, created_at desc);
create index listings_reserved_idx on public.marketplace_listings (reserved_for) where reserved_for is not null;
create index listings_sold_idx on public.marketplace_listings (sold_to) where sold_to is not null;
create index marketplace_listings_category_idx on public.marketplace_listings (category_id, status);
create index marketplace_listings_seller_idx on public.marketplace_listings (seller_id, created_at desc);
create index marketplace_listings_free_idx on public.marketplace_listings (created_at desc) where is_free;
create index marketplace_listings_search_idx on public.marketplace_listings using gin (search_vector);

create trigger marketplace_listings_touch before update on public.marketplace_listings
  for each row execute function public.touch_updated_at();

comment on table public.marketplace_listings is
  'Student listings, gig board is separate. No image, file or video columns exist by design.';

-- Seller-editable columns only; moderation state and counters are protected.
create or replace function public.guard_listing_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_trusted_writer() then
    new.view_count := (
      select count(*) from public.marketplace_interactions i
      where i.listing_id = old.id and i.kind = 'view'
    );
    new.contact_count := (
      select count(*) from public.marketplace_interactions i
      where i.listing_id = old.id and i.kind = 'contact'
    );
  end if;

  if public.is_trusted_writer() or public.has_permission('moderate_marketplace') or public.has_permission('moderate_all') then
    return new;
  end if;
  new.seller_id         := old.seller_id;
  new.category_id       := old.category_id;
  new.is_official       := old.is_official;
  new.moderated_by      := old.moderated_by;
  new.moderated_at      := old.moderated_at;
  new.moderation_reason := old.moderation_reason;
  new.sold_at           := old.sold_at;
  new.sold_to           := old.sold_to;
  -- A seller may only move a listing between the student-controlled states.
  if new.status is distinct from old.status
     and new.status not in ('active', 'reserved', 'sold', 'expired') then
    new.status := old.status;
  end if;
  return new;
end;
$$;

create trigger marketplace_listings_guard_update
  before update on public.marketplace_listings
  for each row execute function public.guard_listing_update();

-- Pre-publication moderation mode (spec §27): when the operator selects
-- "moderator approval before publishing", student listings start as `pending`.
create or replace function public.marketplace_requires_approval()
returns boolean
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_value jsonb;
begin
  begin
    select value into v_value from public.platform_settings where key = 'marketplace_approval_mode';
  exception when undefined_table then
    return false;  -- platform_settings not migrated yet: default to post-moderation
  end;
  return coalesce(v_value, '"post_moderation"'::jsonb) = '"pre_moderation"'::jsonb;
end;
$$;

create or replace function public.apply_listing_approval_mode()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if public.is_trusted_writer() or public.has_permission('moderate_marketplace') or public.is_staff() then
    return new;
  end if;
  if new.status = 'active' and public.marketplace_requires_approval() then
    new.status := 'pending';
  end if;
  return new;
end;
$$;

create trigger marketplace_listings_approval
  before insert on public.marketplace_listings
  for each row execute function public.apply_listing_approval_mode();

-- ----------------------------------------------------------------------------
-- marketplace_interactions — operational counters, not analytics (spec §123)
-- ----------------------------------------------------------------------------

create table public.marketplace_interactions (
  id         uuid primary key default gen_random_uuid(),
  listing_id uuid not null references public.marketplace_listings (id) on delete cascade,
  user_id    uuid not null references public.profiles (id) on delete cascade,
  kind       text not null check (kind in ('view', 'contact', 'save')),
  created_at timestamptz not null default now()
);

create index marketplace_interactions_listing_idx on public.marketplace_interactions (listing_id, kind);
create index marketplace_interactions_user_idx on public.marketplace_interactions (user_id, created_at desc);
-- One 'contact'/'save' row per student per listing. The table backs operational
-- counters and the "notify the seller once" rule, not an event log, so the
-- partial unique index is what makes `on conflict do nothing` meaningful.
create unique index marketplace_interactions_once_idx
  on public.marketplace_interactions (listing_id, user_id, kind)
  where kind in ('contact', 'save');

-- Keep the denormalised counters on the listing truthful: guard_listing_update()
-- recomputes them on every listing write, and this trigger does the same when an
-- interaction is the thing that changed.
create or replace function public.sync_listing_counters()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_listing uuid := coalesce(new.listing_id, old.listing_id);
begin
  update public.marketplace_listings l
     set view_count = (
           select count(*) from public.marketplace_interactions i
           where i.listing_id = v_listing and i.kind = 'view'
         ),
         contact_count = (
           select count(*) from public.marketplace_interactions i
           where i.listing_id = v_listing and i.kind = 'contact'
         )
   where l.id = v_listing;
  return null;
end;
$$;

create trigger marketplace_interactions_sync_counters
  after insert or delete on public.marketplace_interactions
  for each row execute function public.sync_listing_counters();

-- ----------------------------------------------------------------------------
-- gigs (student services board, spec §29)
-- ----------------------------------------------------------------------------

create table public.gigs (
  id                uuid primary key default gen_random_uuid(),
  creator_id        uuid not null references public.profiles (id) on delete cascade,
  category_id       uuid references public.marketplace_categories (id) on delete set null,
  title             text not null check (length(btrim(title)) between 3 and 120),
  description       text not null check (length(btrim(description)) between 5 and 1500),
  category          text not null check (length(btrim(category)) between 2 and 60),
  compensation      text check (compensation is null or length(compensation) <= 120),
  availability      text check (availability is null or length(availability) <= 200),
  status            public.content_status not null default 'published',
  moderated_by      uuid references public.profiles (id) on delete set null,
  moderated_at      timestamptz,
  moderation_reason text,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  search_vector     tsvector generated always as (
    to_tsvector('english'::regconfig, coalesce(title, '') || ' ' || coalesce(description, ''))
  ) stored
);

create index gigs_status_idx on public.gigs (status, created_at desc);
create index gigs_creator_idx on public.gigs (creator_id, created_at desc);
create index gigs_category_idx on public.gigs (category_id, status);
create index gigs_search_idx on public.gigs using gin (search_vector);

create trigger gigs_touch before update on public.gigs
  for each row execute function public.touch_updated_at();

-- ----------------------------------------------------------------------------
-- campus_deals (official, spec §31)
-- ----------------------------------------------------------------------------

create table public.campus_deals (
  id                uuid primary key default gen_random_uuid(),
  title             text not null check (length(btrim(title)) between 3 and 120),
  description       text not null check (length(btrim(description)) between 5 and 1000),
  merchant          text not null check (length(btrim(merchant)) between 2 and 120),
  discount_details  text not null check (length(btrim(discount_details)) between 2 and 300),
  valid_from        date,
  valid_until       date,
  contact_info      text check (contact_info is null or length(contact_info) <= 200),
  status            public.content_status not null default 'published',
  is_official       boolean not null default true,
  created_by        uuid not null references public.profiles (id) on delete restrict,
  updated_by        uuid references public.profiles (id) on delete set null,
  published_at      timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  search_vector     tsvector generated always as (
    to_tsvector('english'::regconfig, coalesce(title, '') || ' ' || coalesce(merchant, '') || ' ' || coalesce(description, ''))
  ) stored,
  constraint deals_validity_order check (valid_until is null or valid_from is null or valid_until >= valid_from)
);

create index campus_deals_status_idx on public.campus_deals (status, created_at desc);
create index campus_deals_search_idx on public.campus_deals using gin (search_vector);

create trigger campus_deals_touch before update on public.campus_deals
  for each row execute function public.touch_updated_at();

-- ----------------------------------------------------------------------------
-- ratings — simple buyer/seller reputation (spec §52)
-- ----------------------------------------------------------------------------

create table public.ratings (
  id         uuid primary key default gen_random_uuid(),
  listing_id uuid not null references public.marketplace_listings (id) on delete cascade,
  rater_id   uuid not null references public.profiles (id) on delete cascade,
  ratee_id   uuid not null references public.profiles (id) on delete cascade,
  role       public.rating_role not null default 'seller',
  score      integer not null check (score between 1 and 5),
  comment    text check (comment is null or length(comment) <= 300),
  created_at timestamptz not null default now(),
  constraint ratings_no_self check (rater_id <> ratee_id),
  unique (listing_id, rater_id, role)
);

create index ratings_ratee_idx on public.ratings (ratee_id, created_at desc);
create index ratings_rater_idx on public.ratings (rater_id);

comment on table public.ratings is
  'Marketplace reputation only: one rating per participant per listing. No popularity or engagement scoring.';

-- Recompute reputation deterministically from the ratings table.
create or replace function public.recompute_reputation(p_profile uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  update public.profiles p
     set reputation_score = coalesce((select round(avg(r.score)::numeric, 2) from public.ratings r where r.ratee_id = p_profile), 0),
         reputation_count = coalesce((select count(*) from public.ratings r where r.ratee_id = p_profile), 0)
   where p.id = p_profile;
end;
$$;

create or replace function public.on_rating_changed()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  perform public.recompute_reputation(coalesce(new.ratee_id, old.ratee_id));
  return coalesce(new, old);
end;
$$;

create trigger ratings_recompute
  after insert or update or delete on public.ratings
  for each row execute function public.on_rating_changed();

-- Completed marketplace interactions (used by the "Marketplace Seller" achievement
-- and the public trust indicator).
create or replace function public.on_listing_completed()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if new.status = 'sold' and old.status <> 'sold' then
    update public.profiles
       set marketplace_completed_count = marketplace_completed_count + 1
     where id = new.seller_id;
  end if;
  return new;
end;
$$;

create trigger marketplace_listings_completed
  after update on public.marketplace_listings
  for each row execute function public.on_listing_completed();

-- ----------------------------------------------------------------------------
-- RLS
-- ----------------------------------------------------------------------------

alter table public.marketplace_categories enable row level security;
alter table public.marketplace_listings enable row level security;
alter table public.marketplace_interactions enable row level security;
alter table public.gigs enable row level security;
alter table public.campus_deals enable row level security;
alter table public.ratings enable row level security;

-- categories ----------------------------------------------------------------
create policy marketplace_categories_select on public.marketplace_categories
  for select to authenticated using (true);
create policy marketplace_categories_manage on public.marketplace_categories
  for all to authenticated
  using (public.has_permission('manage_categories'))
  with check (public.has_permission('manage_categories'));

-- listings ------------------------------------------------------------------
create policy listings_select_visible on public.marketplace_listings
  for select to authenticated
  using (
    status in ('active', 'reserved', 'sold')
    and public.is_active_profile(seller_id)
    and not public.is_blocked_with_current(seller_id)
  );

create policy listings_select_own on public.marketplace_listings
  for select to authenticated using (seller_id = public.current_profile_id());

create policy listings_select_staff on public.marketplace_listings
  for select to authenticated
  using (public.has_permission('moderate_marketplace') or public.has_permission('moderate_all'));

create policy listings_insert_own on public.marketplace_listings
  for insert to authenticated
  with check (
    seller_id = public.current_profile_id()
    and public.is_active_user()
    and public.has_permission('create_marketplace_listing')
    and status in ('active', 'pending')
    and is_official = false
    and exists (select 1 from public.marketplace_categories c where c.id = category_id and c.is_active)
  );

create policy listings_update_own on public.marketplace_listings
  for update to authenticated
  using (seller_id = public.current_profile_id() and public.is_active_user())
  with check (seller_id = public.current_profile_id());

create policy listings_update_staff on public.marketplace_listings
  for update to authenticated
  using (public.has_permission('moderate_marketplace') or public.has_permission('moderate_all'))
  with check (public.has_permission('moderate_marketplace') or public.has_permission('moderate_all'));

create policy listings_delete_own on public.marketplace_listings
  for delete to authenticated using (seller_id = public.current_profile_id());
create policy listings_delete_staff on public.marketplace_listings
  for delete to authenticated
  using (public.has_permission('moderate_marketplace') or public.has_permission('moderate_all'));

-- interactions --------------------------------------------------------------
create policy marketplace_interactions_select_own on public.marketplace_interactions
  for select to authenticated using (user_id = public.current_profile_id());
create policy marketplace_interactions_select_seller on public.marketplace_interactions
  for select to authenticated
  using (exists (select 1 from public.marketplace_listings l
                 where l.id = listing_id and l.seller_id = public.current_profile_id()));

create policy marketplace_interactions_insert_self on public.marketplace_interactions
  for insert to authenticated
  with check (
    user_id = public.current_profile_id()
    and public.has_permission('block_users')  -- any signed-in student
    and exists (select 1 from public.marketplace_listings l
                where l.id = listing_id and l.status in ('active', 'reserved', 'sold'))
  );

-- gigs ----------------------------------------------------------------------
create policy gigs_select_visible on public.gigs
  for select to authenticated
  using (
    status = 'published'
    and public.is_active_profile(creator_id)
    and not public.is_blocked_with_current(creator_id)
  );
create policy gigs_select_own on public.gigs
  for select to authenticated using (creator_id = public.current_profile_id());
create policy gigs_select_staff on public.gigs
  for select to authenticated
  using (public.has_permission('moderate_marketplace') or public.has_permission('moderate_all'));

create policy gigs_insert_own on public.gigs
  for insert to authenticated
  with check (
    creator_id = public.current_profile_id()
    and public.is_active_user()
    and public.has_permission('create_gigs')
    and status = 'published'
  );

create policy gigs_update_own on public.gigs
  for update to authenticated
  using (creator_id = public.current_profile_id() and public.is_active_user())
  with check (creator_id = public.current_profile_id());
create policy gigs_update_staff on public.gigs
  for update to authenticated
  using (public.has_permission('moderate_marketplace') or public.has_permission('moderate_all'))
  with check (public.has_permission('moderate_marketplace') or public.has_permission('moderate_all'));
create policy gigs_delete_own on public.gigs
  for delete to authenticated using (creator_id = public.current_profile_id());

-- deals (official only) -----------------------------------------------------
create policy campus_deals_select_published on public.campus_deals
  for select to authenticated using (status = 'published' or public.has_permission('manage_deals'));
create policy campus_deals_manage on public.campus_deals
  for all to authenticated
  using (public.has_permission('manage_deals') or public.has_permission('moderate_all'))
  with check (public.has_permission('manage_deals') or public.has_permission('moderate_all'));

-- ratings -------------------------------------------------------------------
create policy ratings_select_public on public.ratings
  for select to authenticated using (true);

create policy ratings_insert_participant on public.ratings
  for insert to authenticated
  with check (
    rater_id = public.current_profile_id()
    and public.is_active_user()
    and public.has_permission('rate_users')
    -- A rating must reference a real listing where the two people actually dealt
    -- with each other: either the seller rating the recorded buyer, or a student
    -- who contacted the listing rating the seller.
    and exists (
      select 1
      from public.marketplace_listings l
      where l.id = listing_id
        and (
          (l.seller_id = rater_id and ratee_id = l.sold_to and role = 'buyer')
          or (l.seller_id = ratee_id
              and role = 'seller'
              and exists (
                select 1 from public.marketplace_interactions i
                where i.listing_id = l.id and i.user_id = rater_id and i.kind = 'contact'
              ))
        )
    )
  );

create policy ratings_update_own on public.ratings
  for update to authenticated
  using (rater_id = public.current_profile_id())
  with check (rater_id = public.current_profile_id());
create policy ratings_delete_own on public.ratings
  for delete to authenticated using (rater_id = public.current_profile_id());

-- ==========================================================================
-- FILE 09/25  20261005000009_009_campus.sql
-- ==========================================================================

-- Campus+ migration 009 — campus
-- Supabase CLI filename: 20261005000009_009_campus.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 009 — campus information, official content, student boards
-- =============================================================================
-- Two clearly separated authorities (spec §74):
--
--   OFFICIAL  — notices, events, deals, directory, services, calendar,
--               transport, cafeteria, forms/links, emergency help, locations.
--               Written only by roles holding the matching permission.
--   COMMUNITY — lost & found, housing, rides, team finder, projects,
--               resource submissions, community opportunities.
--
-- Every official row records created_by / updated_by / published_at / status so
-- accountability is structural (spec §103).
--
-- Discussion reuse: entities that support comments link to an ordinary `posts`
-- row (`discussion_post_id`), so comments, reactions and mentions all flow
-- through the one social system instead of a parallel comment table (spec §133).
-- =============================================================================

-- Extend reactions to cover projects (spec §39) through the existing table.
alter table public.reactions drop constraint reactions_target_type_check;
alter table public.reactions add constraint reactions_target_type_check
  check (target_type in ('post', 'comment', 'project'));

alter table public.reactions drop constraint reactions_user_id_target_type_target_id_key;
alter table public.reactions add constraint reactions_unique_per_item
  unique (user_id, target_type, target_id);

-- Same for mentions, so a mention inside a discussion post always resolves.
alter table public.mentions drop constraint mentions_source_type_check;
alter table public.mentions add constraint mentions_source_type_check
  check (source_type in ('post', 'comment', 'message', 'project', 'lost_found', 'opportunity', 'event', 'resource', 'community_post'));

-- ----------------------------------------------------------------------------
-- Helper: should community submissions land in the moderation queue?
-- ----------------------------------------------------------------------------

create or replace function public.community_submissions_require_review(p_kind text)
returns boolean
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_value jsonb;
begin
  begin
    select value into v_value from public.platform_settings where key = 'moderate_community_submissions';
  exception when undefined_table then
    return false;
  end;
  if v_value is null then
    return false;  -- default: immediate publishing + post-publication moderation
  end if;
  if jsonb_typeof(v_value) = 'boolean' then
    return v_value = 'true'::jsonb;
  end if;
  return coalesce(v_value->>p_kind, 'false') = 'true';
end;
$$;

-- ----------------------------------------------------------------------------
-- events
