-- ==========================================================================
-- FILE 10/25  20261005000010_010_random.sql
-- ==========================================================================

-- Campus+ migration 010 — random
-- Supabase CLI filename: 20261005000010_010_random.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 010 — Random: anonymous, moderated, human-to-human chat
-- =============================================================================
-- Design guarantees (spec §24, §25, §78, §122):
--
--  1. `random_sessions` (which maps two real identities) is NOT readable by the
--     participants. Only staff holding the `view_random_sessions` permission may
--     read it, and every such read is written to audit_logs by the application.
--  2. Participants interact through definer views/RPCs that expose a *side*
--     label ('you' / 'stranger') instead of profile ids.
--  3. Realtime uses private broadcast channels per session; authorization lives
--     in the `realtime.messages` policies created in migration 013.
--  4. Reports always carry the session id, so moderation remains possible even
--     though the two participants cannot identify each other.
-- =============================================================================

create table public.random_queue (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null unique references public.profiles (id) on delete cascade,
  joined_at  timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '10 minutes',
  status     public.random_queue_status not null default 'waiting',
  session_id uuid,  -- FK added after random_sessions is created below
  constraint random_queue_expiry check (expires_at > joined_at)
);

create index random_queue_status_idx on public.random_queue (status, joined_at);
create index random_queue_session_idx on public.random_queue (session_id) where session_id is not null;

comment on table public.random_queue is
  'Waiting room for Random. `expires_at` keeps stale entries from matching after the student has closed the tab.';

create table public.random_sessions (
  id            uuid primary key default gen_random_uuid(),
  participant_a uuid not null references public.profiles (id) on delete cascade,
  participant_b uuid not null references public.profiles (id) on delete cascade,
  started_at    timestamptz not null default now(),
  ended_at      timestamptz,
  ended_by      uuid references public.profiles (id) on delete set null,
  end_reason    text check (end_reason is null or end_reason in ('left', 'next', 'timeout', 'moderation', 'blocked', 'reported')),
  status        public.random_session_status not null default 'active',
  message_count integer not null default 0 check (message_count >= 0),
  expires_at    timestamptz not null default now() + interval '60 minutes',
  reviewed_by   uuid references public.profiles (id) on delete set null,
  reviewed_at   timestamptz,
  constraint random_sessions_distinct check (participant_a <> participant_b),
  constraint random_sessions_order check (participant_a < participant_b)
);

create index random_sessions_status_idx on public.random_sessions (status, started_at desc);
create index random_sessions_participant_a_idx on public.random_sessions (participant_a, started_at desc);
create index random_sessions_participant_b_idx on public.random_sessions (participant_b, started_at desc);

alter table public.random_queue
  add constraint random_queue_session_fk
  foreign key (session_id) references public.random_sessions (id) on delete set null;

comment on table public.random_sessions is
  'Internal identity mapping for anonymous sessions. Never exposed to participants; staff access requires view_random_sessions and is audited.';

create table public.random_session_participants (
  id           uuid primary key default gen_random_uuid(),
  session_id   uuid not null references public.random_sessions (id) on delete cascade,
  user_id      uuid not null references public.profiles (id) on delete cascade,
  side         text not null check (side in ('a', 'b')),
  joined_at    timestamptz not null default now(),
  left_at      timestamptz,
  message_count integer not null default 0 check (message_count >= 0),
  unique (session_id, user_id),
  unique (session_id, side)
);

create index random_session_participants_user_idx on public.random_session_participants (user_id, joined_at desc);

create table public.random_messages (
  id              uuid primary key default gen_random_uuid(),
  session_id      uuid not null references public.random_sessions (id) on delete cascade,
  sender_user_id  uuid not null references public.profiles (id) on delete cascade,
  content         text not null default '' check (length(content) <= 2000),
  gif             jsonb,
  status          public.content_status not null default 'published',
  created_at      timestamptz not null default now(),
  constraint random_messages_content_present check (length(btrim(content)) > 0 or gif is not null),
  constraint random_messages_gif_provider check (gif is null or (gif->>'provider') = 'giphy'),
  constraint random_messages_gif_url_host check (gif is null or (gif->>'url') ~ '^https://(media[0-9]?\.)?giphy\.com/')
);

create index random_messages_session_idx on public.random_messages (session_id, created_at);
create index random_messages_sender_idx on public.random_messages (sender_user_id);

create table public.random_reports (
  id               uuid primary key default gen_random_uuid(),
  session_id       uuid not null references public.random_sessions (id) on delete cascade,
  reporter_user_id uuid not null references public.profiles (id) on delete cascade,
  target_user_id   uuid not null references public.profiles (id) on delete cascade,
  reason           text not null check (reason in (
                     'spam', 'harassment', 'hate', 'nudity', 'violence', 'scam',
                     'misinformation', 'impersonation', 'academic_dishonesty',
                     'privacy', 'other')),
  details          text check (details is null or length(details) <= 1000),
  status           public.report_status not null default 'pending',
  reviewed_by      uuid references public.profiles (id) on delete set null,
  reviewed_at      timestamptz,
  resolution       text check (resolution is null or length(resolution) <= 1000),
  created_at       timestamptz not null default now(),
  constraint random_reports_distinct check (reporter_user_id <> target_user_id)
);

create index random_reports_status_idx on public.random_reports (status, created_at desc);
create index random_reports_session_idx on public.random_reports (session_id);
create index random_reports_target_idx on public.random_reports (target_user_id);
create index random_reports_reporter_idx on public.random_reports (reporter_user_id, created_at desc);

-- reports.random_session_id was created in 006 before this table existed.
alter table public.reports
  add constraint reports_random_session_fk
  foreign key (random_session_id) references public.random_sessions (id) on delete set null;

-- ----------------------------------------------------------------------------
-- Helpers
-- ----------------------------------------------------------------------------

create or replace function public.can_access_random_session(p_session uuid, p_user uuid default null)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.random_session_participants p
    where p.session_id = p_session
      and p.user_id = coalesce(p_user, public.current_profile_id())
      and p.left_at is null
  );
$$;

/** The other participant — used server-side only, never returned to a client. */
create or replace function public.random_other_participant(p_session uuid, p_user uuid default null)
returns uuid
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select case
    when s.participant_a = coalesce(p_user, public.current_profile_id()) then s.participant_b
    else s.participant_a
  end
  from public.random_sessions s
  where s.id = p_session
    and coalesce(p_user, public.current_profile_id()) in (s.participant_a, s.participant_b);
$$;

/** Ends any session the caller is part of (used by leave/next/block flows). */
create or replace function public.end_random_session(p_session uuid, p_reason text default 'left')
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if not public.can_access_random_session(p_session, v_me) then
    raise exception 'You are not part of this session.' using errcode = '42501';
  end if;

  -- Only a session that is still active counts as a deliberate "Next"/"End"
  -- action, so repeat calls stay idempotent (the updates below use `coalesce`)
  -- and callers do not burn rate-limit budget twice. Closing a session that a
  -- moderator already closed still marks the participant as left.
  if exists (select 1 from public.random_sessions where id = p_session and status = 'active')
     and not coalesce((public.consume_rate_limit('random_next', v_me::text, 8, 600))->>'allowed', 'true')::boolean then
    raise exception 'You are starting new Random chats too quickly. Try again shortly.' using errcode = '42901';
  end if;

  update public.random_sessions
     set status = case when status = 'active' then 'ended'::public.random_session_status else status end,
         ended_at = coalesce(ended_at, now()),
         end_reason = coalesce(end_reason, case when p_reason in ('left','next','timeout','moderation','blocked','reported') then p_reason else 'left' end),
         ended_by = coalesce(ended_by, v_me)
   where id = p_session;

  update public.random_session_participants
     set left_at = coalesce(left_at, now())
   where session_id = p_session;
end;
$$;

-- ----------------------------------------------------------------------------
-- join_random_queue — matching
-- ----------------------------------------------------------------------------

create or replace function public.join_random_queue()
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_partner uuid;
  v_session uuid;
  v_existing uuid;
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if not public.is_active_user() then
    raise exception 'Your account cannot use Random.' using errcode = '42501';
  end if;
  if not public.has_permission('use_random_chat') then
    raise exception 'Random is not enabled for your account.' using errcode = '42501';
  end if;

  -- Already in a live session? Return it instead of queueing again.
  select s.id into v_existing
  from public.random_sessions s
  join public.random_session_participants p on p.session_id = s.id
  where p.user_id = v_me and p.left_at is null and s.status = 'active'
  order by s.started_at desc
  limit 1;
  if v_existing is not null then
    return jsonb_build_object('status', 'matched', 'session_id', v_existing, 'reused', true);
  end if;

  -- Already waiting? Just report the wait.
  if exists (select 1 from public.random_queue q where q.user_id = v_me and q.status = 'waiting' and q.expires_at > now()) then
    return jsonb_build_object('status', 'waiting');
  end if;

  -- Rate limit before touching the queue: joining repeatedly is the cheapest
  -- abuse of this feature (spec §61). Enforced here as well as in the route so a
  -- direct RPC call cannot skip it.
  if not coalesce((public.consume_rate_limit('random_join', v_me::text, 12, 3600))->>'allowed', 'true')::boolean then
    raise exception 'You are joining Random too often. Try again later.' using errcode = '42901';
  end if;

  -- Clear stale entries for this user, then take a place in the queue.
  delete from public.random_queue where user_id = v_me and (status <> 'waiting' or expires_at <= now());
  insert into public.random_queue (user_id, status)
  values (v_me, 'waiting')
  on conflict (user_id) do update set joined_at = now(), expires_at = now() + interval '10 minutes', status = 'waiting';

  -- Find the longest-waiting eligible partner:
  --   * not me, active account, waiting, not expired
  --   * no block in either direction
  --   * no active session of their own
  -- `for update skip locked` makes concurrent matches safe.
  select q.user_id into v_partner
  from public.random_queue q
  where q.user_id <> v_me
    and q.status = 'waiting'
    and q.expires_at > now()
    and public.is_active_profile(q.user_id)
    and not public.is_blocked(v_me, q.user_id)
    and not exists (
      select 1 from public.random_sessions s
      join public.random_session_participants p on p.session_id = s.id
      where p.user_id = q.user_id and p.left_at is null and s.status = 'active'
    )
  order by q.joined_at asc
  limit 1
  for update skip locked;

  if v_partner is null then
    return jsonb_build_object('status', 'waiting');
  end if;

  insert into public.random_sessions (participant_a, participant_b)
  values (least(v_me, v_partner), greatest(v_me, v_partner))
  returning id into v_session;

  insert into public.random_session_participants (session_id, user_id, side)
  values
    (v_session, least(v_me, v_partner), 'a'),
    (v_session, greatest(v_me, v_partner), 'b');

  update public.random_queue
     set status = 'matched', session_id = v_session
   where user_id in (v_me, v_partner);

  return jsonb_build_object('status', 'matched', 'session_id', v_session);
end;
$$;

comment on function public.join_random_queue() is
  'Atomic matchmaking. Returns {"status":"waiting"} or {"status":"matched","session_id":...}. Never returns the partner identity.';

create or replace function public.leave_random_queue()
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  delete from public.random_queue
   where user_id = v_me and status = 'waiting';
end;
$$;

/** Poll target for the "finding someone" screen: waiting | matched | idle. */
create or replace function public.random_queue_state()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_row public.random_queue;
  v_session uuid;
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select s.id into v_session
  from public.random_sessions s
  join public.random_session_participants p on p.session_id = s.id
  where p.user_id = v_me and p.left_at is null and s.status = 'active'
  order by s.started_at desc
  limit 1;
  if v_session is not null then
    return jsonb_build_object('status', 'matched', 'session_id', v_session);
  end if;

  select * into v_row from public.random_queue q where q.user_id = v_me;
  if v_row.id is null or v_row.status <> 'waiting' or v_row.expires_at <= now() then
    return jsonb_build_object('status', 'idle');
  end if;
  return jsonb_build_object('status', 'waiting', 'joined_at', v_row.joined_at);
end;
$$;

/** The participant-facing state of a session. Contains no identities. */
create or replace function public.random_session_state(p_session uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_row public.random_sessions;
begin
  if not public.can_access_random_session(p_session, v_me) then
    return null;  -- do not distinguish "not found" from "not yours"
  end if;

  select * into v_row from public.random_sessions s where s.id = p_session;

  return jsonb_build_object(
    'id', v_row.id,
    'status', v_row.status,
    'started_at', v_row.started_at,
    'ended_at', v_row.ended_at,
    'expires_at', v_row.expires_at,
    'message_count', v_row.message_count,
    'end_reason', v_row.end_reason
  );
end;
$$;

-- ----------------------------------------------------------------------------
-- send_random_message
-- ----------------------------------------------------------------------------

create or replace function public.send_random_message(
  p_session uuid,
  p_body text,
  p_gif jsonb default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_other uuid;
  v_row public.random_messages;
  v_clean text := btrim(coalesce(p_body, ''));
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if not public.is_active_user() or not public.has_permission('use_random_chat') then
    raise exception 'You cannot send messages right now.' using errcode = '42501';
  end if;
  if not public.can_access_random_session(p_session, v_me) then
    raise exception 'You are not part of this session.' using errcode = '42501';
  end if;
  if not exists (select 1 from public.random_sessions s where s.id = p_session and s.status = 'active' and s.ended_at is null) then
    raise exception 'This conversation has ended.' using errcode = '22023';
  end if;
  if length(v_clean) > 2000 then
    raise exception 'That message is too long.' using errcode = '22023';
  end if;
  if v_clean = '' and p_gif is null then
    raise exception 'Write a message or pick a GIF.' using errcode = '22023';
  end if;
  if p_gif is not null and coalesce(p_gif->>'provider', '') <> 'giphy' then
    raise exception 'Only approved GIFs can be attached.' using errcode = '22023';
  end if;

  v_other := public.random_other_participant(p_session, v_me);
  if public.is_blocked(v_me, v_other) then
    perform public.end_random_session(p_session, 'blocked');
    raise exception 'This conversation was ended.' using errcode = '42501';
  end if;

  insert into public.random_messages (session_id, sender_user_id, content, gif)
  values (p_session, v_me, v_clean, p_gif)
  returning * into v_row;

  update public.random_sessions
     set message_count = message_count + 1
   where id = p_session;

  update public.random_session_participants
     set message_count = message_count + 1
   where session_id = p_session and user_id = v_me;

  return jsonb_build_object(
    'id', v_row.id,
    'session_id', v_row.session_id,
    'mine', true,
    'content', v_row.content,
    'gif', v_row.gif,
    'created_at', v_row.created_at
  );
end;
$$;

-- ----------------------------------------------------------------------------
-- report_random_session — the only way a participant reports
-- ----------------------------------------------------------------------------

create or replace function public.report_random_session(
  p_session uuid,
  p_reason text,
  p_details text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_other uuid;
  v_id uuid;
begin
  if not public.can_access_random_session(p_session, v_me) then
    raise exception 'You are not part of this session.' using errcode = '42501';
  end if;
  if not coalesce((public.consume_rate_limit('report_create', v_me::text, 10, 3600))->>'allowed', 'true')::boolean then
    raise exception 'You are filing reports too quickly. Try again later.' using errcode = '42901';
  end if;
  v_other := public.random_other_participant(p_session, v_me);

  insert into public.random_reports (session_id, reporter_user_id, target_user_id, reason, details)
  values (p_session, v_me, v_other, p_reason, left(p_details, 1000))
  returning id into v_id;

  insert into public.reports (reporter_id, target_type, target_id, reason, details, random_session_id)
  values (v_me, 'random_session', p_session, p_reason, left(p_details, 1000), p_session);

  update public.random_sessions set status = 'reported' where id = p_session and status = 'active';

  return v_id;
end;
$$;

comment on function public.report_random_session(uuid, text, text) is
  'Creates both the Random-specific report and the central moderation report, then flags the session.';

/** Retention helper used by operator scripts / scheduled maintenance. */
create or replace function public.purge_random_data(p_older_than_days integer default 90)
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_count integer;
begin
  if not (public.has_permission('manage_platform_settings') or public.is_trusted_writer()) then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;
  with doomed as (
    delete from public.random_sessions
    where started_at < now() - make_interval(days => greatest(p_older_than_days, 1))
      and status <> 'reported'   -- reported sessions are retained for moderation
    returning id
  )
  select count(*) into v_count from doomed;
  return coalesce(v_count, 0);
end;
$$;

-- ----------------------------------------------------------------------------
-- RLS
-- ----------------------------------------------------------------------------

alter table public.random_queue enable row level security;
alter table public.random_sessions enable row level security;
alter table public.random_session_participants enable row level security;
alter table public.random_messages enable row level security;
alter table public.random_reports enable row level security;

-- random_queue: a student only ever sees their own row, and only to know they
-- are waiting. Matching itself happens in the definer function.
create policy random_queue_select_own on public.random_queue
  for select to authenticated using (user_id = public.current_profile_id());
create policy random_queue_delete_own on public.random_queue
  for delete to authenticated using (user_id = public.current_profile_id());
create policy random_queue_select_staff on public.random_queue
  for select to authenticated using (public.has_permission('moderate_random'));

-- random_sessions: identity mapping. Staff only, and only with the explicit
-- view_random_sessions permission (the application writes an audit entry on
-- every unmasking).
create policy random_sessions_select_privileged on public.random_sessions
  for select to authenticated using (public.has_permission('view_random_sessions'));
create policy random_sessions_update_staff on public.random_sessions
  for update to authenticated
  using (public.has_permission('moderate_random'))
  with check (public.has_permission('moderate_random'));
-- No participant policies on purpose: participants read `random_session_state()`
-- and `random_session_view`, which contain no identities.

create policy random_participants_select_self on public.random_session_participants
  for select to authenticated using (user_id = public.current_profile_id());
create policy random_participants_select_privileged on public.random_session_participants
  for select to authenticated using (public.has_permission('view_random_sessions'));

-- random_messages: participants read their own session through the view below.
create policy random_messages_select_privileged on public.random_messages
  for select to authenticated using (public.has_permission('view_random_sessions'));

create policy random_reports_select_reporter on public.random_reports
  for select to authenticated using (reporter_user_id = public.current_profile_id());
create policy random_reports_select_staff on public.random_reports
  for select to authenticated
  using (public.has_permission('moderate_random') or public.has_permission('moderate_all'));
create policy random_reports_update_staff on public.random_reports
  for update to authenticated
  using (public.has_permission('moderate_random') or public.has_permission('moderate_all'))
  with check (public.has_permission('moderate_random') or public.has_permission('moderate_all'));

-- ----------------------------------------------------------------------------
-- Participant-facing projections (definer views: they intentionally read the
-- identity tables, but whitelist columns so no identity can escape)
-- ----------------------------------------------------------------------------

create view public.random_session_view
as
select
  s.id,
  s.status,
  s.started_at,
  s.ended_at,
  s.end_reason,
  s.message_count,
  s.expires_at,
  p.side as my_side
from public.random_sessions s
join public.random_session_participants p
  on p.session_id = s.id
 and p.user_id = public.current_profile_id()
where p.left_at is null;

comment on view public.random_session_view is
  'Participant-safe session projection: no participant ids, no usernames, no profile data.';

create view public.random_messages_view
as
select
  m.id,
  m.session_id,
  (m.sender_user_id = public.current_profile_id()) as mine,
  m.content,
  m.gif,
  m.created_at,
  m.status
from public.random_messages m
where exists (
  select 1 from public.random_session_participants p
  where p.session_id = m.session_id
    and p.user_id = public.current_profile_id()
);

comment on view public.random_messages_view is
  'Participant-safe message stream. `sender_user_id` is mapped to a boolean `mine` flag so the other student cannot be identified.';

-- ----------------------------------------------------------------------------
-- Session housekeeping: expire queue entries and long-running sessions
-- ----------------------------------------------------------------------------

create or replace function public.sweep_random_state()
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_queue integer;
  v_sessions integer;
begin
  with gone as (
    delete from public.random_queue
    where status = 'waiting' and expires_at <= now()
    returning 1
  )
  select count(*) into v_queue from gone;

  with closed as (
    update public.random_sessions
       set status = 'expired', ended_at = now(), end_reason = 'timeout'
     where status = 'active'
       and (expires_at <= now() or now() - started_at > make_interval(mins => 60))
    returning 1
  )
  select count(*) into v_sessions from closed;

  return jsonb_build_object('queue_expired', coalesce(v_queue, 0), 'sessions_expired', coalesce(v_sessions, 0));
end;
$$;

comment on function public.sweep_random_state() is
  'Callable by any authenticated user (it only expires stale rows) and by the scheduled maintenance script.';

-- ==========================================================================
-- FILE 11/25  20261005000011_011_platform.sql
-- ==========================================================================

-- Campus+ migration 011 — platform
-- Supabase CLI filename: 20261005000011_011_platform.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 011 — settings, feature flags, rate limiting, search, feed, trending
-- =============================================================================
-- Everything here is deterministic and configuration-driven (spec §18, §76,
-- §77). No AI, no ranking service, no external search engine: PostgreSQL does
-- full-text search, tsvector + GIN indexes do the work, and the trending
-- formula is readable in one line of SQL.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- platform_settings — Admin/Super Admin controlled
-- ----------------------------------------------------------------------------

create table public.platform_settings (
  key         text primary key check (length(btrim(key)) between 1 and 80),
  value       jsonb not null,
  description text,
  category    text not null default 'general',
  is_public   boolean not null default false,
  updated_by  uuid references public.profiles (id) on delete set null,
  updated_at  timestamptz not null default now(),
  created_at  timestamptz not null default now()
);

comment on table public.platform_settings is
  'Runtime configuration. Changing a value is a Super Admin/Admin action and is audited.';

create trigger platform_settings_touch before update on public.platform_settings
  for each row execute function public.touch_updated_at();

-- ----------------------------------------------------------------------------
-- feature_flags — module on/off without deleting code (spec §77)
-- ----------------------------------------------------------------------------

create table public.feature_flags (
  key         text primary key check (length(btrim(key)) between 1 and 80),
  label       text not null,
  description text,
  group_name  text not null default 'general',
  enabled     boolean not null default true,
  updated_by  uuid references public.profiles (id) on delete set null,
  updated_at  timestamptz not null default now()
);

create trigger feature_flags_touch before update on public.feature_flags
  for each row execute function public.touch_updated_at();

create or replace function public.feature_enabled(p_key text)
returns boolean
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_enabled boolean;
begin
  select enabled into v_enabled from public.feature_flags where key = p_key;
  -- Unknown flags are treated as enabled so a missing row can never hide a
  -- module from the whole campus.
  return coalesce(v_enabled, true);
end;
$$;

create or replace function public.setting(p_key text, p_default jsonb default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_value jsonb;
begin
  select value into v_value from public.platform_settings where key = p_key;
  return coalesce(v_value, p_default);
end;
$$;

create or replace function public.setting_int(p_key text, p_default integer)
returns integer
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_value jsonb := public.setting(p_key, null);
begin
  if v_value is null or jsonb_typeof(v_value) <> 'number' then
    return p_default;
  end if;
  return (v_value)::text::integer;
end;
$$;

-- ----------------------------------------------------------------------------
-- rate_limits (spec §61). No Redis, no external service.
-- ----------------------------------------------------------------------------

create table public.rate_limits (
  bucket       text not null,
  key          text not null,
  window_start timestamptz not null default now(),
  counter      integer not null default 0,
  primary key (bucket, key)
);

comment on table public.rate_limits is
  'Rolling-window counters. RLS is enabled with no policies: only consume_rate_limit() (definer) reads or writes this table.';

create or replace function public.consume_rate_limit(
  p_bucket text,
  p_key text,
  p_limit integer,
  p_window_seconds integer
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_count integer;
  v_start timestamptz;
  v_reset_at timestamptz;
begin
  if p_bucket is null or p_key is null or p_limit is null or p_window_seconds is null then
    raise exception 'consume_rate_limit requires bucket, key, limit and window.' using errcode = '22023';
  end if;

  -- A student may only consume their own bucket. Server-side jobs (secret key)
  -- may use any key, which is how pre-authentication limits are applied.
  if not public.is_trusted_writer()
     and p_key <> coalesce(public.current_profile_id()::text, '') then
    raise exception 'Rate limit key mismatch.' using errcode = '42501';
  end if;

  insert into public.rate_limits (bucket, key, window_start, counter)
  values (p_bucket, p_key, now(), 1)
  on conflict (bucket, key) do update
    set counter = case
          when public.rate_limits.window_start < now() - make_interval(secs => p_window_seconds) then 1
          else public.rate_limits.counter + 1
        end,
        window_start = case
          when public.rate_limits.window_start < now() - make_interval(secs => p_window_seconds) then now()
          else public.rate_limits.window_start
        end
  returning counter, window_start into v_count, v_start;

  v_reset_at := v_start + make_interval(secs => p_window_seconds);

  return jsonb_build_object(
    'allowed', v_count <= p_limit,
    'remaining', greatest(p_limit - v_count, 0),
    'retry_after_seconds', greatest(ceil(extract(epoch from (v_reset_at - now())))::integer, 0)
  );
end;
$$;

create or replace function public.reset_rate_limit(p_bucket text, p_key text)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not (public.has_permission('manage_platform_settings') or public.is_trusted_writer()) then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;
  delete from public.rate_limits where bucket = p_bucket and key = p_key;
end;
$$;

-- ----------------------------------------------------------------------------
-- Global search (spec §54, §86)
-- ----------------------------------------------------------------------------
-- SECURITY INVOKER on purpose: every table read inside is filtered by its own
-- RLS policy, which is what makes search respect blocks, visibility, account
-- status, community privacy and conversation privacy without a second
-- authorization implementation.

create or replace function public.global_search(
  p_query text,
  p_scope text default 'all',
  p_limit integer default 20,
  p_offset integer default 0
)
returns table (
  scope text,
  id uuid,
  title text,
  subtitle text,
  snippet text,
  url text,
  meta jsonb,
  rank real
)
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
with params as (
  select
    nullif(btrim(coalesce(p_query, '')), '') as q,
    least(greatest(coalesce(p_limit, 20), 1), 50) as lim,
    greatest(coalesce(p_offset, 0), 0) as off,
    coalesce(p_scope, 'all') as scope
),
needle as (
  select
    q,
    lim,
    off,
    scope,
    '%' || replace(replace(q, '%', '\%'), '_', '\_') || '%' as like_q,
    websearch_to_tsquery('english', q) as tsq
  from params
  where q is not null and length(q) >= 2
)
select * from (
(
  -- people ------------------------------------------------------------------
  select
    'people'::text as scope,
    p.id,
    p.username as title,
    coalesce(nullif(p.display_name, ''), '@' || p.username) as subtitle,
    coalesce(p.bio, '') as snippet,
    '/user/' || p.username as url,
    jsonb_build_object(
      'branch', case when p.show_branch_year then p.branch else null end,
      'year', case when p.show_branch_year then p.year else null end,
      'reputation_score', p.reputation_score
    ) as meta,
    greatest(
      similarity(p.username, n.q),
      similarity(coalesce(p.display_name, ''), n.q) * 0.8
    )::real as rank
  from public.profiles p, needle n
  where n.scope in ('all', 'people')
    and public.is_active_profile(p.id)
    and not public.is_blocked_with_current(p.id)
    and (p.username ilike n.like_q or p.display_name ilike n.like_q)
  order by rank desc
  limit (select lim from params)
  )
  union all
(
  -- posts & discussions -----------------------------------------------------
  select
    case when po.kind = 'discussion' then 'discussions' else 'posts' end,
    po.id,
    coalesce(po.title, nullif(left(po.body, 80), '')),
    '@' || pr.username,
    left(po.body, 200),
    '/post/' || po.id::text,
    jsonb_build_object(
      'kind', po.kind,
      'is_official', po.is_official,
      'created_at', po.created_at,
      'reaction_count', po.reaction_count,
      'comment_count', po.comment_count
    ),
    ts_rank(po.search_vector, n.tsq)
  from public.posts po
  join public.profiles pr on pr.id = po.author_id
  cross join needle n
  where n.scope in ('all', 'posts', 'discussions')
    and (n.scope <> 'discussions' or po.kind = 'discussion')
    and po.status = 'published'
    and po.deleted_at is null
    and (po.search_vector @@ n.tsq or po.body ilike n.like_q or coalesce(po.title, '') ilike n.like_q)
  )
  union all
(
  -- communities / study groups / clubs --------------------------------------
  select
    case c.kind
      when 'study_group' then 'communities'
      when 'club' then 'clubs'
      else 'communities'
    end,
    c.id,
    c.name,
    case c.kind when 'club' then 'Club' when 'study_group' then 'Study group' else 'Community' end,
    left(c.description, 200),
    case c.kind
      when 'club' then '/campus/clubs/' || c.id::text
      else '/communities/' || c.slug
    end,
    jsonb_build_object('kind', c.kind, 'member_count', c.member_count, 'visibility', c.visibility),
    ts_rank(to_tsvector('english', c.name || ' ' || c.description), n.tsq)
  from public.communities c
  cross join needle n
  where n.scope in ('all', 'communities', 'clubs')
    and (n.scope <> 'clubs' or c.kind = 'club')
    and c.status = 'published'
    and public.can_view_community(c.id)
    and (c.name ilike n.like_q or c.description ilike n.like_q)
  )
  union all
(
  -- marketplace listings ----------------------------------------------------
  select
    'marketplace',
    l.id,
    l.title,
    case when l.is_free then 'Free' else '₹' || coalesce(l.price, 0)::text end,
    left(l.description, 200),
    '/market/listing/' || l.id::text,
    jsonb_build_object('price', l.price, 'is_free', l.is_free, 'condition', l.condition, 'status', l.status),
    ts_rank(l.search_vector, n.tsq)
  from public.marketplace_listings l
  cross join needle n
  where n.scope in ('all', 'marketplace')
    and l.status in ('active', 'reserved')
    and public.feature_enabled('marketplace')
    and (l.search_vector @@ n.tsq or l.title ilike n.like_q)
  )
  union all
(
  -- gigs --------------------------------------------------------------------
  select
    'marketplace',
    g.id,
    g.title,
    'Gig · ' || g.category,
    left(g.description, 200),
    '/market/gigs/' || g.id::text,
    jsonb_build_object('kind', 'gig', 'compensation', g.compensation),
    ts_rank(g.search_vector, n.tsq)
  from public.gigs g
  cross join needle n
  where n.scope in ('all', 'marketplace')
    and g.status = 'published'
    and public.feature_enabled('gigs')
    and (g.search_vector @@ n.tsq or g.title ilike n.like_q)
  )
  union all
(
  -- events ------------------------------------------------------------------
  select
    'events',
    e.id,
    e.title,
    'Event · ' || to_char(e.starts_on, 'DD Mon YYYY'),
    left(e.description, 200),
    '/campus/events/' || e.id::text,
    jsonb_build_object('starts_on', e.starts_on, 'location', e.location),
    ts_rank(e.search_vector, n.tsq)
  from public.events e
  cross join needle n
  where n.scope in ('all', 'events')
    and e.status = 'published'
    and public.feature_enabled('events')
    and (e.search_vector @@ n.tsq or e.title ilike n.like_q)
  )
  union all
(
  -- resources ---------------------------------------------------------------
  select
    'resources',
    r.id,
    r.title,
    coalesce(r.subject, '') || case when r.is_official then ' · Official' else ' · Community' end,
    left(r.description, 200),
    '/explore/resources/' || r.id::text,
    jsonb_build_object('type', r.type, 'is_official', r.is_official),
    ts_rank(r.search_vector, n.tsq)
  from public.official_resources r
  cross join needle n
  where n.scope in ('all', 'resources')
    and r.status = 'published'
    and (r.search_vector @@ n.tsq or r.title ilike n.like_q)
  )
  union all
(
  -- opportunities -----------------------------------------------------------
  select
    'opportunities',
    o.id,
    o.title,
    o.organization || case when o.source = 'official' then ' · Official' else ' · Community' end,
    left(o.description, 200),
    '/explore/opportunities/' || o.id::text,
    jsonb_build_object('deadline', o.deadline, 'mode', o.mode, 'source', o.source),
    ts_rank(o.search_vector, n.tsq)
  from public.opportunities o
  cross join needle n
  where n.scope in ('all', 'opportunities')
    and o.status = 'published'
    and (o.search_vector @@ n.tsq or o.title ilike n.like_q)
  )
  union all
(
  -- projects ----------------------------------------------------------------
  select
    'projects',
    pr.id,
    pr.title,
    pr.technologies,
    left(pr.description, 200),
    '/explore/projects/' || pr.id::text,
    jsonb_build_object('reaction_count', pr.reaction_count),
    ts_rank(pr.search_vector, n.tsq)
  from public.projects pr
  cross join needle n
  where n.scope in ('all', 'projects')
    and pr.status = 'published'
    and (pr.search_vector @@ n.tsq or pr.title ilike n.like_q)
  )
) results
order by rank desc, title asc
limit (select lim from params)
offset (select off from params);
$$;

comment on function public.global_search(text, text, integer, integer) is
  'Conventional PostgreSQL search across public entities. SECURITY INVOKER so RLS enforces blocks, visibility and privacy.';

-- ----------------------------------------------------------------------------
-- Trending — deterministic, readable, no machine learning (spec §18)
-- ----------------------------------------------------------------------------
--   score = (reactions*2 + comments*3 + participants) / (age_hours + 2)^1.5
-- `participants` counts distinct commenters, so a thread with many voices
-- outranks a thread with many self-replies.

create or replace function public.trending_posts(
  p_limit integer default 20,
  p_hours integer default 72
)
returns table (
  id uuid,
  author_id uuid,
  username text,
  display_name text,
  title text,
  body text,
  kind public.post_kind,
  gif jsonb,
  reaction_count integer,
  comment_count integer,
  participant_count integer,
  created_at timestamptz,
  score real
)
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  select
    p.id,
    p.author_id,
    pr.username,
    pr.display_name,
    p.title,
    p.body,
    p.kind,
    p.gif,
    p.reaction_count,
    p.comment_count,
    coalesce(c.participants, 0) as participant_count,
    p.created_at,
    (
      (p.reaction_count * 2 + p.comment_count * 3 + coalesce(c.participants, 0))::numeric
      / power(
          greatest(extract(epoch from (now() - p.created_at)) / 3600.0, 0) + 2,
          1.5
        )
    )::real as score
  from public.posts p
  join public.profiles pr on pr.id = p.author_id
  left join (
    select cm.post_id, count(distinct cm.author_id) as participants
    from public.comments cm
    where cm.status = 'published' and cm.deleted_at is null
    group by cm.post_id
  ) c on c.post_id = p.id
  where p.status = 'published'
    and p.deleted_at is null
    and p.created_at > now() - make_interval(hours => greatest(p_hours, 1))
  order by score desc, p.created_at desc
  limit least(greatest(coalesce(p_limit, 20), 1), 50);
$$;

comment on function public.trending_posts(integer, integer) is
  'Deterministic trending score documented in lib/constants.js#TRENDING_FORMULA.';

-- ----------------------------------------------------------------------------
-- Campus feed — one query, transparent ordering (spec §17)
-- ----------------------------------------------------------------------------

create or replace function public.campus_feed(
  p_limit integer default 20,
  p_offset integer default 0,
  p_sort text default 'newest'
)
returns table (
  item_type text,
  id uuid,
  title text,
  body text,
  gif jsonb,
  author_username text,
  author_display_name text,
  is_official boolean,
  community_slug text,
  meta jsonb,
  created_at timestamptz,
  sort_at timestamptz
)
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with items as (
    -- student posts and discussions
    select
      case when p.kind = 'discussion' then 'discussion' else 'post' end as item_type,
      p.id,
      p.title,
      p.body,
      p.gif,
      pr.username as author_username,
      pr.display_name as author_display_name,
      p.is_official,
      c.slug as community_slug,
      jsonb_build_object(
        'kind', p.kind,
        'reaction_count', p.reaction_count,
        'comment_count', p.comment_count,
        'pinned', p.pinned
      ) as meta,
      p.created_at,
      p.created_at as sort_at
    from public.posts p
    join public.profiles pr on pr.id = p.author_id
    left join public.communities c on c.id = p.community_id
    where p.community_id is null
      and p.status = 'published'
      and p.deleted_at is null
      and public.feature_enabled('feed')

    union all

    -- official notices
    select
      'notice',
      n.id,
      n.title,
      n.body,
      null,
      null,
      null,
      true,
      null,
      jsonb_build_object('category', n.category, 'importance', n.importance, 'pinned', n.pinned),
      coalesce(n.published_at, n.created_at),
      case when n.pinned then now() + interval '1 day' else coalesce(n.published_at, n.created_at) end
    from public.notices n
    where n.status = 'published'
      and (n.expires_at is null or n.expires_at > now())
      and public.feature_enabled('noticeboard')

    union all

    -- upcoming events
    select
      'event',
      e.id,
      e.title,
      e.description,
      null,
      null,
      null,
      true,
      null,
      jsonb_build_object('starts_on', e.starts_on, 'start_time', e.start_time, 'location', e.location, 'organizer', e.organizer),
      e.created_at,
      case when e.starts_on <= current_date then now() else (e.starts_on::timestamptz) end
    from public.events e
    where e.status = 'published'
      and (e.ends_on is null or e.ends_on >= current_date)
      and public.feature_enabled('events')

    union all

    -- published opportunities
    select
      'opportunity',
      o.id,
      o.title,
      o.description,
      null,
      null,
      null,
      o.source = 'official',
      null,
      jsonb_build_object('organization', o.organization, 'deadline', o.deadline, 'source', o.source),
      o.created_at,
      o.created_at
    from public.opportunities o
    where o.status = 'published'
      and public.feature_enabled('opportunities')

    union all

    -- active marketplace highlights
    select
      'listing',
      l.id,
      l.title,
      l.description,
      null,
      pr.username,
      pr.display_name,
      false,
      null,
      jsonb_build_object('price', l.price, 'is_free', l.is_free, 'condition', l.condition),
      l.created_at,
      l.created_at
    from public.marketplace_listings l
    join public.profiles pr on pr.id = l.seller_id
    where l.status = 'active'
      and public.feature_enabled('marketplace')
      and public.setting('feed_marketplace_highlights', 'true'::jsonb) = 'true'::jsonb
  )
  select *
  from items
  order by
    case when p_sort = 'trending' then null else sort_at end desc nulls last,
    -- deterministic secondary signal for trending: engagement density
    case when p_sort = 'trending'
      then coalesce((meta->>'reaction_count')::int, 0) * 2 + coalesce((meta->>'comment_count')::int, 0) * 3
      else 0 end desc
  limit least(greatest(coalesce(p_limit, 20), 1), 50)
  offset greatest(coalesce(p_offset, 0), 0);
$$;

comment on function public.campus_feed(integer, integer, text) is
  'Unified home feed. Ordering is explicit: newest by timestamp, or trending by the documented engagement formula.';

-- ----------------------------------------------------------------------------
-- Achievements — deterministic evaluation (spec §51)
-- ----------------------------------------------------------------------------

create or replace function public.evaluate_achievements(p_user uuid default null)
returns text[]
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_user uuid := coalesce(p_user, public.current_profile_id());
  v_awarded text[] := '{}';
  v_posts integer;
  v_communities integer;
  v_comment_reactions integer;
  v_rsvps integer;
  v_sold integer;
  v_projects integer;
begin
  if v_user is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if not (public.is_trusted_writer() or p_user is null or p_user = public.current_profile_id() or public.is_staff()) then
    raise exception 'Not permitted.' using errcode = '42501';
  end if;

  select count(*) into v_posts from public.posts where author_id = v_user;
  select count(*) into v_communities from public.communities where created_by = v_user;
  select coalesce(sum(c.reaction_count), 0) into v_comment_reactions from public.comments c where c.author_id = v_user;
  select count(*) into v_rsvps from public.event_registrations where user_id = v_user;
  select count(*) into v_sold from public.marketplace_listings where seller_id = v_user and status = 'sold';
  select count(*) into v_projects from public.projects where creator_id = v_user;

  with rules as (
    select 'early_contributor'::text as key, v_posts >= 1 as met
    union all select 'community_builder', v_communities >= 1
    union all select 'helpful_member', v_comment_reactions >= 10
    union all select 'event_participant', v_rsvps >= 1
    union all select 'marketplace_seller', v_sold >= 1
    union all select 'project_showcase_contributor', v_projects >= 1
  ),
  awarded as (
    insert into public.user_achievements (user_id, achievement_key)
    select v_user, r.key
    from rules r
    join public.achievements a on a.key = r.key and a.is_active
    where r.met
    on conflict (user_id, achievement_key) do nothing
    returning achievement_key
  )
  select coalesce(array_agg(achievement_key), '{}') into v_awarded from awarded;

  return v_awarded;
end;
$$;

comment on function public.evaluate_achievements(uuid) is
  'Grants achievements whose documented deterministic rule is satisfied. Idempotent.';

-- ----------------------------------------------------------------------------
-- RLS
-- ----------------------------------------------------------------------------

alter table public.platform_settings enable row level security;
alter table public.feature_flags enable row level security;
alter table public.rate_limits enable row level security;

-- settings: everyone needs a few public values (platform name); the rest is for
-- administrators.
create policy platform_settings_select_public on public.platform_settings
  for select to authenticated using (is_public or public.has_permission('manage_platform_settings'));
create policy platform_settings_manage on public.platform_settings
  for all to authenticated
  using (public.has_permission('manage_platform_settings'))
  with check (public.has_permission('manage_platform_settings'));

create policy feature_flags_select_all on public.feature_flags
  for select to authenticated using (true);
create policy feature_flags_manage on public.feature_flags
  for all to authenticated
  using (public.has_permission('manage_feature_flags'))
  with check (public.has_permission('manage_feature_flags'));

-- rate_limits: intentionally no policies. Only the definer function touches it.

-- ==========================================================================
-- FILE 12/25  20261005000012_012_auth_hooks.sql
-- ==========================================================================

-- Campus+ migration 012 — auth hooks
-- Supabase CLI filename: 20261005000012_012_auth_hooks.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 012 — auth hooks, onboarding, username rules
-- =============================================================================
-- The institutional domain restriction is enforced HERE, in the database, at
-- the moment an auth user is created (spec §8). A caller cannot bypass it with a
-- crafted request to the Auth API, because the trigger raises and the insert
-- rolls back.
--
-- Onboarding (username + display name + optional details) also happens through
-- definer functions so that username uniqueness, the reserved list and the
-- change cooldown cannot be dodged by writing to the tables directly.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- reserved_usernames — mirrored from lib/constants.js RESERVED_USERNAMES
-- ----------------------------------------------------------------------------

create table public.reserved_usernames (
  username text primary key check (username ~ '^[a-z0-9_]{2,30}$'),
  reason   text,
  created_at timestamptz not null default now()
);

create or replace function public.is_reserved_username(p_username text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (select 1 from public.reserved_usernames r where r.username = lower(coalesce(p_username, '')));
$$;

-- ----------------------------------------------------------------------------
-- Domain gate
-- ----------------------------------------------------------------------------

create or replace function public.allowed_email_domain(p_email text)
returns boolean
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_domain text;
  v_setting jsonb;
begin
  v_domain := lower(split_part(coalesce(p_email, ''), '@', 2));
  if v_domain = '' then
    return false;
  end if;

  -- Database configuration wins…
  begin
    select value into v_setting from public.platform_settings where key = 'allowed_email_domains';
  exception when undefined_table then
    v_setting := null;
  end;

  if v_setting is not null and jsonb_typeof(v_setting) = 'array' then
    if exists (
      select 1 from jsonb_array_elements_text(v_setting) d
      where lower(d) = v_domain
    ) then
      return true;
    end if;
  end if;

  -- …then the college row…
  if public.college_for_domain(v_domain) is not null then
    return true;
  end if;

  -- …and finally the deployment default stored on the college row itself.
  return false;
end;
$$;

comment on function public.allowed_email_domain(text) is
  'Server-side institutional domain check. Used by the auth trigger, so it cannot be bypassed from the client.';

create or replace function public.enforce_institutional_domain()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_email text := coalesce(new.email, '');
begin
  -- Only enforce when an email is present (phone-only or OAuth sign-ups are not
  -- part of Campus+ and are rejected by configuration anyway).
  if v_email = '' then
    raise exception 'Campus+ requires an institutional email address.'
      using errcode = '42501';
  end if;

  if not public.allowed_email_domain(v_email) then
    raise exception 'Campus+ is limited to approved institutional email addresses (%).',
      coalesce((select string_agg('@' || d, ', ') from public.colleges c, unnest(c.email_domains) d where c.is_active), '@pccoepune.org')
      using errcode = '42501';
  end if;

  return new;
end;
$$;

drop trigger if exists enforce_institutional_domain_trigger on auth.users;
create trigger enforce_institutional_domain_trigger
  before insert on auth.users
  for each row execute function public.enforce_institutional_domain();

-- ----------------------------------------------------------------------------
-- Profile provisioning
-- ----------------------------------------------------------------------------

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_email text := lower(coalesce(new.email, ''));
  v_domain text := lower(split_part(coalesce(new.email, ''), '@', 2));
  v_college uuid;
  v_profile uuid;
  v_display text;
begin
  v_college := public.college_for_domain(v_domain);
  if v_college is null then
    raise exception 'No Campus+ college is configured for @%.', v_domain using errcode = '42501';
  end if;

  v_display := coalesce(
    nullif(btrim(coalesce(new.raw_user_meta_data->>'display_name', '')), ''),
    initcap(replace(split_part(v_email, '@', 1), '.', ' '))
  );

  -- Mark the provisioning work so guards such as prevent_privilege_escalation()
  -- know this is the database's own baseline setup, not a client asking for a
  -- role. Transaction-local: it disappears when this trigger's transaction ends.
  perform set_config('campus.system_context', 'on', true);

  insert into public.profiles (display_name)
  values (left(v_display, 60))
  returning id into v_profile;

  insert into public.profile_private (
    profile_id, auth_user_id, college_id, account_status, profile_completed
  ) values (
    v_profile, new.id, v_college, 'active', false
  );

  -- Baseline role. Additional roles are granted deliberately and audited.
  insert into public.user_roles (user_id, role_key)
  values (v_profile, 'student')
  on conflict do nothing;

  -- The first username_history row is written by complete_profile() once the
  -- student actually claims a handle.

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

comment on function public.handle_new_user() is
  'Creates profiles + profile_private + the student role for each new auth user. Username is chosen during onboarding.';
-- ----------------------------------------------------------------------------
-- Hard-delete cleanup
-- ----------------------------------------------------------------------------
-- Deleting an auth user cascades into profile_private but cannot reach
-- `profiles` (that FK points the other way), which used to leave an orphaned
-- public identity behind. Removing the profile here lets the rest of the
-- cascade chain run: content, memberships and reports follow the profile.

create or replace function public.cleanup_deleted_profile()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  delete from public.profiles where id = old.profile_id;
  return old;
end;
$$;

comment on function public.cleanup_deleted_profile() is
  'Keeps the public identity in step with the auth record when an account is hard-deleted.';

drop trigger if exists profile_private_cleanup on public.profile_private;
create trigger profile_private_cleanup
  after delete on public.profile_private
  for each row execute function public.cleanup_deleted_profile();



-- ----------------------------------------------------------------------------
-- Onboarding: complete_profile
-- ----------------------------------------------------------------------------

create or replace function public.complete_profile(
  p_username text,
  p_display_name text,
  p_bio text default null,
  p_branch text default null,
  p_year text default null,
  p_division text default null,
  p_show_branch_year boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_username text := lower(btrim(coalesce(p_username, '')));
  v_display text := btrim(coalesce(p_display_name, ''));
  v_existing text;
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  -- Validation mirrors lib/validation/schemas.js#vUsername (defence in depth:
  -- the database is the last word).
  if v_username !~ '^[a-z0-9_]{3,24}$' then
    raise exception 'Usernames must be 3-24 characters using lowercase letters, numbers and underscores.'
      using errcode = '22023';
  end if;
  if v_username ~ '^_|_$' or v_username ~ '__' then
    raise exception 'Usernames cannot start or end with an underscore, or repeat one.'
      using errcode = '22023';
  end if;
  if v_username ~ '^[0-9]+$' then
    raise exception 'Usernames cannot be only numbers.' using errcode = '22023';
  end if;
  if public.is_reserved_username(v_username) then
    raise exception 'That username is reserved by the platform.' using errcode = '22023';
  end if;
  if length(v_display) < 2 or length(v_display) > 60 then
    raise exception 'Display name must be between 2 and 60 characters.' using errcode = '22023';
  end if;
  if length(coalesce(p_bio, '')) > 280 then
    raise exception 'Bio must be at most 280 characters.' using errcode = '22023';
  end if;

  select username into v_existing from public.profiles where id = v_me;
  if v_existing is not null and v_existing <> v_username then
    raise exception 'Your username can be changed from Settings once the cooldown passes.'
      using errcode = '22023';
  end if;

  if exists (select 1 from public.profiles p where lower(p.username) = v_username and p.id <> v_me) then
    raise exception 'That username is already taken.' using errcode = '23505';
  end if;

  update public.profiles
     set username = v_username,
         display_name = v_display,
         bio = nullif(btrim(coalesce(p_bio, '')), ''),
         branch = nullif(btrim(coalesce(p_branch, '')), ''),
         year = nullif(btrim(coalesce(p_year, '')), ''),
         division = nullif(btrim(coalesce(p_division, '')), ''),
         show_branch_year = coalesce(p_show_branch_year, true)
   where id = v_me;

  update public.profile_private
     set profile_completed = true,
         username_changed_at = coalesce(username_changed_at, now()),
         last_seen = now()
   where profile_id = v_me;

  insert into public.username_history (user_id, old_username, new_username, changed_by)
  values (v_me, v_existing, v_username, v_me);

  perform public.evaluate_achievements(v_me);

  insert into public.audit_logs (actor_user_id, action, target_type, target_id, metadata, visibility)
  values (v_me, 'account.profile_created', 'user', v_me, jsonb_build_object('username', v_username), 'private');

  return jsonb_build_object('ok', true, 'username', v_username);
exception
  when unique_violation then
    raise exception 'That username is already taken.' using errcode = '23505';
end;
$$;

comment on function public.complete_profile is
  'First-login onboarding: claims a unique username and completes the profile.';

-- ----------------------------------------------------------------------------
-- Username changes with a configurable cooldown
-- ----------------------------------------------------------------------------

create or replace function public.change_username(p_new_username text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_username text := lower(btrim(coalesce(p_new_username, '')));
  v_old text;
  v_changed_at timestamptz;
  v_cooldown integer;
  v_days_left integer;
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if not public.is_active_user() then
    raise exception 'Your account cannot change its username.' using errcode = '42501';
  end if;
  if v_username !~ '^[a-z0-9_]{3,24}$' or v_username ~ '^_|_$' or v_username ~ '__' or v_username ~ '^[0-9]+$' then
    raise exception 'Usernames must be 3-24 characters: lowercase letters, numbers and single underscores.'
      using errcode = '22023';
  end if;
  if public.is_reserved_username(v_username) then
    raise exception 'That username is reserved by the platform.' using errcode = '22023';
  end if;

  select p.username, pp.username_changed_at into v_old, v_changed_at
  from public.profiles p
  join public.profile_private pp on pp.profile_id = p.id
  where p.id = v_me;

  if v_old = v_username then
    raise exception 'That is already your username.' using errcode = '22023';
  end if;

  v_cooldown := coalesce(public.setting_int('username_change_cooldown_days', 30), 30);
  if v_changed_at is not null and now() < v_changed_at + make_interval(days => greatest(v_cooldown, 0)) then
    v_days_left := ceil(extract(epoch from (v_changed_at + make_interval(days => v_cooldown) - now())) / 86400.0)::integer;
    raise exception 'You can change your username again in % day(s).', greatest(v_days_left, 1)
      using errcode = '22023';
  end if;

  if exists (select 1 from public.profiles p where lower(p.username) = v_username and p.id <> v_me) then
    raise exception 'That username is already taken.' using errcode = '23505';
  end if;

  update public.profiles set username = v_username where id = v_me;
  update public.profile_private set username_changed_at = now() where profile_id = v_me;

  insert into public.username_history (user_id, old_username, new_username, changed_by)
  values (v_me, v_old, v_username, v_me);

  perform public.log_audit('account.username_changed', 'user', v_me::text,
    jsonb_build_object('old_username', v_old, 'new_username', v_username), false, null, 'private');

  return jsonb_build_object('ok', true, 'username', v_username);
exception
  when unique_violation then
    raise exception 'That username is already taken.' using errcode = '23505';
end;
$$;

create or replace function public.username_change_available_at()
returns timestamptz
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_changed_at timestamptz;
  v_cooldown integer;
begin
  select username_changed_at into v_changed_at
  from public.profile_private where profile_id = public.current_profile_id();
  v_cooldown := coalesce(public.setting_int('username_change_cooldown_days', 30), 30);
  if v_changed_at is null then
    return now();
  end if;
  return v_changed_at + make_interval(days => greatest(v_cooldown, 0));
end;
$$;

-- ----------------------------------------------------------------------------
-- Presence-free activity marker (spec §102: never displayed, retention only)
-- ----------------------------------------------------------------------------

create or replace function public.touch_last_seen()
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  update public.profile_private
     set last_seen = now()
   where profile_id = public.current_profile_id();
end;
$$;

comment on function public.touch_last_seen() is
  'Records coarse retention/last activity for the owner only. There is no online/offline indicator anywhere in the product.';

-- ----------------------------------------------------------------------------
-- Suspension lifecycle: lift expired suspensions automatically
-- ----------------------------------------------------------------------------

create or replace function public.lift_expired_suspensions()
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_count integer;
begin
  with lifted as (
    update public.profile_private
       set account_status = 'active', suspended_until = null, status_reason = null
     where account_status = 'suspended'
       and suspended_until is not null
       and suspended_until <= now()
    returning 1
  )
  select count(*) into v_count from lifted;
  return coalesce(v_count, 0);
end;
$$;

comment on function public.lift_expired_suspensions() is
  'Marks temporary suspensions as over. Called on sign-in and by the maintenance script.';

