-- Identity/config tables are never client-updatable; use the admin actions.
revoke update on public.user_roles from authenticated, anon;
revoke update on public.roles from authenticated, anon;
revoke update on public.role_permissions from authenticated, anon;
revoke update on public.platform_settings from authenticated, anon;
revoke update on public.feature_flags from authenticated, anon;
revoke update on public.reserved_usernames from authenticated, anon;

-- Service role and operators keep full access (they are the maintenance path).
grant all on all tables in schema public to service_role;

-- ==========================================================================
-- FILE 16/25  20261005000016_016_staff_actions.sql
-- ==========================================================================

-- Campus+ migration 016 — staff actions
-- Supabase CLI filename: 20261005000016_016_staff_actions.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 016 — privileged actions (moderation, roles, account lifecycle)
-- =============================================================================
-- Every privileged transition is a single SECURITY DEFINER function that:
--   1. checks the caller's permission (the same `has_permission()` used by RLS),
--   2. checks the staffing hierarchy (nobody acts on a peer or a senior),
--   3. performs the change,
--   4. writes a moderation action and an audit entry (spec §59, §105),
--   5. notifies the affected student where that is appropriate.
--
-- Because column privileges (015) make these columns unwritable by clients, this
-- file is the ONLY way privileged state changes happen.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- Role assignment
-- ----------------------------------------------------------------------------

create or replace function public.grant_role(p_user uuid, p_role text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_rank integer;
  v_username text;
begin
  -- Operator context (secret key / maintenance script) may always assign roles.
  if not (public.has_permission('assign_roles') or public.is_trusted_writer()) then
    raise exception 'You do not have permission to assign roles.' using errcode = '42501';
  end if;
  select p.username into v_username from public.profiles p where p.id = p_user;
  if v_username is null then
    raise exception 'That student could not be found.' using errcode = '22023';
  end if;

  select r.rank into v_rank from public.roles r where r.key = p_role;
  if v_rank is null then
    raise exception 'That role does not exist.' using errcode = '22023';
  end if;
  if not public.is_trusted_writer() then
    if p_role = 'super_admin'
       and not (public.has_role('super_admin') and public.has_permission('manage_role_authority')) then
      raise exception 'Only a Super Admin can grant the Super Admin role.' using errcode = '42501';
    end if;
    if v_rank >= public.current_role_rank() then
      raise exception 'You cannot grant a role at or above your own level.' using errcode = '42501';
    end if;
  end if;

  insert into public.user_roles (user_id, role_key, granted_by)
  values (p_user, p_role, public.current_profile_id())
  on conflict (user_id, role_key) do nothing;

  perform public.log_audit('admin.role_granted', 'user', p_user::text,
    jsonb_build_object('role', p_role, 'username', v_username), true, null, 'admin');

  perform public.notify_user(p_user, 'moderation_notice',
    'Your Campus+ role changed',
    'You now have the ' || p_role || ' role on Campus+.',
    'profile', p_user::text, '/profile');

  return jsonb_build_object('ok', true, 'role', p_role);
end;
$$;

create or replace function public.revoke_role(p_user uuid, p_role text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_rank integer;
begin
  if not (public.has_permission('assign_roles') or public.is_trusted_writer()) then
    raise exception 'You do not have permission to change roles.' using errcode = '42501';
  end if;
  if p_role = 'student' then
    raise exception 'The student role is assigned automatically.' using errcode = '22023';
  end if;
  if p_user = public.current_profile_id() then
    raise exception 'You cannot remove your own role.' using errcode = '42501';
  end if;

  select r.rank into v_rank from public.roles r where r.key = p_role;
  if v_rank is null then
    raise exception 'That role does not exist.' using errcode = '22023';
  end if;
  if not public.is_trusted_writer() and v_rank >= public.current_role_rank() then
    raise exception 'You cannot revoke a role at or above your own level.' using errcode = '42501';
  end if;

  delete from public.user_roles where user_id = p_user and role_key = p_role;

  perform public.log_audit('admin.role_revoked', 'user', p_user::text,
    jsonb_build_object('role', p_role), true, null, 'admin');

  return jsonb_build_object('ok', true);
end;
$$;

-- ----------------------------------------------------------------------------
-- Account lifecycle
-- ----------------------------------------------------------------------------

create or replace function public.admin_set_account_status(
  p_user uuid,
  p_status public.account_status,
  p_reason text default null,
  p_duration_days integer default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_target_rank integer;
  v_until timestamptz;
  v_username text;
begin
  if p_user is null then
    raise exception 'Choose a student.' using errcode = '22023';
  end if;
  if p_user = v_actor then
    raise exception 'You cannot change your own account status here.' using errcode = '22023';
  end if;
  if not (public.is_trusted_writer() or public.is_active_profile(v_actor)) then
    raise exception 'Your account cannot perform moderation actions.' using errcode = '42501';
  end if;

  if not public.is_trusted_writer() then
    if p_status in ('suspended', 'banned') then
      if not public.has_permission('suspend_users') then
        raise exception 'You do not have permission to suspend accounts.' using errcode = '42501';
      end if;
    elsif not public.has_permission('manage_users') then
      raise exception 'You do not have permission to change account status.' using errcode = '42501';
    end if;

    v_target_rank := public.role_rank(p_user);
    if public.current_role_rank() <= v_target_rank then
      raise exception 'You cannot act on a student at or above your own level.' using errcode = '42501';
    end if;
  end if;

  if p_status = 'suspended' then
    v_until := now() + make_interval(days => greatest(coalesce(p_duration_days, 7), 1));
  end if;

  select p.username into v_username from public.profiles p where p.id = p_user;
  if v_username is null then
    raise exception 'That student could not be found.' using errcode = '22023';
  end if;

  update public.profile_private
     set account_status = p_status,
         status_reason = left(nullif(btrim(coalesce(p_reason, '')), ''), 500),
         suspended_until = v_until
   where profile_id = p_user;

  perform public.log_audit(
    case p_status
      when 'suspended' then 'moderation.user_suspended'
      when 'banned' then 'moderation.user_banned'
      when 'active' then 'moderation.user_reinstated'
      else 'admin.user_status_changed'
    end,
    'user', p_user::text,
    jsonb_build_object('status', p_status, 'duration_days', p_duration_days, 'username', v_username),
    true, p_reason, 'staff');

  if p_status in ('suspended', 'banned') then
    perform public.notify_user(p_user, 'moderation_notice',
      case when p_status = 'banned' then 'Your Campus+ account has been banned' else 'Your Campus+ account has been suspended' end,
      coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Contact the Campus+ moderators if you believe this is a mistake.'),
      'profile', p_user::text, '/account-status');
  end if;

  return jsonb_build_object('ok', true, 'status', p_status, 'until', v_until);
end;
$$;

comment on function public.admin_set_account_status is
  'Suspend, ban, reinstate or deactivate an account. Rank-checked, audited and notified.';

create or replace function public.deactivate_own_account(p_reason text default null)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  update public.profile_private
     set account_status = 'deactivated',
         status_reason = left(nullif(btrim(coalesce(p_reason, '')), ''), 500)
   where profile_id = v_me;

  perform public.log_audit('account.deactivated', 'user', v_me::text,
    jsonb_build_object('reason', p_reason), false, null, 'private');

  return jsonb_build_object('ok', true);
end;
$$;

create or replace function public.reactivate_own_account()
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  update public.profile_private
     set account_status = 'active', status_reason = null, suspended_until = null
   where profile_id = v_me and account_status in ('deactivated', 'active');

  perform public.log_audit('account.reactivated', 'user', v_me::text, '{}'::jsonb, false, null, 'private');
  return jsonb_build_object('ok', true);
end;
$$;

-- ----------------------------------------------------------------------------
-- Content moderation
-- ----------------------------------------------------------------------------

create or replace function public.content_moderation_permission(p_target_type text)
returns text
language sql
immutable
as $$
  select case p_target_type
    when 'post' then 'remove_posts'
    when 'comment' then 'remove_comments'
    when 'marketplace_listing' then 'moderate_marketplace'
    when 'gig' then 'moderate_marketplace'
    when 'community' then 'moderate_communities'
    when 'club' then 'moderate_communities'
    when 'deal' then 'manage_deals'
    when 'event' then 'manage_events'
    when 'notice' then 'manage_notices'
    when 'resource' then 'manage_official_content'
    when 'opportunity' then 'manage_official_content'
    when 'project' then 'moderate_all'
    when 'lost_found' then 'moderate_all'
    when 'housing_post' then 'moderate_all'
    when 'ride_post' then 'moderate_all'
    else null
  end;
$$;

create or replace function public.moderate_content(
  p_target_type text,
  p_target_id uuid,
  p_action text,
  p_reason text default null,
  p_report_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_permission text;
  v_new_status text;
  v_author uuid;
  v_label text;
begin
  v_permission := public.content_moderation_permission(p_target_type);
  if v_permission is null then
    raise exception 'That content type cannot be moderated.' using errcode = '22023';
  end if;

  if not public.is_trusted_writer() then
    if not public.is_active_profile(public.current_profile_id()) then
      raise exception 'Your account cannot moderate content.' using errcode = '42501';
    end if;
    if not (public.has_permission(v_permission) or public.has_permission('moderate_all')) then
      raise exception 'You do not have permission to moderate this content.' using errcode = '42501';
    end if;
  end if;

  v_new_status := case p_action
    when 'hide' then 'hidden'
    when 'remove' then 'removed'
    when 'restore' then 'published'
    when 'approve' then 'published'
    when 'reject' then 'removed'
    else null
  end;

  if p_target_type in ('post', 'comment', 'marketplace_listing', 'gig', 'community', 'club',
                       'project', 'lost_found', 'housing_post', 'ride_post')
     and v_new_status is null then
    raise exception 'Unsupported action for this content type.' using errcode = '22023';
  end if;
  if p_target_type = 'marketplace_listing' and p_action = 'approve' then
    v_new_status := 'active';
  end if;

  if p_target_type = 'post' then
    update public.posts
       set status = v_new_status::public.content_status, moderated_by = public.current_profile_id(),
           moderated_at = now(), moderation_reason = left(p_reason, 500)
     where id = p_target_id
     returning author_id into v_author;
  elsif p_target_type = 'comment' then
    update public.comments
       set status = v_new_status::public.content_status, moderated_by = public.current_profile_id(),
           moderated_at = now(), moderation_reason = left(p_reason, 500)
     where id = p_target_id
     returning author_id into v_author;
  elsif p_target_type = 'marketplace_listing' then
    update public.marketplace_listings
       set status = v_new_status::public.listing_status, moderated_by = public.current_profile_id(),
           moderated_at = now(), moderation_reason = left(p_reason, 500)
     where id = p_target_id
     returning seller_id into v_author;
  elsif p_target_type = 'gig' then
    update public.gigs
       set status = v_new_status::public.content_status, moderated_by = public.current_profile_id(),
           moderated_at = now(), moderation_reason = left(p_reason, 500)
     where id = p_target_id
     returning creator_id into v_author;
  elsif p_target_type in ('community', 'club') then
    update public.communities
       set status = v_new_status::public.content_status
     where id = p_target_id
     returning created_by into v_author;
  elsif p_target_type = 'project' then
    update public.projects
       set status = v_new_status::public.content_status, moderated_by = public.current_profile_id(),
           moderated_at = now(), moderation_reason = left(p_reason, 500)
     where id = p_target_id
     returning creator_id into v_author;
  elsif p_target_type = 'lost_found' then
    update public.lost_found set status = v_new_status::public.content_status
     where id = p_target_id returning creator_id into v_author;
  elsif p_target_type = 'housing_post' then
    update public.housing_posts set status = v_new_status::public.content_status
     where id = p_target_id returning creator_id into v_author;
  elsif p_target_type = 'ride_post' then
    update public.ride_posts set status = v_new_status::public.content_status
     where id = p_target_id returning creator_id into v_author;
  elsif p_target_type in ('notice', 'event', 'resource', 'opportunity', 'deal') then
    -- Official content: staff already own these rows through RLS-managed updates.
    update public.audit_logs set id = id where false;  -- no-op keeps the branch explicit
    v_author := null;
  end if;

  perform public.log_audit('moderation.content_' || p_action, p_target_type, p_target_id::text,
    jsonb_build_object('report_id', p_report_id, 'status', v_new_status), true, p_reason, 'staff');

  if v_author is not null and p_action in ('hide', 'remove', 'reject') then
    v_label := replace(p_target_type, '_', ' ');
    perform public.notify_user(v_author, 'moderation_notice',
      'Your ' || v_label || ' was ' || case when p_action = 'hide' then 'hidden' else 'removed' end,
      coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'Review the Campus+ rules and post again.'),
      p_target_type, p_target_id::text, null);
  end if;

  return jsonb_build_object('ok', true, 'status', v_new_status);
end;
$$;

comment on function public.moderate_content is
  'Single moderation action path: permission check → status change → moderation action → audit log → author notification.';

-- ----------------------------------------------------------------------------
-- Reports
-- ----------------------------------------------------------------------------

create or replace function public.resolve_report(
  p_report_id uuid,
  p_status public.report_status,
  p_resolution text default null,
  p_target_action text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_report public.reports;
  v_actor uuid := public.current_profile_id();
begin
  if not (public.has_permission('review_reports') or public.has_permission('moderate_all') or public.is_trusted_writer()) then
    raise exception 'You do not have permission to review reports.' using errcode = '42501';
  end if;

  select * into v_report from public.reports where id = p_report_id;
  if v_report.id is null then
    raise exception 'That report could not be found.' using errcode = '22023';
  end if;

  if p_target_action is not null and p_target_action not in ('none') then
    perform public.moderate_content(v_report.target_type::text, v_report.target_id, p_target_action,
                                    p_resolution, p_report_id);
  end if;

  update public.reports
     set status = p_status,
         resolution = left(nullif(btrim(coalesce(p_resolution, '')), ''), 1000),
         reviewed_by = case when p_status in ('resolved', 'dismissed') then v_actor else reviewed_by end,
         reviewed_at = case when p_status in ('resolved', 'dismissed') then now() else reviewed_at end
   where id = p_report_id;

  update public.random_reports
     set status = p_status,
         resolution = left(nullif(btrim(coalesce(p_resolution, '')), ''), 1000),
         reviewed_by = case when p_status in ('resolved', 'dismissed') then v_actor else reviewed_by end,
         reviewed_at = case when p_status in ('resolved', 'dismissed') then now() else reviewed_at end
   where session_id = v_report.random_session_id;

  -- Tell the reporter the outcome (spec §53: report result).
  if p_status in ('resolved', 'dismissed') then
    perform public.notify_user(v_report.reporter_id, 'report_result',
      'Your report was ' || case when p_status = 'dismissed' then 'reviewed and dismissed' else 'actioned' end,
      coalesce(nullif(btrim(coalesce(p_resolution, '')), ''), 'Thanks for helping keep Campus+ usable.'),
      v_report.target_type::text, v_report.target_id::text, null);
  end if;

  return jsonb_build_object('ok', true, 'status', p_status);
end;
$$;

create or replace function public.assign_report(
  p_report uuid,
  p_to uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_target uuid := coalesce(p_to, v_me);
begin
  if not (public.has_permission('review_reports') or public.has_permission('moderate_all')) then
    raise exception 'You do not have permission to review reports.' using errcode = '42501';
  end if;
  if not public.is_active_profile(v_target) then
    raise exception 'That moderator cannot take reports right now.' using errcode = '22023';
  end if;

  update public.reports
     set assigned_to = v_target,
         status = case when status = 'pending' then 'reviewing'::public.report_status else status end
   where id = p_report and status in ('pending', 'reviewing');

  if not found then
    raise exception 'That report is not open for triage.' using errcode = '22023';
  end if;

  perform public.log_audit('moderation.report_assigned', 'report', p_report::text,
    jsonb_build_object('assigned_to', v_target), true, null, 'staff');

  return jsonb_build_object('ok', true, 'assigned_to', v_target);
end;
$$;

comment on function public.assign_report is
  'Claims an open report for a moderator. The only path that changes reports.assigned_to or moves pending → reviewing.';

-- ----------------------------------------------------------------------------
-- Self-service content deletion (soft delete keeps moderation evidence)
-- ----------------------------------------------------------------------------

create or replace function public.delete_own_content(p_target_type text, p_target_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_owner uuid;
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if p_target_type = 'post' then
    update public.posts set status = 'deleted', deleted_at = now()
     where id = p_target_id and author_id = v_me returning author_id into v_owner;
  elsif p_target_type = 'comment' then
    update public.comments set status = 'deleted', deleted_at = now()
     where id = p_target_id and author_id = v_me returning author_id into v_owner;
  elsif p_target_type = 'marketplace_listing' then
    update public.marketplace_listings set status = 'removed'
     where id = p_target_id and seller_id = v_me returning seller_id into v_owner;
  elsif p_target_type = 'gig' then
    update public.gigs set status = 'deleted'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'housing_post' then
    update public.housing_posts set status = 'deleted'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'ride_post' then
    update public.ride_posts set status = 'deleted'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'project' then
    update public.projects set status = 'deleted'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'team_post' then
    update public.team_posts set status = 'deleted'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'lost_found' then
    update public.lost_found set status = 'deleted'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'message' then
    update public.messages set deleted_at = now(), deleted_by = v_me
     where id = p_target_id and sender_id = v_me returning sender_id into v_owner;
  else
    raise exception 'That content type cannot be deleted here.' using errcode = '22023';
  end if;

  if v_owner is null then
    raise exception 'That content could not be found, or is not yours.' using errcode = '42501';
  end if;

  perform public.log_audit('content.self_deleted', p_target_type, p_target_id::text, '{}'::jsonb, false, null, 'private');
  return jsonb_build_object('ok', true);
end;
$$;

create or replace function public.restore_own_content(p_target_type text, p_target_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_owner uuid;
begin
  if p_target_type = 'post' then
    update public.posts set status = 'published', deleted_at = null
     where id = p_target_id and author_id = v_me and status = 'deleted' returning author_id into v_owner;
  elsif p_target_type = 'comment' then
    update public.comments set status = 'published', deleted_at = null
     where id = p_target_id and author_id = v_me and status = 'deleted' returning author_id into v_owner;
  elsif p_target_type = 'marketplace_listing' then
    update public.marketplace_listings set status = 'active'
     where id = p_target_id and seller_id = v_me and status = 'removed' returning seller_id into v_owner;
  elsif p_target_type = 'housing_post' then
    update public.housing_posts set status = 'published'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'ride_post' then
    update public.ride_posts set status = 'published'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'project' then
    update public.projects set status = 'published'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'gig' then
    update public.gigs set status = 'published'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  elsif p_target_type = 'lost_found' then
    update public.lost_found set status = 'published'
     where id = p_target_id and creator_id = v_me returning creator_id into v_owner;
  else
    raise exception 'That content type cannot be restored here.' using errcode = '22023';
  end if;

  if v_owner is null then
    raise exception 'That content could not be found, or is not yours.' using errcode = '42501';
  end if;
  return jsonb_build_object('ok', true);
end;
$$;

-- ----------------------------------------------------------------------------
-- Platform configuration
-- ----------------------------------------------------------------------------
-- Clients cannot UPDATE `platform_settings` (015 revokes the column privilege);
-- this function is the only in-app path. It validates the value against the
-- key's documented shape, so a mistyped setting cannot take the platform down,
-- and writes the change to the audit trail.
create or replace function public.admin_set_platform_setting(p_key text, p_value jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_old jsonb;
  v_text text;
  v_number numeric;
  v_item text;
begin
  if not public.has_permission('manage_platform_settings') then
    raise exception 'You do not have permission to change platform settings.' using errcode = '42501';
  end if;
  if p_value is null then
    raise exception 'A platform setting needs a value.' using errcode = '22023';
  end if;

  select value into v_old from public.platform_settings where key = p_key;
  if not found then
    raise exception 'That platform setting does not exist.' using errcode = '22023';
  end if;

  if p_key = 'allowed_email_domains' then
    if jsonb_typeof(p_value) <> 'array' or jsonb_array_length(p_value) = 0 then
      raise exception 'allowed_email_domains must be a non-empty list of domains.' using errcode = '22023';
    end if;
    -- Every entry must look like a domain (lowercase, at least one dot, no
    -- wildcards) so the sign-in gate can never be opened accidentally.
    for v_item in select jsonb_array_elements_text(p_value) loop
      if v_item <> lower(v_item)
         or v_item !~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$' then
        raise exception 'Invalid email domain: %', v_item using errcode = '22023';
      end if;
    end loop;

  elsif p_key = 'marketplace_approval_mode' then
    if jsonb_typeof(p_value) <> 'string'
       or (p_value #>> '{}') not in ('post_moderation', 'pre_moderation') then
      raise exception 'marketplace_approval_mode must be post_moderation or pre_moderation.' using errcode = '22023';
    end if;

  elsif p_key in ('username_change_cooldown_days', 'random_session_max_minutes',
                  'random_rematch_cooldown_seconds', 'random_retention_days') then
    if jsonb_typeof(p_value) <> 'number' then
      raise exception '% must be a number.', p_key using errcode = '22023';
    end if;
    v_number := (p_value #>> '{}')::numeric;
    if v_number <> trunc(v_number) or v_number < 0 then
      raise exception '% must be a whole number of zero or more.', p_key using errcode = '22023';
    end if;
    if p_key = 'username_change_cooldown_days' and v_number > 365 then
      raise exception 'The username change cooldown cannot exceed a year.' using errcode = '22023';
    elsif p_key = 'random_session_max_minutes' and v_number < 5 then
      raise exception 'A Random session must last at least five minutes.' using errcode = '22023';
    elsif p_key = 'random_retention_days' and v_number < 1 then
      raise exception 'Random sessions must be retained for at least one day.' using errcode = '22023';
    elsif p_key = 'random_rematch_cooldown_seconds' and v_number > 3600 then
      raise exception 'The rematch cooldown cannot exceed an hour.' using errcode = '22023';
    end if;

  elsif p_key in ('community_creation_open', 'student_opportunity_submission',
                  'feed_marketplace_highlights', 'show_event_attendees') then
    if jsonb_typeof(p_value) <> 'boolean' then
      raise exception '% must be true or false.', p_key using errcode = '22023';
    end if;

  elsif p_key = 'moderate_community_submissions' then
    if jsonb_typeof(p_value) <> 'object'
       or jsonb_typeof(p_value -> 'resource') <> 'boolean'
       or jsonb_typeof(p_value -> 'opportunity') <> 'boolean' then
      raise exception 'moderate_community_submissions needs resource and opportunity booleans.' using errcode = '22023';
    end if;

  elsif p_key = 'feed_ranking' then
    if p_value <> '"deterministic_v1"'::jsonb then
      raise exception 'Campus+ only supports deterministic feed ranking.' using errcode = '22023';
    end if;

  else
    -- Branding text values: short strings only.
    if jsonb_typeof(p_value) <> 'string' then
      raise exception '% must be text.', p_key using errcode = '22023';
    end if;
    v_text := p_value #>> '{}';
    if length(v_text) > 200 then
      raise exception '% cannot be longer than 200 characters.', p_key using errcode = '22023';
    end if;
    if p_key in ('platform_name', 'institution_name') and btrim(v_text) = '' then
      raise exception '% cannot be empty.', p_key using errcode = '22023';
    end if;
  end if;

  update public.platform_settings
     set value = p_value, updated_by = public.current_profile_id()
   where key = p_key;

  perform public.log_audit('admin.setting_changed', 'platform_settings', p_key,
    jsonb_build_object('old', v_old, 'new', p_value), true, null, 'admin');

  return jsonb_build_object('ok', true, 'key', p_key, 'value', p_value);
end;
$$;

comment on function public.admin_set_platform_setting(text, jsonb) is
  'Admin/Super Admin entry point for platform configuration. Validates the value per key and writes an audit entry.';

-- ==========================================================================
-- FILE 17/25  20261005000017_017_marketplace_hardening.sql
-- ==========================================================================

-- Campus+ migration 017 — marketplace hardening
-- Supabase CLI filename: 20261005000017_017_marketplace_hardening.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 017 — marketplace: interest → contact → completion
-- =============================================================================
-- One explicit funnel, all of it server-side:
--
--   browse (no contact details) → "I'm interested"  → contact details + DM
--                               → seller marks the item sold → ratings allowed
--
-- Blocking is respected at every step, and the seller is notified once.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- Express interest: records the interaction, notifies the seller, and only then
-- hands back the contact note.
-- ----------------------------------------------------------------------------

create or replace function public.record_listing_interest(p_listing uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_listing public.marketplace_listings;
  v_interaction uuid;
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if not public.is_active_user() then
    raise exception 'Your account cannot use the marketplace.' using errcode = '42501';
  end if;
  if not public.feature_enabled('marketplace') then
    raise exception 'The marketplace is disabled.' using errcode = '42501';
  end if;

  select * into v_listing from public.marketplace_listings where id = p_listing;
  if v_listing.id is null or v_listing.status not in ('active', 'reserved') then
    raise exception 'That listing is no longer available.' using errcode = '22023';
  end if;
  if v_listing.seller_id = v_me then
    raise exception 'That is your own listing.' using errcode = '22023';
  end if;
  if public.is_blocked(v_me, v_listing.seller_id) or public.is_blocked(v_listing.seller_id, v_me) then
    raise exception 'You cannot contact this seller.' using errcode = '42501';
  end if;

  -- One 'contact' row per student per listing. A repeated tap returns the
  -- contact note again but must not notify the seller twice.
  insert into public.marketplace_interactions (listing_id, user_id, kind)
  values (p_listing, v_me, 'contact')
  on conflict do nothing
  returning id into v_interaction;

  if v_interaction is not null then
    perform public.notify_user(
      v_listing.seller_id, 'marketplace_status',
      'Someone is interested in your listing',
      'A student asked about "' || left(v_listing.title, 80) || '".',
      'marketplace_listing', p_listing::text, '/market/listing/' || p_listing::text
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'seller_id', v_listing.seller_id,
    'contact_note', v_listing.contact_note
  );
end;
$$;

comment on function public.record_listing_interest(uuid) is
  'The only path that reveals a listing''s contact details. Records the interaction and notifies the seller.';

-- ----------------------------------------------------------------------------
-- The seller (and moderators) keep access to the contact note they own.
-- ----------------------------------------------------------------------------
-- Clients lost SELECT on `contact_note` in migration 015, so the seller's edit
-- form reads it through here instead of the base table.
create or replace function public.get_listing_contact_note(p_listing uuid)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_note text;
  v_seller uuid;
begin
  select l.contact_note, l.seller_id into v_note, v_seller
  from public.marketplace_listings l
  where l.id = p_listing;
  if v_seller is null then
    raise exception 'That listing could not be found.' using errcode = '22023';
  end if;
  if not (v_seller = public.current_profile_id()
          or public.has_permission('moderate_marketplace')
          or public.is_trusted_writer()) then
    raise exception 'Contact details are released only through the interest flow.' using errcode = '42501';
  end if;
  return v_note;
end;
$$;

comment on function public.get_listing_contact_note(uuid) is
  'Owner/moderator read of a listing contact note; buyers get it from record_listing_interest().';

-- ----------------------------------------------------------------------------
-- The seller closes the loop. `sold_to` is what unlocks buyer ratings, so it is
-- set here rather than by the client.
-- ----------------------------------------------------------------------------

create or replace function public.mark_listing_completed(p_listing uuid, p_buyer uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_buyer uuid := p_buyer;
  v_seller uuid;
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select seller_id into v_seller from public.marketplace_listings where id = p_listing;
  if v_seller is null then
    raise exception 'That listing could not be found.' using errcode = '22023';
  end if;
  if v_seller <> v_me and not public.has_permission('moderate_marketplace') then
    raise exception 'Only the seller can mark a listing as sold.' using errcode = '42501';
  end if;

  if v_buyer is null then
    -- Default to the student who most recently showed interest.
    select i.user_id into v_buyer
    from public.marketplace_interactions i
    where i.listing_id = p_listing and i.kind = 'contact'
    order by i.created_at desc
    limit 1;
  end if;
  if v_buyer is null then
    raise exception 'Choose the student the item was handed to.' using errcode = '22023';
  end if;
  if v_buyer = v_seller then
    raise exception 'The buyer cannot be the seller.' using errcode = '22023';
  end if;

  update public.marketplace_listings
     set status = 'sold', sold_to = v_buyer, sold_at = now()
   where id = p_listing;

  perform public.notify_user(
    v_buyer, 'marketplace_rating',
    'You can now rate this trade',
    'The seller marked "' || left(coalesce((select title from public.marketplace_listings where id = p_listing), 'a listing'), 80)
      || '" as completed. Leave a rating to help other students.',
    'marketplace_listing', p_listing::text, '/market/listing/' || p_listing::text
  );

  perform public.log_audit('marketplace.completed', 'marketplace_listing', p_listing::text,
    jsonb_build_object('buyer_id', v_buyer), false, null, 'private');

  return jsonb_build_object('ok', true, 'buyer_id', v_buyer);
end;
$$;

-- ----------------------------------------------------------------------------
-- The seller's own view of who is interested (RLS already restricts this to the
-- seller and staff; this view adds the student's public identity in one read).
-- ----------------------------------------------------------------------------

create or replace view public.listing_interests_view
with (security_invoker = true) as
select
  i.id,
  i.listing_id,
  i.user_id,
  pr.username,
  pr.display_name,
  i.created_at
from public.marketplace_interactions i
join public.public_profiles pr on pr.id = i.user_id
where i.kind = 'contact';

comment on view public.listing_interests_view is
  'Students who expressed interest in a listing. Visible only to the seller and staff (security_invoker + base-table RLS).';

-- ==========================================================================
-- FILE 18/25  20261005000018_018_function_grants.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 018 — final function grants
-- =============================================================================
-- This file runs last so that every function defined by earlier migrations is
-- reachable by `authenticated` and unreachable by `anon`.
--
-- Two layers matter:
--
--   1. PostgreSQL grants EXECUTE on every new function to PUBLIC by default, so
--      `anon` inherits the whole RPC surface unless it is revoked explicitly.
--      Campus+ has no anonymous features, so PUBLIC loses EXECUTE entirely and
--      the default is changed for functions created by future migrations too.
--
--   2. Every function that changes state validates the caller itself
--      (has_permission, ownership, rank, or is_trusted_writer). Granting
--      EXECUTE is therefore not a privilege escalation: it only makes the
--      audited entry point callable.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. Remove the PostgreSQL default (EXECUTE to PUBLIC) from existing functions
-- ----------------------------------------------------------------------------

do $$
declare
  v_fn record;
begin
  for v_fn in
    select p.oid::regprocedure as signature
    from pg_proc p
    join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public'
      and p.prokind = 'f'
  loop
    -- Explicit, not inherited: authenticated and service_role only.
    execute format('revoke all on function %s from public', v_fn.signature);
    execute format('revoke all on function %s from anon', v_fn.signature);
    execute format('grant execute on function %s to authenticated', v_fn.signature);
    execute format('grant execute on function %s to service_role', v_fn.signature);
  end loop;
end;
$$;

-- Same rule for anything a future migration adds. `alter default privileges`
-- applies to objects created by the role running it (postgres, the migration
-- owner), which is exactly the CLI's role.
alter default privileges in schema public revoke execute on functions from public;
alter default privileges in schema public grant execute on functions to service_role;
alter default privileges in schema public grant execute on functions to authenticated;

-- ----------------------------------------------------------------------------
-- 2. Tables, sequences and views
-- ----------------------------------------------------------------------------

-- NOTE: this loop only removes access from anon/PUBLIC. It deliberately does not
-- touch `authenticated`: the two-dimensional grant matrix (which *rows* via RLS,
-- which *columns* via migration 015) is authoritative there, and a blanket
-- `grant update` here would silently undo 015's column privileges.
do $$
declare
  v_rel record;
begin
  for v_rel in
    select c.oid::regclass as name, c.relkind
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind in ('r', 'p', 'v', 'm', 'S')
  loop
    execute format('revoke all on %s from anon', v_rel.name);
    execute format('revoke all on %s from public', v_rel.name);
    execute format('grant all on %s to service_role', v_rel.name);
    if v_rel.relkind = 'S' then
      execute format('grant usage, select on %s to authenticated', v_rel.name);
    elsif v_rel.relkind in ('v', 'm') then
      -- RLS of the base tables still applies (security_invoker) unless a definer
      -- view is intentionally whitelisted (see migration 010).
      execute format('grant select on %s to authenticated', v_rel.name);
    end if;
  end loop;
end;
$$;

-- Defaults for objects future migrations add: no anonymous access, no client
-- UPDATE unless a column grant says so. `authenticated` keeps SELECT/INSERT/DELETE
-- so a new table is usable immediately, with RLS as the row boundary.
alter default privileges in schema public revoke all on tables from public;
alter default privileges in schema public revoke all on tables from anon;
alter default privileges in schema public grant all on tables to service_role;
alter default privileges in schema public grant select, insert, delete on tables to authenticated;
alter default privileges in schema public grant usage, select on sequences to authenticated, service_role;

-- Schema usage: the API roles need to see the schema, but nothing else.
revoke all on schema public from anon, public;
grant usage on schema public to anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 3. Explicitly public, pre-authentication helpers
-- ----------------------------------------------------------------------------
-- The sign-in screen checks a domain *before* a session exists. These two
-- functions are pure, read-only and harmless, so anon may call them:

grant execute on function public.allowed_email_domain(text) to anon;
grant execute on function public.is_reserved_username(text) to anon;
grant execute on function public.feature_enabled(text) to anon;
grant execute on function public.setting(text, jsonb) to anon;

-- Views that are intentionally readable by any signed-in student.
grant select on public.public_profiles to authenticated;
grant select on public.random_session_view to authenticated;
grant select on public.random_messages_view to authenticated;

-- ==========================================================================
-- FILE 19/25  20261005000019_019_staff_visibility.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 019 — staff visibility on the public projection
-- =============================================================================
-- Spec §13 requires a subtle staff marker next to a moderator's or admin's
-- username everywhere their content appears. `user_roles` is (correctly) not
-- readable for other students, so the application had no way to render that
-- marker: the badge was impossible without weakening a policy.
--
-- The fix is a single SECURITY DEFINER predicate plus one extra column on the
-- existing public projection. It answers exactly one boolean question — "does
-- this profile hold a moderator role or above?" — and reveals nothing else: not
-- which role, not when it was granted, not who granted it. Students have no row to show and
-- therefore see no marker, as the spec requires.
-- =============================================================================

create or replace function public.is_staff_profile(p_profile uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  -- `rank` is the role's level: student < moderator < admin < super admin.
  select exists (
    select 1
    from public.user_roles ur
    join public.roles r on r.key = ur.role_key
    where ur.user_id = p_profile
      and r.rank >= 2
  );
$$;

comment on function public.is_staff_profile(uuid) is
  'TRUE when a profile holds a staff role (moderator/admin/super admin). Used only to render the staff marker (spec §13); it exposes no role details.';

-- Same explicit grant contract as migration 018: PostgreSQL gives every new
-- function EXECUTE to PUBLIC by default, and Campus+ has no anonymous surface.
revoke all on function public.is_staff_profile(uuid) from public, anon;
grant execute on function public.is_staff_profile(uuid) to authenticated, service_role;

-- The projection keeps its block-aware filter and security_invoker behaviour.
-- Recreating a view drops its grants, so the SELECT grant is restored below.
create or replace view public.public_profiles
with (security_invoker = true)
as
select
  p.id,
  p.username,
  p.display_name,
  p.bio,
  case when p.show_branch_year then p.branch else null end as branch,
  case when p.show_branch_year then p.year else null end as year,
  p.reputation_score,
  p.reputation_count,
  p.marketplace_completed_count,
  public.is_active_profile(p.id) as is_active,
  p.created_at,
  -- Appended last on purpose: `create or replace view` cannot reorder columns,
  -- and keeping the existing order means existing readers are unaffected.
  public.is_staff_profile(p.id) as is_staff
from public.profiles p
where p.username is not null
  -- Discovery respects blocks in both directions (spec §14, §60). The raw
  -- `profiles` table stays available so blocking, unblocking and moderation can
  -- still resolve the person involved.
  and not public.is_blocked_with_current(p.id);

comment on view public.public_profiles is
  'Public projection of profiles. Institutional email, auth ids and moderation state are structurally absent. `is_staff` drives the staff marker only.';

grant select on public.public_profiles to authenticated;

-- ==========================================================================
-- FILE 20/25  20261005000020_020_chat_inbox.sql
-- ==========================================================================

-- =============================================================================
-- Campus+ migration 020 — conversation inbox read model
-- =============================================================================
-- The Messages inbox needs, per visible conversation: the newest message (for
-- the preview line) and how many messages are unread since the last read mark,
-- saturated at the same 30-message window the UI has always used.
--
-- Before this function the page fetched the newest 30 messages of *every*
-- conversation (bodies included) just to render one preview line each — about
-- 69 kB per inbox open on the reference data set, and worse as threads grow.
-- The window is a read model, not a product change: an unread badge still
-- saturates at 30, and the preview is still the newest message.
--
-- Security: `security invoker`, so every row is still filtered by the RLS
-- policies on `conversations`, `conversation_members` and `messages` for the
-- calling student — this adds no visibility the student did not already have.
-- =============================================================================

create or replace function public.conversation_inbox(p_limit integer default 30)
returns table (
  id                      uuid,
  kind                    public.conversation_kind,
  title                   text,
  community_id            uuid,
  status                  public.content_status,
  last_message_at         timestamptz,
  created_at              timestamptz,
  is_muted                boolean,
  last_read_at            timestamptz,
  unread                  integer,
  last_message_id         uuid,
  last_message_sender_id  uuid,
  last_message_body       text,
  last_message_gif        jsonb,
  last_message_created_at timestamptz
)
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
  with mine as (
    select m.conversation_id, m.is_muted, m.last_read_at
    from public.conversation_members m
    where m.user_id = public.current_profile_id()
      and m.status = 'active'
  )
  select
    c.id,
    c.kind,
    c.title,
    c.community_id,
    c.status,
    c.last_message_at,
    c.created_at,
    mine.is_muted,
    mine.last_read_at,
    (
      select count(*)::integer
      from (
        select msg.sender_id, msg.created_at
        from public.messages msg
        where msg.conversation_id = c.id
        order by msg.created_at desc
        limit 30
      ) window_rows
      where window_rows.sender_id <> public.current_profile_id()
        and (mine.last_read_at is null or window_rows.created_at > mine.last_read_at)
    ) as unread,
    latest.id,
    latest.sender_id,
    latest.body,
    latest.gif,
    latest.created_at
  from public.conversations c
  join mine on mine.conversation_id = c.id
  left join lateral (
    select msg.id, msg.sender_id, msg.body, msg.gif, msg.created_at
    from public.messages msg
    where msg.conversation_id = c.id
    order by msg.created_at desc
    limit 1
  ) latest on true
  order by c.last_message_at desc
  limit coalesce(p_limit, 30);
$$;

comment on function public.conversation_inbox(integer) is
  'Inbox read model (RLS-scoped): newest message plus the unread count within the newest 30 messages per visible conversation.';

-- ==========================================================================
-- FILE 21/25  20261005000021_021_marketplace_and_security_fixes.sql
-- ==========================================================================

-- Campus+ migration 021 — marketplace lifecycle fixes + security hardening
-- Supabase CLI filename: 20261005000021_021_marketplace_and_security_fixes.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- This migration fixes two confirmed, root-caused marketplace bugs and closes
-- three small, real gaps the security review found. Nothing here touches RLS
-- in a way that widens access, converts a function away from the security
-- posture it needs to work, or uses the secret key to bypass a policy.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- 1. "Remove listing" silently did nothing, and a resolved listing never
--    actually recorded its buyer.
-- ----------------------------------------------------------------------------
-- guard_listing_update() (migration 008) lets a seller move their own listing
-- between 'active', 'reserved', 'sold' and 'expired' only — any other value is
-- silently reverted to the old status (`new.status := old.status;`), with no
-- error raised. 'removed' was missing from that list, so the "Remove listing"
-- action in the UI ran its UPDATE, got a 200, and the listing stayed exactly
-- as visible as before. This adds 'removed' to the seller-controlled set.
--
-- Separately, this trigger unconditionally reverts `sold_to`/`sold_at` back to
-- their old values for any caller that is not `is_trusted_writer()` or a
-- marketplace moderator. mark_listing_completed() is SECURITY DEFINER so it
-- can legitimately set those two columns on the seller's behalf, but
-- SECURITY DEFINER only changes which role's *table privileges* apply — the
-- session's JWT claims (which is_trusted_writer() reads) are unchanged, so
-- from this trigger's point of view an ordinary seller's resolve looked
-- exactly like a student trying to edit sold_to directly, and it was silently
-- reverted. The result: calling mark_listing_completed() as a regular student
-- always left `sold_to`/`sold_at` untouched even when a buyer was found,
-- regardless of the two bugs fixed below. This now also recognises
-- `in_system_context()` (migration 002's existing marker for "a Campus+
-- definer function is doing privileged work on the user's behalf", already
-- used by prevent_privilege_escalation()) and mark_listing_completed() sets
-- that marker before writing.
-- ----------------------------------------------------------------------------

create or replace function public.guard_listing_update()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_trusted_writer() then
    new.view_count := (
      select count(*) from public.marketplace_interactions i
      where i.listing_id = old.id and i.kind = 'view'
    );
    new.contact_count := (
      select count(*) from public.marketplace_interactions i
      where i.listing_id = old.id and i.kind = 'contact'
    );
  end if;

  if public.is_trusted_writer() or public.in_system_context()
     or public.has_permission('moderate_marketplace') or public.has_permission('moderate_all') then
    return new;
  end if;
  new.seller_id         := old.seller_id;
  new.category_id       := old.category_id;
  new.is_official       := old.is_official;
  new.moderated_by      := old.moderated_by;
  new.moderated_at      := old.moderated_at;
  new.moderation_reason := old.moderation_reason;
  new.sold_at           := old.sold_at;
  new.sold_to           := old.sold_to;
  -- A seller may only move a listing between the student-controlled states.
  -- 'removed' is the self-service "take this down" state (delete_own_content /
  -- restore_own_content toggle it); a hard delete is a separate RLS-governed
  -- DELETE, not a status transition.
  if new.status is distinct from old.status
     and new.status not in ('active', 'reserved', 'sold', 'expired', 'removed') then
    new.status := old.status;
  end if;
  return new;
end;
$$;

-- ----------------------------------------------------------------------------
-- 2. Generic "Something went wrong" on resolving a listing with no recorded
--    interest.
-- ----------------------------------------------------------------------------
-- mark_listing_completed() raised when it could not infer a buyer (nobody had
-- tapped "I'm interested" first) and the UI's "Mark as sold" button never
-- collects one, so the seller could never resolve such a listing. sold_to is
-- nullable (migration 008: `references profiles(id) on delete set null`) and
-- on_listing_completed() (migration 008) only counts completions — it does not
-- require a buyer — so completing with sold_to = null is safe. The matching
-- fromPostgresError() fix lives in lib/errors.js: it previously had no mapping
-- for the 22023 errcode these business-rule messages use, so this and ~50
-- other deliberately-written, user-safe messages across the app were being
-- swallowed into a generic "internal error" string.
-- ----------------------------------------------------------------------------

create or replace function public.mark_listing_completed(p_listing uuid, p_buyer uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_me uuid := public.current_profile_id();
  v_buyer uuid := p_buyer;
  v_seller uuid;
begin
  if v_me is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  select seller_id into v_seller from public.marketplace_listings where id = p_listing;
  if v_seller is null then
    raise exception 'That listing could not be found.' using errcode = '22023';
  end if;
  if v_seller <> v_me and not public.has_permission('moderate_marketplace') then
    raise exception 'Only the seller can mark a listing as sold.' using errcode = '42501';
  end if;

  if v_buyer is null then
    -- Default to the student who most recently showed interest, if any.
    select i.user_id into v_buyer
    from public.marketplace_interactions i
    where i.listing_id = p_listing and i.kind = 'contact'
    order by i.created_at desc
    limit 1;
  end if;
  -- No interest was ever recorded (e.g. handed off outside the app): complete
  -- the listing without a buyer rather than blocking the seller from ever
  -- resolving it. A buyer is still never allowed to be the seller.
  if v_buyer is not null and v_buyer = v_seller then
    raise exception 'The buyer cannot be the seller.' using errcode = '22023';
  end if;

  -- Mark this as privileged, definer-driven work so guard_listing_update()
  -- lets sold_to/sold_at through for an ordinary seller (see the comment on
  -- guard_listing_update() above). Transaction-local: cleared automatically
  -- once this call's transaction ends.
  perform set_config('campus.system_context', 'on', true);

  update public.marketplace_listings
     set status = 'sold', sold_to = v_buyer, sold_at = now()
   where id = p_listing;

  if v_buyer is not null then
    perform public.notify_user(
      v_buyer, 'marketplace_rating',
      'You can now rate this trade',
      'The seller marked "' || left(coalesce((select title from public.marketplace_listings where id = p_listing), 'a listing'), 80)
        || '" as completed. Leave a rating to help other students.',
      'marketplace_listing', p_listing::text, '/market/listing/' || p_listing::text
    );
  end if;

  perform public.log_audit('marketplace.completed', 'marketplace_listing', p_listing::text,
    jsonb_build_object('buyer_id', v_buyer), false, null, 'private');

  return jsonb_build_object('ok', true, 'buyer_id', v_buyer);
end;
$$;

-- ----------------------------------------------------------------------------
-- 2b. mark_listing_completed() could never finish for an ordinary student.
-- ----------------------------------------------------------------------------
-- Independently of the missing-buyer bug above, log_audit() (migration 006)
-- only allows a non-staff caller to write 'account.%', 'user.%' or
-- 'content.self_%' actions — anything else raises 42501 "You do not have
-- permission to write audit entries." mark_listing_completed() logs
-- 'marketplace.completed', which matches none of those, so the perform
-- public.log_audit(...) call at the end of a successful resolve would ALWAYS
-- fail with that 42501 for a regular student seller (it never surfaced before
-- because every student request hit the missing-buyer 22023 first — a
-- moderator-driven resolve worked, since v_is_staff short-circuits the check,
-- which is why this stayed hidden). 'marketplace.completed' is a self-service
-- action on the caller's own listing, the same category as content.self_*, so
-- it is added to the allowed set rather than loosening the check generally.
-- ----------------------------------------------------------------------------

create or replace function public.log_audit(
  p_action text,
  p_target_type text default null,
  p_target_id text default null,
  p_metadata jsonb default null,
  p_also_moderation boolean default false,
  p_reason text default null,
  p_visibility public.moderation_visibility default 'staff'
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := public.current_profile_id();
  v_id uuid;
  v_is_staff boolean;
begin
  if v_actor is null and not public.is_trusted_writer() then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  v_is_staff := public.is_staff() or public.is_trusted_writer();

  -- Non-staff may only record their own account-lifecycle events and a small,
  -- explicit allow-list of other self-service actions, never moderation or
  -- administration entries.
  if not v_is_staff
     and p_action not like 'account.%'
     and p_action not like 'user.%'
     and p_action not like 'content.self_%'
     and p_action <> 'marketplace.completed' then
    raise exception 'You do not have permission to write audit entries.' using errcode = '42501';
  end if;

  insert into public.audit_logs (actor_user_id, action, target_type, target_id, metadata, visibility)
  values (
    v_actor,
    left(p_action, 80),
    left(p_target_type, 60),
    case when p_target_id ~ '^[0-9a-f-]{36}$' then p_target_id::uuid else null end,
    coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object(
      'reason', p_reason,
      'actor_username', (select username from public.profiles where id = v_actor)
    ),
    case when v_is_staff then p_visibility else 'private'::public.moderation_visibility end
  )
  returning id into v_id;

  if p_also_moderation and v_is_staff then
    insert into public.moderation_actions (
      moderator_id, report_id, action, target_type, target_id, note
    ) values (
      v_actor,
      nullif(p_metadata->>'report_id', '')::uuid,
      left(p_action, 60),
      left(p_target_type, 60),
      case when p_target_id ~ '^[0-9a-f-]{36}$' then p_target_id::uuid else null end,
      left(p_reason, 1000)
    );
  end if;

  return v_id;
end;
$$;

comment on function public.log_audit is
  'Append-only audit writer. Students are limited to their own account.* / user.* / content.self_* events plus the marketplace.completed self-service action; moderation entries require staff.';

-- ----------------------------------------------------------------------------
-- 3. conversation_inbox() was callable by anon.
-- ----------------------------------------------------------------------------
-- Migration 020 created this function after migration 018's blanket
-- revoke/grant loop and relied on `alter default privileges` to keep new
-- functions off PUBLIC. That did not take effect for this function, so it
-- kept PostgreSQL's built-in "EXECUTE to PUBLIC" default and `anon` could call
-- it. The function is `security invoker` and every row is still filtered by
-- RLS (an anon caller has no profile, so current_profile_id() is null and the
-- query returns nothing) — there is no data exposure — but an unauthenticated
-- caller should not be able to reach an application RPC at all. Fixed
-- explicitly here rather than re-relying on the default.
-- ----------------------------------------------------------------------------

revoke all on function public.conversation_inbox(integer) from public, anon;
grant execute on function public.conversation_inbox(integer) to authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 4. messages_update_staff allowed `with check (true)`.
-- ----------------------------------------------------------------------------
-- Column privileges already confine every authenticated UPDATE on `messages`
-- to the `body`/`gif` columns (migration 015), so this was never a path to
-- changing `sender_id`, `deleted_at`, etc. But `with check (true)` means a
-- moderator's update is accepted no matter what the row looks like afterwards,
-- so the same re-check used for `using` now also runs for `with check`: the
-- message must still belong to a conversation/message under an active
-- pending/reviewing report after the edit, matching the condition that let
-- the moderator reach the row in the first place.
-- ----------------------------------------------------------------------------

drop policy if exists messages_update_staff on public.messages;
create policy messages_update_staff on public.messages
  for update to authenticated
  using ((public.has_permission('review_reports') or public.has_permission('moderate_all'))
         and exists (select 1 from public.reports r
                     where r.status in ('pending', 'reviewing')
                       and ((r.target_type = 'message' and r.target_id = messages.id)
                            or (r.target_type = 'conversation' and r.target_id = messages.conversation_id))))
  with check ((public.has_permission('review_reports') or public.has_permission('moderate_all'))
         and exists (select 1 from public.reports r
                     where r.status in ('pending', 'reviewing')
                       and ((r.target_type = 'message' and r.target_id = messages.id)
                            or (r.target_type = 'conversation' and r.target_id = messages.conversation_id))));

-- ----------------------------------------------------------------------------
-- 5. Mutable search_path on a handful of helper functions this repo owns.
-- ----------------------------------------------------------------------------
-- Every SECURITY DEFINER function already pins search_path. These few small
-- SECURITY INVOKER helpers predate that convention; pinning them is a
-- metadata-only change (no behavioural difference — none of them reference an
-- unqualified relation) that silences the Advisor's "Function Search Path
-- Mutable" lint for the functions this project actually authored. The
-- remaining functions the lint can flag (pgcrypto, pg_trgm) are vendored
-- extension functions installed into `public`; they are intentionally left
-- alone — the fix for those is moving extensions to a dedicated schema, which
-- is a deploy-time decision for whoever owns the Supabase project, not a
-- migration that should be forced through here.
-- ----------------------------------------------------------------------------

alter function public.touch_updated_at() set search_path = public, pg_temp;
alter function public.request_claims() set search_path = public, pg_temp;
alter function public.jwt_role() set search_path = public, pg_temp;
alter function public.jwt_sub() set search_path = public, pg_temp;
alter function public.is_trusted_writer() set search_path = public, pg_temp;
alter function public.in_system_context() set search_path = public, pg_temp;
alter function public.safe_uuid(text) set search_path = public, pg_temp;
alter function public.content_moderation_permission(text) set search_path = public, pg_temp;

-- ----------------------------------------------------------------------------
-- Note on random_session_view / random_messages_view (not changed here)
-- ----------------------------------------------------------------------------
-- These two views are intentionally NOT `security_invoker`. random_sessions,
-- random_session_participants and random_messages have no participant-facing
-- SELECT policy on purpose (migration 010: "No participant policies on
-- purpose: participants read random_session_state() and random_session_view,
-- which contain no identities.") — the views themselves do the privacy
-- filtering (`p.user_id = current_profile_id()`) and intentionally run with
-- the view owner's privileges to assemble that projection across both
-- participants' rows. Setting `security_invoker = true` would make the views
-- subject to RLS as the calling student, who has no SELECT policy on the
-- underlying tables at all — every participant would get zero rows and
-- Random Chat's message/session reads would break outright. This is kept as
-- designed; the earlier assumption that these views already had
-- `security_invoker = true` set does not match the migration history and the
-- correct fix is not to add it.

-- ==========================================================================
-- FILE 22/25  20261005000022_022_random_views_invoker_fix.sql
-- ==========================================================================

-- Campus+ migration 022 — restore random_session_view / random_messages_view
-- Supabase CLI filename: 20261005000022_022_random_views_invoker_fix.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- These two views were reported as having been manually switched to
-- `security_invoker = true` directly against a live project during an earlier
-- debugging session (outside of this migration history, so no prior migration
-- file shows it). This migration verifies that claim against real behaviour
-- and, since it is correct, restores the configuration the application
-- actually requires — explicitly, so a future "harden this view" pass does
-- not flip it back without re-reading this comment.
--
-- Verified empirically (not by inspection alone) against a disposable
-- Postgres instance with every migration through 021 applied and real
-- session/message rows:
--
--   default view (security definer semantics, as migration 010 created it):
--     a participant querying random_session_view / random_messages_view for
--     their own session sees their session row and their message — correct.
--
--   same query, same data, with `security_invoker = true` set on both views:
--     the same participant gets ZERO rows back from both views.
--
-- Why: random_sessions, random_session_participants and random_messages have
-- NO participant-facing SELECT policy at all — migration 010 says so in so
-- many words ("No participant policies on purpose: participants read
-- random_session_state() and random_session_view, which contain no
-- identities."). Access control for a participant's own session is enforced
-- by the view body (`p.user_id = current_profile_id()`) and by
-- random_session_state()'s own has_permission/ownership check, not by RLS on
-- the base tables — participant RLS was deliberately never built for these
-- tables. `security_invoker = true` makes a view subject to RLS as the
-- calling role; with no participant policy to pass, every participant query
-- returns nothing. Staff (who do have a `view_random_sessions`-gated SELECT
-- policy on the base tables) would not notice this change — the lobby and
-- message list silently stop working for every real participant, while admin
-- testing still looks fine. That matches a change that can go unnoticed.
--
-- lib/actions/random.js confirms the application depends on exactly this
-- definer behaviour: it queries `random_session_view` / `random_messages_view`
-- directly with no extra ownership filter, trusting the view to scope the
-- rows to the caller. (The `/random` UI route that called these actions was
-- since removed — see migration 023 — but the actions module and this view
-- behaviour are both kept, unreferenced, per the same retention decision.)
--
-- This does not weaken RLS: RLS stays enabled and unchanged on every base
-- table. It restores two views to the access-control design they were built
-- with, which is documented, narrow (no identity columns, no cross-session
-- reads) and already audited (`npm run audit:db` — "Definer views are limited
-- to the two audited Random projections").
-- =============================================================================

alter view public.random_session_view set (security_invoker = false);
alter view public.random_messages_view set (security_invoker = false);

comment on view public.random_session_view is
  'Participant-safe session projection: no participant ids, no usernames, no profile data. '
  'Deliberately NOT security_invoker — see migration 022. The base tables have no participant '
  'SELECT policy on purpose; this view''s own `p.user_id = current_profile_id()` filter is the '
  'access control. Do not add security_invoker to this view without also adding participant-safe '
  'RLS policies to random_sessions and random_session_participants, or every participant query '
  'will silently return zero rows.';

comment on view public.random_messages_view is
  'Participant-safe message stream. `sender_user_id` is mapped to a boolean `mine` flag so the '
  'other student cannot be identified. Deliberately NOT security_invoker — see migration 022; the '
  'same reasoning as random_session_view applies, since random_messages has no participant SELECT '
  'policy either.';

-- ==========================================================================
-- FILE 23/25  20261005000023_023_random_chat_flag_retired.sql
-- ==========================================================================

-- 023: Random Chat removed from the UI — reflect it in the feature flag.
--
-- Random Chat has no nav link, no /random route and no composer anywhere in
-- the app (see lib/constants.js FEATURE_FLAGS for the full rationale). This
-- migration only flips the admin-visible `feature_flags` row so staff see an
-- accurate state in the Admin > Feature flags panel; it is a one-row UPDATE,
-- not a deletion:
--   - random_sessions, random_session_participants, random_messages and their
--     views/functions/RLS policies are all left exactly as they are;
--   - the `use_random_chat`, `moderate_random` and `view_random_sessions`
--     permissions are untouched — moderators still need them to review
--     reports already filed against past sessions;
--   - the moderator "Random reports" queue keeps working against existing data.
-- Nothing in the application currently reads this flag to gate anything (the
-- /random page checked the `use_random_chat` permission directly and no
-- longer exists at all), so this update has no functional effect beyond the
-- admin panel's own display — it exists purely so the control panel doesn't
-- claim a retired feature is still enabled.

update public.feature_flags
set
  label = 'Random (retired — no UI entry point)',
  description = 'Anonymous paired conversations between verified students. Removed from navigation; data and moderation tools are retained.',
  enabled = false
where key = 'random_chat';

-- ==========================================================================
-- FILE 24/25  20261005000024_024_study_partners_and_discovery.sql
-- ==========================================================================

-- Campus+ migration 024 — study partners and discovery
-- Supabase CLI filename: 20261005000024_024_study_partners_and_discovery.sql
-- This file is part of the single authoritative migration history in supabase/migrations/.
-- =============================================================================
-- Campus+ 024 — study partner finder, event submissions, discovery categories
-- =============================================================================
-- Additive only: one new table, two nullable category columns, two new
-- permissions, one feature flag, two RLS policies for student event
-- submissions, and an extended global_search(). No existing object is
-- redefined except global_search(), which keeps its signature.
--
--   Study Partner Finder — explicit opt-in requests. Coarse availability
--     categories only; no calendars, no locations, no presence. Closed and
--     expired requests never appear as active.
--   Events — student submissions land as non-official drafts for staff review;
--     a submission can never publish itself or appear official.
--   Opportunities — nullable discovery category; no workflow change.
-- =============================================================================

-- ----------------------------------------------------------------------------
-- Permissions (mirror lib/constants.js PERMISSIONS + DEFAULT_STUDENT_PERMISSIONS)
-- ----------------------------------------------------------------------------

insert into public.permissions (key, label, description, group_name) values
  ('create_study_posts', 'Create study partner posts', 'Publish opt-in study partner requests.', 'Campus'),
  ('submit_events', 'Submit events', 'Submit community events for staff review (never published as official).', 'Campus')
on conflict (key) do update
  set label = excluded.label, description = excluded.description, group_name = excluded.group_name;

-- Every baseline role holds the student baseline, so all four gain the two keys.
insert into public.role_permissions (role_key, permission_key)
select r.key, p.key
from (values ('student'), ('moderator'), ('admin'), ('super_admin')) as r(key)
cross join (values ('create_study_posts'), ('submit_events')) as p(key)
on conflict do nothing;

-- ----------------------------------------------------------------------------
-- Feature flag (mirrors lib/constants.js FEATURE_FLAGS)
-- ----------------------------------------------------------------------------

insert into public.feature_flags (key, label, description, group_name, enabled) values
  ('study_partners', 'Study partner finder', 'Opt-in subject/exam study requests.', 'campus', true)
on conflict (key) do nothing;

-- ----------------------------------------------------------------------------
-- study_partner_posts — opt-in study requests (separate from team finder)
-- ----------------------------------------------------------------------------

create table public.study_partner_posts (
  id               uuid primary key default gen_random_uuid(),
  title            text not null check (length(btrim(title)) between 3 and 140),
  description      text not null check (length(btrim(description)) between 10 and 1500),
  subject          text not null check (length(btrim(subject)) between 2 and 120),
  purpose          text not null check (purpose in ('subject_study', 'exam_prep', 'collaboration')),
  branch           text check (branch is null or length(branch) <= 80),
  year             text check (year is null or length(year) <= 40),
  academic_context text check (academic_context is null or length(academic_context) <= 200),
  mode             text not null default 'either' check (mode in ('oncampus', 'online', 'either')),
  availability     text[] not null default '{}'
    check (availability <@ array['weekday_morning', 'weekday_afternoon', 'weekday_evening', 'weekend', 'flexible']),
  expires_on       date,
  closed_at        timestamptz,
  status           public.content_status not null default 'published',
  creator_id       uuid not null references public.profiles (id) on delete cascade,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  search_vector    tsvector generated always as (
    to_tsvector('english'::regconfig, coalesce(title, '') || ' ' || coalesce(description, '') || ' ' || coalesce(subject, ''))
  ) stored
);

create index study_partner_posts_status_idx on public.study_partner_posts (status, created_at desc);
create index study_partner_posts_active_idx on public.study_partner_posts (created_at desc)
  where status = 'published' and closed_at is null;
create index study_partner_posts_creator_idx on public.study_partner_posts (creator_id, created_at desc);
create index study_partner_posts_subject_idx on public.study_partner_posts (subject);
create index study_partner_posts_filters_idx on public.study_partner_posts (purpose, mode);
create index study_partner_posts_search_idx on public.study_partner_posts using gin (search_vector);

create trigger study_partner_posts_touch before update on public.study_partner_posts
  for each row execute function public.touch_updated_at();

alter table public.study_partner_posts enable row level security;

-- Active = published, not closed by the creator, not expired, creator in good
-- standing and not blocked either way. Participation is opt-in: only rows a
-- student explicitly published are ever visible to others.
create policy study_posts_select_visible on public.study_partner_posts
  for select to authenticated
  using (
    status = 'published'
    and closed_at is null
    and (expires_on is null or expires_on >= CURRENT_DATE)
    and public.is_active_profile(creator_id)
    and not public.is_blocked_with_current(creator_id)
  );
create policy study_posts_select_own on public.study_partner_posts
  for select to authenticated using (creator_id = public.current_profile_id());
create policy study_posts_select_staff on public.study_partner_posts
  for select to authenticated using (public.has_permission('moderate_all'));
create policy study_posts_insert_own on public.study_partner_posts
  for insert to authenticated
  with check (
    creator_id = public.current_profile_id()
    and public.is_active_user()
    and public.has_permission('create_study_posts')
    and status = 'published'
    and closed_at is null
  );
create policy study_posts_update_own on public.study_partner_posts
  for update to authenticated
  using (creator_id = public.current_profile_id())
  with check (creator_id = public.current_profile_id());
create policy study_posts_update_staff on public.study_partner_posts
  for update to authenticated
  using (public.has_permission('moderate_all'))
  with check (public.has_permission('moderate_all'));
create policy study_posts_delete_own on public.study_partner_posts
  for delete to authenticated using (creator_id = public.current_profile_id());

revoke all on public.study_partner_posts from anon;

-- Column privileges mirror migration 015: narrow UPDATE to editable columns.
revoke update on public.study_partner_posts from authenticated, anon;
grant update (title, description, subject, purpose, branch, year, academic_context,
              mode, availability, expires_on, closed_at, status)
  on public.study_partner_posts to authenticated;

-- ----------------------------------------------------------------------------
-- Discovery categories (nullable, additive — existing rows read as uncategorised)
-- ----------------------------------------------------------------------------

alter table public.events
  add column if not exists category text
    check (category is null or category in
      ('academic', 'cultural', 'sports', 'technical', 'workshop', 'club', 'placement', 'other'));

create index if not exists events_category_idx on public.events (category)
  where status = 'published';

-- Staff manage events through direct updates (migration 015 narrowed UPDATE to
-- an explicit column list), so the new column must be granted to be editable.
grant update (category) on public.events to authenticated;

alter table public.opportunities
  add column if not exists category text
    check (category is null or category in
      ('internship', 'program', 'hackathon', 'competition', 'scholarship',
       'collaboration', 'club_recruitment', 'gig', 'other'));

create index if not exists opportunities_category_idx on public.opportunities (category);

grant update (category) on public.opportunities to authenticated;

-- ----------------------------------------------------------------------------
-- Student event submissions: non-official drafts, staff review, owner withdrawal
-- ----------------------------------------------------------------------------

-- A student submission is always a draft and never official. Publishing stays
-- staff-only through the existing events_update_staff policy.
create policy events_insert_community on public.events
  for insert to authenticated
  with check (
    public.has_permission('submit_events')
    and public.is_active_user()
    and is_official = false
    and status = 'draft'
    and created_by = public.current_profile_id()
  );

-- Submitters can track their own pending drafts; everyone else sees published
-- events (events_select_published) and staff see everything (events_select_staff).
create policy events_select_own on public.events
  for select to authenticated using (created_by = public.current_profile_id());

-- A submitter may withdraw their own unreviewed draft. Anything published is
-- staff-managed history and cannot be deleted by its submitter.
create policy events_delete_own_draft on public.events
  for delete to authenticated
  using (created_by = public.current_profile_id() and status = 'draft' and is_official = false);

-- ----------------------------------------------------------------------------
-- Global search: study & teams scope (signature unchanged)
-- ----------------------------------------------------------------------------

create or replace function public.global_search(
  p_query text,
  p_scope text default 'all',
  p_limit integer default 20,
  p_offset integer default 0
)
returns table (
  scope text,
  id uuid,
  title text,
  subtitle text,
  snippet text,
  url text,
  meta jsonb,
  rank real
)
language sql
stable
security invoker
set search_path = public, pg_temp
as $$
with params as (
  select
    nullif(btrim(coalesce(p_query, '')), '') as q,
    least(greatest(coalesce(p_limit, 20), 1), 50) as lim,
    greatest(coalesce(p_offset, 0), 0) as off,
    coalesce(p_scope, 'all') as scope
),
needle as (
  select
    q,
    lim,
    off,
    scope,
    '%' || replace(replace(q, '%', '\\%'), '_', '\\_') || '%' as like_q,
    websearch_to_tsquery('english', q) as tsq
  from params
  where q is not null and length(q) >= 2
)
select * from (
(
  -- people ------------------------------------------------------------------
  select
    'people'::text as scope,
    p.id,
    p.username as title,
    coalesce(nullif(p.display_name, ''), '@' || p.username) as subtitle,
    coalesce(p.bio, '') as snippet,
    '/user/' || p.username as url,
    jsonb_build_object(
      'branch', case when p.show_branch_year then p.branch else null end,
      'year', case when p.show_branch_year then p.year else null end,
      'reputation_score', p.reputation_score
    ) as meta,
    greatest(
      similarity(p.username, n.q),
      similarity(coalesce(p.display_name, ''), n.q) * 0.8
    )::real as rank
  from public.profiles p, needle n
  where n.scope in ('all', 'people')
    and public.is_active_profile(p.id)
    and not public.is_blocked_with_current(p.id)
    and (p.username ilike n.like_q or p.display_name ilike n.like_q)
  order by rank desc
  limit (select lim from params)
  )
  union all
(
  -- posts & discussions -----------------------------------------------------
  select
    case when po.kind = 'discussion' then 'discussions' else 'posts' end,
    po.id,
    coalesce(po.title, nullif(left(po.body, 80), '')),
    '@' || pr.username,
    left(po.body, 200),
    '/post/' || po.id::text,
    jsonb_build_object(
      'kind', po.kind,
      'is_official', po.is_official,
      'created_at', po.created_at,
      'reaction_count', po.reaction_count,
      'comment_count', po.comment_count
    ),
    ts_rank(po.search_vector, n.tsq)
  from public.posts po
  join public.profiles pr on pr.id = po.author_id
  cross join needle n
  where n.scope in ('all', 'posts', 'discussions')
    and (n.scope <> 'discussions' or po.kind = 'discussion')
    and po.status = 'published'
    and po.deleted_at is null
    and (po.search_vector @@ n.tsq or po.body ilike n.like_q or coalesce(po.title, '') ilike n.like_q)
  )
  union all
(
  -- communities / study groups / clubs --------------------------------------
  select
    case c.kind
      when 'study_group' then 'communities'
      when 'club' then 'clubs'
      else 'communities'
    end,
    c.id,
    c.name,
    case c.kind when 'club' then 'Club' when 'study_group' then 'Study group' else 'Community' end,
    left(c.description, 200),
    case c.kind
      when 'club' then '/campus/clubs/' || c.id::text
      else '/communities/' || c.slug
    end,
    jsonb_build_object('kind', c.kind, 'member_count', c.member_count, 'visibility', c.visibility),
    ts_rank(to_tsvector('english', c.name || ' ' || c.description), n.tsq)
  from public.communities c
  cross join needle n
  where n.scope in ('all', 'communities', 'clubs')
    and (n.scope <> 'clubs' or c.kind = 'club')
    and c.status = 'published'
    and public.can_view_community(c.id)
    and (c.name ilike n.like_q or c.description ilike n.like_q)
  )
  union all
(
  -- marketplace listings ----------------------------------------------------
  select
    'marketplace',
    l.id,
    l.title,
    case when l.is_free then 'Free' else '₹' || coalesce(l.price, 0)::text end,
    left(l.description, 200),
    '/market/listing/' || l.id::text,
    jsonb_build_object('price', l.price, 'is_free', l.is_free, 'condition', l.condition, 'status', l.status),
    ts_rank(l.search_vector, n.tsq)
  from public.marketplace_listings l
  cross join needle n
  where n.scope in ('all', 'marketplace')
    and l.status in ('active', 'reserved')
    and public.feature_enabled('marketplace')
    and (l.search_vector @@ n.tsq or l.title ilike n.like_q)
  )
  union all
(
  -- gigs --------------------------------------------------------------------
  select
    'marketplace',
    g.id,
    g.title,
    'Gig · ' || g.category,
    left(g.description, 200),
    '/market/gigs/' || g.id::text,
    jsonb_build_object('kind', 'gig', 'compensation', g.compensation),
    ts_rank(g.search_vector, n.tsq)
  from public.gigs g
  cross join needle n
  where n.scope in ('all', 'marketplace')
    and g.status = 'published'
    and public.feature_enabled('gigs')
    and (g.search_vector @@ n.tsq or g.title ilike n.like_q)
  )
  union all
(
  -- events ------------------------------------------------------------------
  select
    'events',
    e.id,
    e.title,
    'Event · ' || to_char(e.starts_on, 'DD Mon YYYY'),
    left(e.description, 200),
    '/campus/events/' || e.id::text,
    jsonb_build_object('starts_on', e.starts_on, 'location', e.location),
    ts_rank(e.search_vector, n.tsq)
  from public.events e
  cross join needle n
  where n.scope in ('all', 'events')
    and e.status = 'published'
    and public.feature_enabled('events')
    and (e.search_vector @@ n.tsq or e.title ilike n.like_q)
  )
  union all
(
  -- resources ---------------------------------------------------------------
  select
    'resources',
    r.id,
    r.title,
    coalesce(r.subject, '') || case when r.is_official then ' · Official' else ' · Community' end,
    left(r.description, 200),
    '/explore/resources/' || r.id::text,
    jsonb_build_object('type', r.type, 'is_official', r.is_official),
    ts_rank(r.search_vector, n.tsq)
  from public.official_resources r
  cross join needle n
  where n.scope in ('all', 'resources')
    and r.status = 'published'
    and (r.search_vector @@ n.tsq or r.title ilike n.like_q)
  )
  union all
(
  -- opportunities -----------------------------------------------------------
  select
    'opportunities',
    o.id,
    o.title,
    o.organization || case when o.source = 'official' then ' · Official' else ' · Community' end,
    left(o.description, 200),
    '/explore/opportunities/' || o.id::text,
    jsonb_build_object('deadline', o.deadline, 'mode', o.mode, 'source', o.source),
    ts_rank(o.search_vector, n.tsq)
  from public.opportunities o
  cross join needle n
  where n.scope in ('all', 'opportunities')
    and o.status = 'published'
    and (o.search_vector @@ n.tsq or o.title ilike n.like_q)
  )
  union all
(
  -- projects ----------------------------------------------------------------
  select
    'projects',
    pr.id,
    pr.title,
    pr.technologies,
    left(pr.description, 200),
    '/explore/projects/' || pr.id::text,
    jsonb_build_object('reaction_count', pr.reaction_count),
    ts_rank(pr.search_vector, n.tsq)
  from public.projects pr
  cross join needle n
  where n.scope in ('all', 'projects')
    and pr.status = 'published'
    and (pr.search_vector @@ n.tsq or pr.title ilike n.like_q)
  )
  union all
(
  -- study partner posts (opt-in requests only; closed/expired never match) --
  select
    'study',
    s.id,
    s.title,
    s.subject || ' · ' || case s.purpose
      when 'subject_study' then 'Subject study'
      when 'exam_prep' then 'Exam prep'
      else 'Collaboration'
    end,
    left(s.description, 200),
    '/campus/study/' || s.id::text,
    jsonb_build_object('purpose', s.purpose, 'mode', s.mode, 'subject', s.subject, 'kind', 'study_post'),
    ts_rank(s.search_vector, n.tsq)
  from public.study_partner_posts s
  cross join needle n
  where n.scope in ('all', 'study')
    and s.status = 'published'
    and s.closed_at is null
    and (s.expires_on is null or s.expires_on >= CURRENT_DATE)
    and public.feature_enabled('study_partners')
    and (s.search_vector @@ n.tsq or s.title ilike n.like_q or s.subject ilike n.like_q)
  )
  union all
(
  -- team finder posts ---------------------------------------------------------
  select
    'study',
    t.id,
    t.project_name,
    'Team finder · ' || left(t.required_skills, 60),
    left(t.description, 200),
    '/campus/teams',
    jsonb_build_object('kind', 'team_post'),
    ts_rank(t.search_vector, n.tsq)
  from public.team_posts t
  cross join needle n
  where n.scope in ('all', 'study')
    and t.status = 'published'
    and public.feature_enabled('team_finder')
    and (t.search_vector @@ n.tsq or t.project_name ilike n.like_q)
  )
) results
order by rank desc, title asc
limit (select lim from params)
offset (select off from params);
$$;

comment on function public.global_search(text, text, integer, integer) is
  'Conventional PostgreSQL search across public entities. SECURITY INVOKER so RLS enforces blocks, visibility and privacy.';

-- ==========================================================================
-- FILE 25/25  20261014000025_025_random_confessions.sql
-- ==========================================================================

-- Campus+ 025 — Random Confessions
-- Anonymous public content and its identity mapping are deliberately separate.

alter type public.report_target_type add value if not exists 'confession';

insert into public.permissions (key, label, description, group_name) values
 ('submit_confessions','Submit confessions','Submit anonymous confessions subject to the daily quota.','Social'),
 ('moderate_confessions','Moderate confessions','Review, publish, hide, or reject confession content without seeing author identity.','Moderation'),
 ('reveal_confession_identity','Reveal confession identity','Sensitive safety authority: reveal a confession author with a required, audited reason.','Administration')
on conflict (key) do update set label=excluded.label, description=excluded.description, group_name=excluded.group_name;

insert into public.role_permissions(role_key, permission_key)
select r.key, 'submit_confessions' from public.roles r where r.key in ('student','moderator','admin','super_admin') on conflict do nothing;
insert into public.role_permissions(role_key, permission_key)
select r.key, 'moderate_confessions' from public.roles r where r.key in ('moderator','admin','super_admin') on conflict do nothing;
insert into public.role_permissions(role_key, permission_key)
select r.key, 'reveal_confession_identity' from public.roles r where r.key in ('admin','super_admin') on conflict do nothing;

insert into public.feature_flags(key,label,description,group_name,enabled)
values ('random_confessions','Random Confessions','Anonymous, asynchronous confession feed.','social',true)
on conflict(key) do update set label=excluded.label, description=excluded.description;
insert into public.platform_settings(key,value,description,is_public)
values ('confession_daily_limit','2'::jsonb,'Maximum accepted submissions per profile per Asia/Kolkata calendar day.',true)
on conflict(key) do nothing;

create table public.confessions (
 id uuid primary key default gen_random_uuid(),
 content text not null check (length(btrim(content)) between 10 and 1000 and content=btrim(content)),
 status text not null default 'pending' check(status in ('pending','published','hidden','rejected','removed')),
 submitted_at timestamptz not null default clock_timestamp(),
 published_at timestamptz,
 moderated_at timestamptz,
 moderation_note text check(moderation_note is null or length(moderation_note)<=1000),
 constraint confession_publication_time check ((status='published' and published_at is not null) or status<>'published')
);
create index confessions_public_cursor_idx on public.confessions(published_at desc,id desc) where status='published';
create index confessions_moderation_idx on public.confessions(status,submitted_at asc);

create table public.confession_identities (
 confession_id uuid primary key references public.confessions(id) on delete restrict,
 profile_id uuid not null references public.profiles(id) on delete restrict,
 created_at timestamptz not null default clock_timestamp()
);
create index confession_identities_profile_idx on public.confession_identities(profile_id,created_at desc);

-- A durable ledger means deletion or later moderation can never refund quota.
create table public.confession_daily_quotas (
 profile_id uuid not null references public.profiles(id) on delete restrict,
 ist_day date not null,
 accepted_count integer not null check(accepted_count between 0 and 100),
 updated_at timestamptz not null default clock_timestamp(),
 primary key(profile_id,ist_day)
);

alter table public.confessions enable row level security;
alter table public.confession_identities enable row level security;
alter table public.confession_daily_quotas enable row level security;
-- No direct policies. All access is through narrow RPCs; this also prevents column-level identity leaks.
revoke all on public.confessions, public.confession_identities, public.confession_daily_quotas from anon, authenticated, public;
grant all on public.confessions, public.confession_identities, public.confession_daily_quotas to service_role;

create or replace function public.submit_confession(p_content text)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare
 v_profile uuid := public.current_profile_id(); v_day date := (clock_timestamp() at time zone 'Asia/Kolkata')::date;
 v_limit integer; v_count integer; v_id uuid;
begin
 if v_profile is null or not public.has_permission('submit_confessions') then raise exception 'Not permitted.' using errcode='42501'; end if;
 if p_content is null or length(btrim(p_content)) not between 10 and 1000 then raise exception 'A confession must be between 10 and 1000 characters.' using errcode='22023'; end if;
 v_limit := greatest(1,least(public.setting_int('confession_daily_limit',2),20));
 insert into public.confession_daily_quotas(profile_id,ist_day,accepted_count) values(v_profile,v_day,0)
 on conflict(profile_id,ist_day) do nothing;
 select accepted_count into v_count from public.confession_daily_quotas where profile_id=v_profile and ist_day=v_day for update;
 if v_count >= v_limit then
  return jsonb_build_object('ok',false,'code','daily_quota_exhausted','remaining',0,'limit',v_limit,'ist_day',v_day);
 end if;
 insert into public.confessions(content) values(btrim(p_content)) returning id into v_id;
 insert into public.confession_identities(confession_id,profile_id) values(v_id,v_profile);
 update public.confession_daily_quotas set accepted_count=accepted_count+1,updated_at=clock_timestamp() where profile_id=v_profile and ist_day=v_day returning accepted_count into v_count;
 return jsonb_build_object('ok',true,'id',v_id,'status','pending','remaining',v_limit-v_count,'limit',v_limit,'ist_day',v_day);
end $$;

create or replace function public.confession_quota_status()
returns jsonb language plpgsql stable security definer set search_path=''
as $$ declare v_profile uuid:=public.current_profile_id(); v_day date:=(clock_timestamp() at time zone 'Asia/Kolkata')::date; v_limit integer; v_count integer;
begin
 if v_profile is null then raise exception 'Not permitted.' using errcode='42501'; end if;
 v_limit:=greatest(1,least(public.setting_int('confession_daily_limit',2),20));
 select accepted_count into v_count from public.confession_daily_quotas where profile_id=v_profile and ist_day=v_day;
 return jsonb_build_object('limit',v_limit,'used',coalesce(v_count,0),'remaining',greatest(v_limit-coalesce(v_count,0),0),'ist_day',v_day);
end $$;

create or replace function public.browse_confessions(p_cursor_published_at timestamptz default null,p_cursor_id uuid default null,p_limit integer default 12)
returns table(id uuid,content text,published_at timestamptz) language sql stable security definer set search_path=''
as $$
 select c.id,c.content,c.published_at from public.confessions c
 where c.status='published' and (p_cursor_published_at is null or (c.published_at,c.id)<(p_cursor_published_at,p_cursor_id))
 order by c.published_at desc,c.id desc limit greatest(1,least(coalesce(p_limit,12),24));
$$;

create or replace function public.list_confessions_for_moderation(p_limit integer default 50)
returns table(id uuid,content text,status text,submitted_at timestamptz,published_at timestamptz) language plpgsql stable security definer set search_path=''
as $$ begin
 if not public.has_permission('moderate_confessions') then raise exception 'Not permitted.' using errcode='42501'; end if;
 return query select c.id,c.content,c.status,c.submitted_at,c.published_at from public.confessions c order by (c.status='pending') desc,c.submitted_at asc limit least(greatest(p_limit,1),100);
end $$;

create or replace function public.moderate_confession(p_id uuid,p_status text,p_note text default null)
returns jsonb language plpgsql security definer set search_path=''
as $$ declare v_old text; v_actor uuid:=public.current_profile_id();
begin
 if not public.has_permission('moderate_confessions') then raise exception 'Not permitted.' using errcode='42501'; end if;
 if p_status not in ('published','hidden','rejected','removed') or length(coalesce(p_note,''))>1000 then raise exception 'Invalid moderation request.' using errcode='22023'; end if;
 select status into v_old from public.confessions where id=p_id for update; if v_old is null then raise exception 'Confession not found.' using errcode='22023'; end if;
 update public.confessions set status=p_status,published_at=case when p_status='published' then coalesce(published_at,clock_timestamp()) else published_at end,moderated_at=clock_timestamp(),moderation_note=nullif(btrim(p_note),'') where id=p_id;
 insert into public.moderation_actions(moderator_id,action,target_type,target_id,previous_status,new_status,note) values(v_actor,'moderate_confession','confession',p_id,v_old,p_status,nullif(btrim(p_note),''));
 return jsonb_build_object('ok',true,'id',p_id,'status',p_status);
end $$;

create or replace function public.reveal_confession_identity(p_id uuid,p_reason text)
returns table(profile_id uuid) language plpgsql security definer set search_path=''
as $$ declare v_actor uuid:=public.current_profile_id();
begin
 if not public.has_permission('reveal_confession_identity') then raise exception 'Not permitted.' using errcode='42501'; end if;
 if p_reason is null or length(btrim(p_reason)) not between 20 and 1000 then raise exception 'A specific investigation reason of at least 20 characters is required.' using errcode='22023'; end if;
 insert into public.audit_logs(actor_user_id,action,target_type,target_id,metadata,visibility) values(v_actor,'reveal_confession_identity','confession',p_id,jsonb_build_object('reason',btrim(p_reason)),'admin');
 return query select ci.profile_id from public.confession_identities ci where ci.confession_id=p_id;
end $$;

revoke all on function public.submit_confession(text),public.confession_quota_status(),public.browse_confessions(timestamptz,uuid,integer),public.list_confessions_for_moderation(integer),public.moderate_confession(uuid,text,text),public.reveal_confession_identity(uuid,text) from public,anon;
grant execute on function public.submit_confession(text),public.confession_quota_status(),public.browse_confessions(timestamptz,uuid,integer),public.list_confessions_for_moderation(integer),public.moderate_confession(uuid,text,text),public.reveal_confession_identity(uuid,text) to authenticated,service_role;

-- Preserve the retirement boundary for the old paired Random Chat RPCs.
revoke execute on function public.can_access_random_session(uuid,uuid),public.end_random_session(uuid,text),public.join_random_queue(),public.leave_random_queue(),public.random_other_participant(uuid,uuid),public.random_queue_state(),public.random_session_state(uuid),public.report_random_session(uuid,text,text),public.send_random_message(uuid,text,jsonb) from public,anon,authenticated;

-- ==========================================================================
-- VERIFICATION — reports whether the install is complete (no changes made)
-- ==========================================================================

do $$
declare
  v_auth_triggers integer;
  v_rls integer;
begin
  select count(*) into v_auth_triggers
    from pg_trigger
   where tgname in ('on_auth_user_created', 'enforce_institutional_domain_trigger')
     and not tgisinternal;

  select count(*) into v_rls
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relkind = 'r' and c.relrowsecurity;

  if v_auth_triggers < 2 then
    raise warning 'Campus+ install incomplete: only % of 2 auth.users triggers exist. Sign-in cannot provision accounts until both are created — re-run the section headed "auth hooks" (file 12) from this script.', v_auth_triggers;
  end if;
  if v_rls < 30 then
    raise warning 'Campus+ install incomplete: only % tables in schema public have row level security. Re-run the migration files in order.', v_rls;
  end if;
end $$;

select
  (select count(*) from public.roles)                 as roles,
  (select count(*) from public.permissions)           as permissions,
  (select count(*) from public.role_permissions)      as role_permissions,
  (select count(*) from public.colleges)              as colleges,
  (select count(*) from public.marketplace_categories) as categories,
  (select count(*) from public.feature_flags)         as feature_flags,
  (select count(*) from public.platform_settings)     as platform_settings,
  (select count(*) from pg_class c
     join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind = 'r' and c.relrowsecurity) as tables_with_rls,
  (select count(*) from pg_trigger
    where tgname in ('on_auth_user_created', 'enforce_institutional_domain_trigger')
      and not tgisinternal)                           as auth_triggers,
  (select count(*) from pg_proc p
     join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public')                       as public_functions,
  case
    when (select count(*) from public.roles) >= 4
     and (select count(*) from public.permissions) >= 40
     and (select count(*) from public.platform_settings) >= 10
     and (select count(*) from pg_trigger
           where tgname in ('on_auth_user_created', 'enforce_institutional_domain_trigger')
             and not tgisinternal) = 2
    then 'INSTALL OK — next: sign in once, then npm run role:grant -- --email you@pccoepune.org --role super_admin'
    else 'INCOMPLETE — read the warnings above and docs/DEPLOYMENT.md §3'
  end as verdict;
